  FT["PH-H1651"] = {"id":"PH-H1651","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1957/ra_1817_1957.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"经费拨款法","en":"An Act Appropriating the Sum of One Hundred Thousand Pesos as a Grant to Mrs. Luz B. Magsaysay","orig":"An Act Appropriating the Sum of One Hundred Thousand Pesos as a Grant to Mrs. Luz B. Magsaysay"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 1817","issuingBody":"Congress of the Philippines","promulgatedDate":"1957-06-22","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1957/ra_1817_1957.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1651-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The sum of one hundred thousand pesos is appropriated, out of any funds in the National Treasury not otherwise appropriated, as a grant to Mrs. Luz B. Magsaysay, widow of the late President Ramon Magsaysay. This amount shall be tax exempt."}},{"id":"PH-H1651-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 22, 1957."}}],"pack":"ph-p23"};
  FT["PH-H1652"] = {"id":"PH-H1652","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1957/ra_1818_1957.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"修订第1607号共和国法（即《宣布Intramuros为商业、住宅与教育区，为此废止第171号联邦法与第597号共和国法》）第2条的法案","en":"An Act to Amend Section Two of Republic Act Numbered Sixteen Hundred Seven, Entitled “An Act Declaring Intramuros a Commercial, Residential and Educational District, Repealing for that Purpose Commonwealth Act Numbered One Hundred Seventy-One and Republic Act Numbered Five Hundred Ninety Seven”","orig":"An Act to Amend Section Two of Republic Act Numbered Sixteen Hundred Seven, Entitled “An Act Declaring Intramuros a Commercial, Residential and Educational District, Repealing for that Purpose Commonwealth Act Numbered One Hundred Seventy-One and Republic Act Numbered Five Hundred Ninety Seven”"},"level":"law","status":"active","topics":["trade","education"],"docNumber":"Republic Act No. 1818","issuingBody":"Congress of the Philippines","promulgatedDate":"1957-06-22","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1957/ra_1818_1957.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1652-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Section two of Republic Act Numbered Sixteen hundred seven is amended to read as follows:\n\"Sec. 2. The City Engineer of Manila, with the cooperation of the National Planning Commission or its successors, shall draft the necessary plans for the widening of streets in the Walled City as hereinbelow specified:\n\"Cabildo, which is hereby declared a national road, shall be 30 meters wide with arcade of 4.70 meters; General Luna and Magallanes, 17 meters wide; and Real, 21 meters wide with arcade of 3.80 meters.\""}},{"id":"PH-H1652-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 22, 1957."}}],"pack":"ph-p23","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act to Amend Section Two of Republic Act Numbered Sixteen Hundred Seven, Entitled “An Act Declaring Intramuros a Commercial, Residential and Educational District, Repealing for that Purpose Commonwealth Act Numbered One Hundred Seventy-One and Republic Act Numbered Five Hundred Ninety Seven”","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H1653"] = {"id":"PH-H1653","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1957/ra_1819_1957.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"修订碧瑶市宪章若干条款，规定该市官员新薪级表并增加助理市检察官人数的法案","en":"An Act to Amend Certain Sections of the Charter of the City of Baguio, so as to Provide a New Schedule of Salaries of City Officials of the Said City and to Increase the Number of Assistant City Attorneys","orig":"An Act to Amend Certain Sections of the Charter of the City of Baguio, so as to Provide a New Schedule of Salaries of City Officials of the Said City and to Increase the Number of Assistant City Attorneys"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 1819","issuingBody":"Congress of the Philippines","promulgatedDate":"1957-06-22","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1957/ra_1819_1957.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1653-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Sections two thousand five hundred forty-five-A, two thousand five hundred fifty-one and two thousand five hundred sixty-one of the Revised Administrative Code are amended to read as follows:\n\"Sec. 2545-A. Salaries of city officials. -The officials of the city shall receive the following salaries, payable from the funds of the city:\n\"(a) Mayor, nine thousand pesos per annum.\n\"(b) Vice-mayor, seven thousand two hundred pesos per annum.\n\"(c) Members of the city council, four thousand eight hundred pesos each per annum.\n\"(d) Judge of the municipal court, seven thousand eight hundred pesos per annum.\n\"(e) City treasurer, city engineer, city attorney, city health officer, city auditor, and chief of police, seven thousand two hundred pesos each per annum.\n\"(f) City assessor and superintendent of public utilities, six thousand six hundred pesos each per annum.\n\"(g) Assistant city engineer and assistant city treasurer, six thousand pesos each per annum.\"\n\"Sec. 2251. The vice-mayor. -There shall be a vice-mayor who shall be a member of the city council. During the absence of the mayor from the city or his disability for any reason, the vice-mayor shall discharge the duties of his office and exercise all his powers, except that of removing any officer from office.\"\n\"Sec. 2561. The assistant city attorneys. -There shall be three assistant city attorneys who shall assist the city attorney as he shall direct. The assistant city attorneys shall receive the following compensation:\n\"(a) First assistant, six thousand pesos per annum.\n\"(b) Second assistant, five thousand one hundred pesos per annum.\n\"(c) Third assistant, three thousand seven hundred twenty pesos per annum.\""}},{"id":"PH-H1653-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Section two thousand five hundred sixty-one-A of the Revised Administrative Code and all laws or parts thereof inconsistent herewith are repealed."}},{"id":"PH-H1653-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 22, 1957."}}],"pack":"ph-p23","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act to Amend Certain Sections of the Charter of the City of Baguio, so as to Provide a New Schedule of Salaries of City Officials of the Said City and to Increase the Number of Assistant City Attorneys","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H1654"] = {"id":"PH-H1654","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1957/ra_1820_1957.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"进一步修订政府服务保险法若干条款，将其福利扩大适用于菲律宾结核病协会雇员的法案","en":"An Act to Further Amend Certain Provisions of the Government Service Insurance Act so as to Extend its Benefits to Employees of the Philippine Tuberculosis Society","orig":"An Act to Further Amend Certain Provisions of the Government Service Insurance Act so as to Extend its Benefits to Employees of the Philippine Tuberculosis Society"},"level":"law","status":"active","topics":["labor"],"docNumber":"Republic Act No. 1820","issuingBody":"Congress of the Philippines","promulgatedDate":"1957-06-22","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1957/ra_1820_1957.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1654-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Subsection (a) of section two of the Commonwealth Act Numbered One hundred eighty-six, otherwise known as the Government Service Insurance Act, as amended, is further amended to read as follows:\n\"(a) \"Employer\" shall mean the National or a local government, an agency, board, or corporation controlled or owned by the Government, and shall include the Philippine Tuberculosis Society. ‘Employee’ shall mean any Filipino citizen in the service of an ‘employer’.\""}},{"id":"PH-H1654-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Subsection (a) of section four of the same Act, as amended, is further amended to read as follows:\n\"Sec. 4. Scope of application of System. -(a) Membership in the System shall be compulsory upon all regularly and permanently appointed employees, including judges of the Courts of First Instance and those whose tenure of office is fixed or limited by law; upon all teachers except only those who are substitutes; upon all regular employees of the Philippine Tuberculosis Society, and upon all regular officers and enlisted men of the Armed Forces of the Philippines.\""}},{"id":"PH-H1654-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect as of June sixteen, nineteen hundred and fifty-one.\nApproved: June 22, 1957."}}],"pack":"ph-p23","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act to Further Amend Certain Provisions of the Government Service Insurance Act so as to Extend its Benefits to Employees of the Philippine Tuberculosis Society","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H1655"] = {"id":"PH-H1655","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1957/ra_1821_1957.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"公共工程拨款法","en":"An Act Appropriating Funds for Public Works","orig":"An Act to Amend Certain Items in Republic Act Numbered Fourteen Hundred Eleven, Entitled “An Act Appropriating Funds for Public Works”"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 1821","issuingBody":"Congress of the Philippines","promulgatedDate":"1957-06-22","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1957/ra_1821_1957.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1655-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Items (n), (o), (u), (w) and (aa) of paragraph 4, for the Province of Antique, subsection f, of section two of Republic Act Numbered Fourteen hundred eleven are amended to read as follows:\n\"(n) Iraya Primary School Building, Hamtic Construction ..................................................\n₱5,000.00 \"(o) Mayos Primary School Building, Tibiao Construction ..................................................\n2,000.00 \"(u) Alegre Primary School Building, Tibiao Construction ..................................................\n2,000.00 \"(w) Importante Primary School Building, Tibiao Construction ..................................................\n2,000.00 \"(aa) Santa Justa Elementary School Building, Tibiao Construction ..................................................\n3,000.00\""}},{"id":"PH-H1655-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Items 15, 36, 39, 40, 41, 44, 45, 47 and 57 of subsection d, for the Province of Antique, of section three of the same Act are amended to read as follows:\n\"15.\nMapatag Primary School Building, Hamtic Construction ..................................................\n₱3,000.00 \"36.\nEgaña Elementary School Building, Sibalom Construction ..................................................\n4,000.00 \"39.\nMabini Primary School Building, Sibalom Construction ..................................................\n3,000.00 \"40. lnitan Primary School Building, Sibalom Construction ..................................................\n4,000.00 \"41.\nVillar Elementary School Home Economics Building, Sibalom Construction ..................................................\n2,000.00 \"44.\nIlabas Primary School Building, Sibalom Construction ..................................................\n4,000.00 \"45.\nVillafont Primary School Building, Sibalom Construction ..................................................\n4,000.00 \"47.\nCatmon (Pajarito) Primary School Building, Sibalom Completion ..................................................\n3,000.00 \"57.\nSan Rafael Primary School Building, San Remigio Repair and improvement ..................................................\n2,000.00\""}},{"id":"PH-H1655-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval.\nApproved, June 22, 1957."}}],"pack":"ph-p23","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Appropriating Funds for Public Works","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H1656"] = {"id":"PH-H1656","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1957/ra_1822_1957.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"为特定目的重新划拨第1200号共和国法第一编A部分第4段马尼拉市第183页（ab）目第（19）项所拨款项的法案","en":"An Act Reappropriating for Certain Purposes the Appropriation in Item (19), Page One Hundred Eighty-Three, Sub-Paragraph “Ab,” for the City of Manila, Paragraph 4, Title A, Section One of Republic Act Numbered Twelve Hundred","orig":"An Act Reappropriating for Certain Purposes the Appropriation in Item (19), Page One Hundred Eighty-Three, Sub-Paragraph “Ab,” for the City of Manila, Paragraph 4, Title A, Section One of Republic Act Numbered Twelve Hundred"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 1822","issuingBody":"Congress of the Philippines","promulgatedDate":"1957-06-22","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1957/ra_1822_1957.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1656-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The sum of ten thousand pesos appropriated in item (19), page one hundred eighty-three, subparagraph \"ab,\" for the City of Manila, paragraph 4, title A, section one of Republic Act Numbered Twelve hundred, is hereby reappropriated for the following purposes:\n(1) Sta. Clara Street Asphalting from Lamayan to Havana ₱6,000.00\n(2) Trece de Agosto Street Asphalting from Paz to Estero de Paco 4,000.00"}},{"id":"PH-H1656-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 22, 1957."}}],"pack":"ph-p23","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Reappropriating for Certain Purposes the Appropriation in Item (19), Page One Hundred Eighty-Three, Sub-Paragraph “Ab,” for the City of Manila, Paragraph 4, Title A, Section One of Republic Act Numbered Twelve Hundred","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H1657"] = {"id":"PH-H1657","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1957/ra_1823_1957.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"在特定条件下豁免公司不当累积的利润与盈余缴纳附加公司所得税，为此修订《国家国内税收法典》第25条（a）项的法案","en":"An Act Exempting Under Certain Conditions Profits and Surplus Improperly Accumulated by Corporations from the Additional Corporate Income Tax, Amending for the Purpose Subsection (a), Section Twenty-Five of the National Internal Revenue Code","orig":"An Act Exempting Under Certain Conditions Profits and Surplus Improperly Accumulated by Corporations from the Additional Corporate Income Tax, Amending for the Purpose Subsection (a), Section Twenty-Five of the National Internal Revenue Code"},"level":"law","status":"active","topics":["tax","company"],"docNumber":"Republic Act No. 1823","issuingBody":"Congress of the Philippines","promulgatedDate":"1957-06-22","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1957/ra_1823_1957.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1657-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Subsection (a), section twenty-five of the National Internal Revenue Code, is amended to read as follows:\n\"Sec. 25. Additional tax on corporations improperly accumulating profits or surplus. (a) Imposition of tax. If any corporation, except banks, insurance companies, or personal holding companies, whether domestic or foreign, is formed or availed of for the purpose of preventing the imposition of the tax upon its shareholders or members or the shareholders or members of another corporation, through the medium of permitting its gains and profits to accumulate instead of being divided or distributed, there is levied and assessed against such corporation, for each taxable year, a tax equal to twenty-five per centum of the undistributed portion of its accumulated profits or surplus which shall be in addition to the tax imposed by section twenty-four, and shall be computed, collected and paid in the same manner and subject to the same provisions of law, including penalties, as that tax: Provided , That no such tax shall be levied upon any accumulated profits or surplus, if they are invested in any dollar-producing or dollar-saving industry or in the purchase of bonds issued by the Central Bank of the Philippines.\""}},{"id":"PH-H1657-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 22, 1957."}}],"pack":"ph-p23","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Exempting Under Certain Conditions Profits and Surplus Improperly Accumulated by Corporations from the Additional Corporate Income Tax, Amending for the Purpose Subsection (a), Section Twenty-Five of the National Internal Revenue Code","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H1658"] = {"id":"PH-H1658","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1957/ra_1824_1957.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"经费拨款法","en":"An Act Appropriating One Hundred and Twenty Thousand Pesos to Defray the Expenses of a State Funeral for Ramon Magsaysay and for the Erection of a Temporary Mausoleum to Contain His Remains and to Defray the Funeral and Other Expenses of All the Other Persons in His Party","orig":"An Act Appropriating One Hundred and Twenty Thousand Pesos to Defray the Expenses of a State Funeral for Ramon Magsaysay and for the Erection of a Temporary Mausoleum to Contain His Remains and to Defray the Funeral and Other Expenses of All the Other Persons in His Party"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 1824","issuingBody":"Congress of the Philippines","promulgatedDate":"1957-06-22","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1957/ra_1824_1957.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1658-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The sum of one hundred and twenty thousand pesos, or so much thereof as may be necessary, is hereby appropriated out of any funds in the National Treasury not otherwise appropriated, to defray the expenses of a state funeral for Ramon Magsaysay, the late President of the Philippines, and for the erection of a temporary mausoleum to contain the remains of the great leader and, also, to defray the funeral and other expenses of all the other deceased persons in his party."}},{"id":"PH-H1658-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 22, 1957."}}],"pack":"ph-p23"};
  FT["PH-H1659"] = {"id":"PH-H1659","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1957/ra_1825_1957.html","fetchedAt":"2026-10-06","articleCount":8,"structureMode":"ARTICLE","title":{"zh":"规定食糖绝对配额的分配、再分配与管理的法案","en":"An Act to Provide for the Allocation, Reallocation and Administration of the Absolute Quota on Sugar","orig":"An Act to Provide for the Allocation, Reallocation and Administration of the Absolute Quota on Sugar"},"level":"law","status":"active","topics":["environment"],"docNumber":"Republic Act No. 1825","issuingBody":"Congress of the Philippines","promulgatedDate":"1957-06-22","completenessNote":"全文，共 8 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1957/ra_1825_1957.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1659-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The Sugar Quota Administrator shall allocate annually the quota for unrefined sugar which is a Philippine article as defined in subparagraph (f) of paragraph 1 of the Protocol to the Revised Agreement on Trade and Related Matters between the Republic of the Philippines and the United States of America dated September six, nineteen hundred fifty-five (hereinafter referred to as the Revised Agreement), which may be entered, or withdrawn from warehouse, in the United States for consumption in any calendar year, or part thereof, during the period from January first, nineteen hundred fifty-six to July third, nineteen hundred seventy-four, inclusive, including that required to manufacture the refined sugar, to the sugar-producing mills and plantation owners in the Philippines in the calendar year nineteen hundred forty whose sugars were exported to the United States During such calendar year, or to their successors in interest, proportionately on the basis of their average annual production (or in the case of a successor in interest, the average annual production of his predecessor in interest) for the calendar years nineteen hundred thirty-one, nineteen hundred thirty-two and nineteen hundred thirty-three, and the amount of sugars which may be so exported shall be allocated in each year between each mill and the plantation owners on the basis of the proportion of sugars to which each mill and the plantation owners are respectively entitled."}},{"id":"PH-H1659-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The Sugar Quota Administration shall allocate annually the quota for refined sugar as defined in section 101 of the United States Sugar Act of nineteen hundred thirty-seven, as amended, and which is a Philippine article as defined in subparagraph (f) of paragraph 1 of the Protocol to the Revised Agreement which may be entered or withdrawn from warehouse, in the United States for consumption in any calendar year or part thereof during the period from January first, nineteen hundred fifty-six to July third, nineteen hundred seventy-four, inclusive, to the manufacturers of refined sugars in the Philippines in the calendar year nineteen hundred forty whose refined sugars were exported to the United States during such calendar year, or to their successors in interest, proportionately on the basis of the amount of refined sugars produced by each such manufacturer (or in the case of a successor in interest, the amount of refined sugars produced by his predecessor in interest) which was exported to the United States during the calendar year nineteen hundred forty."}},{"id":"PH-H1659-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"If after the termination of milling in each sugar central in any milling season, the holder of any production allowance or quota is not able to mill enough sugar to fill the same for that year, that amount of such production allowance or quota which he cannot fill during such milling season shall be reallocated without compensation by the Sugar Quota Administration to other quota holders first within the same district, and thereafter the remainder, if any, of such unfilled production allowance or quota shall be reallocated to quota holders in other mill districts in such manner as would insure the filling of the total export quota for that year: Provided, That no reallocation under the provision of this section shall diminish the production allowance or quota to which the holder may be entitled in any subsequent crop year."}},{"id":"PH-H1659-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"The production allowance or quota corresponding to each piece of land under the provisions of this Act shall be deemed to be an improvement attaching to the land entitled thereto. In the absence of a milling contract or contracts, or where such milling contract or contracts shall have expired, such production allowance or quota shall be transferable preferably within the same district in accordance with such rules and regulations as may be issued by the Sugar Quota Office: Provided, That a plantation owner may transfer his production allowance or quota from one district to another when the following conditions exist: (a) when there is no milling contract between the planter and miller or when said contract shall have expired; and (b) when the mill of the district in which the land of the planter lies is not willing to give him the participation laid down in section one of Republic Act Numbered Eight hundred nine regarding the division of shares between the sugar mill and plantation owner."}},{"id":"PH-H1659-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Notwithstanding the provisions of the preceding sections of this Act, any export sugar quota holder actually registered in the Sugar Quota Administration, who does not actually plant and produce sugar in an amount not less than twenty per cent of his production allowance or quota during any crop year after the approval of this Act, unless such failure to plant and produce is due to circumstances or conditions beyond his control, shall have his production allowance or quota permanently cancelled and such production allowance or quota shall be reallocated to other quota holders, firstly, within the same district, and secondly, to other districts in such manner as would insure the filling of the total export quota: Provided, however, That the provision regarding the cancellation of production allowance or quota shall become effective beginning with the crop year nineteen hundred fifty-seven and nineteen hundred fifty-eight."}},{"id":"PH-H1659-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"Any increase in the U.S.-Philippine export quota for sugar which may be allocated by the United States Government to the Philippines shall be pro-rated among the export quota holders in proportion to their allotments as determined under this Act."}},{"id":"PH-H1659-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"All provisions of existing Acts which are inconsistent with the provisions of this Act are hereby repealed."}},{"id":"PH-H1659-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"This Act shall take effect beginning January first, nineteen hundred fifty-six.\nApproved: June 22, 1957."}}],"pack":"ph-p23","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act to Provide for the Allocation, Reallocation and Administration of the Absolute Quota on Sugar","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H1660"] = {"id":"PH-H1660","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1957/ra_1826_1957.html","fetchedAt":"2026-10-06","articleCount":15,"structureMode":"ARTICLE","title":{"zh":"设立学徒培训制度与国家学徒委员会、界定该委员会权力与职责并为此提供资金的法案","en":"An Act Establishing an Apprenticeship Training System and a National Apprenticeship Council, Defining the Powers and Duties of the Said Council and Providing Funds Therefor","orig":"An Act Establishing an Apprenticeship Training System and a National Apprenticeship Council, Defining the Powers and Duties of the Said Council and Providing Funds Therefor"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 1826","issuingBody":"Congress of the Philippines","promulgatedDate":"1957-06-22","completenessNote":"全文，共 15 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1957/ra_1826_1957.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1660-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"This Act shall be known as the \"National Apprenticeship Act of 1957.\""}},{"id":"PH-H1660-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"In order to meet adequately the progressively increasing demand for a skilled-labor force necessary to the industrialization of the Philippines and to increase productivity, it is hereby declared to be the policy of the Government: (1) to establish a national apprenticeship system through the voluntary cooperation of employers and workers and interested governmental and non-governmental agencies; and (2) to provide for the establishment and furtherance of apprenticeship standards to safeguard and promote the welfare of apprentices."}},{"id":"PH-H1660-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The Department of Labor shall, in addition to its duties and functions, perform the following:\n(a) To implement the policy on apprenticeship training as now or may hereafter be declared by Congress;\n(b) To organize and develop an apprenticeship training program by which the requirements for trained labor may be met;\n(c) To secure the cooperation of government agencies and private organizations and institutions, including those providing vocational guidance and training, in effecting coordination in the development of apprenticeship training;\n(d) To recommend appropriate measures for the promotion of apprenticeship training;\n(e) To assist and cooperate in determining the number of apprentices and skilled workers needed for each trade and occupation, and in promoting the proper distribution of manpower to meet the needs of the national economy and the labor requirements of employers so as to achieve the fullest and most effective utilization of manpower resources;\n(f) To enable workers to advance their opportunities or steady employment and to make full use of their natural talents and abilities;\n(g) To establish minimum standards of training in apprenticeable trades and occupations;\n(h) To formulate and adopt standards for effecting the employment of apprentices under different conditions, by setting out their qualifications for employment, number of apprentices, required education, age limitations, aptitudes, terms of apprenticeship, wages, working hours, overtime, vacation with pay, and other matters;\n(i) To lay down minimum standards and procedures for the examination of apprentices, the execution and registration of apprentices and apprenticeship agreements, the methods of supervision and the duration of the apprentices' work on the job and at school, and the methods of examination of apprentices at the end of their training;\n(j) To approve, disapprove, suspend or revoke plant apprenticeship programs and agreements, issue certificates of apprentices, required education, age limitations, apti-occupations in accordance with the rules, regulations and standards promulgated under this Act;\n(k) To promulgate such rules and regulations as may be necessary to carry out the interests and purposes of this Act, including the denial of apprentices to any employer that has violated any provision of this Act, rule or regulation promulgated thereunder, or of any apprentice agreement; and\n(l) To make and submit, not later than February first of each year, a report through the Secretary of Labor of its activities, accomplishments and findings to the President and to the Congress of the Philippines."}},{"id":"PH-H1660-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"The Department of Labor shall:\n(a) Develop and supervise standards in apprenticeship that may be formulated by it and to carry out the apprenticeship program envisioned by this Act;\n(b) Assist and cooperate in the development and formulation of policies, rules, regulations, standards, and plans;\n(c) Promote the purposes of this Act by bringing employers and workers together and assisting them in working out appropriate apprenticeship programs;\n(d) Conduct research in matters affecting apprenticeship and compile and disseminate such research currently;\n(e) Provide technical and advisory services to the several apprenticeship committee, employers, associations of employers, employees, associations of employees, and other interested parties, in the development, maintenance and operation of apprenticeship programs;\n(f) Provide services for the review and appraisal of proposed apprenticeship programs and apprenticeship agreements;\n(g) Maintain a register of apprentices, apprenticeship agreements, and apprenticeship programs;\n(h) Maintain currently a record of all apprenticeship committees and management-labor committees and all employers operating under approved apprenticeship programs;\n(i) Approve, disapprove, suspend, revoke or terminate plant apprenticeship programs and apprenticeship agreements, and issue certificates of apprenticeship;\n(j) Act as a clearing house for the operation of apprenticeship programs in different areas, industries, and occupations;\n(k) Disseminate such information regarding apprenticeship as may be necessary to bring about a better understanding of the purposes of the apprenticeship programs provided by this Act and to arouse public interest in such programs; and\n(l) Protect and promote the welfare of apprentices."}},{"id":"PH-H1660-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Any employer may enter into an apprenticeship agreement with a qualified apprentice. Each apprenticeship agreement shall contain:\n(a) The full names of the contracting parties;\n(b) The date of birth of the apprentice;\n(c) A statement of the trade, craft, or business in which apprenticeship is sought, and the date on which the apprenticeship will begin and end;\n(d) A statement showing the number of hours to be spent by the apprentice in work and the number of hours to be spent in related and supplemental instruction, the total of which hours shall, in no case, be less than those established by the Department of Labor pursuant to this Act: Provided, That the combined weekly hours of work and of the required related and supplemental instruction of the apprentice shall not exceed the maximum number of hours of work prescribed by law for a worker of the age and sex of the apprentice;\n(e) A statement setting forth a schedule of the processes in the trade or industry in which the apprentice is to be taught and the approximate time to be spent in instruction in each process;\n(f) A statement of the graduated scale of wages to be paid the apprentice, the provisions of Republic Act Numbered Six hundred two to the contrary notwithstanding, and whether or not the required school time shall be compensated;\n(g) A statement fixing a period of probation of not more than five hundred hours of employment and of instruction extending not more than four months, during which time the apprenticeship agreement may, at the request of either party in writing, be terminated upon approval of the Department of Labor for good and sufficient cause;\n(h) A provision that an employer who is unable to fulfill his obligation under an apprenticeship agreement may, with the approval of the Department of Labor, transfer such contract to any other employer, if the apprentice consents and such other employer agrees to assume the obligation of said apprenticeship agreement;\n(i) Such additional terms and conditions not inconsistent with this Act, which the Department of Labor determines are necessary and proper to effectuate the purposes of this Act; and\n(j) A clause stating that a copy of the apprenticeship agreement shall be issued without cost to the apprentice."}},{"id":"PH-H1660-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"Every apprenticeship agreement shall be signed by the employer or his agent, or by an authorized representative of an association or group of employers or employees, or by an apprenticeship committee, and by the apprentice; and, if the apprentice is a minor, by the minor's parent or guardian. Where a minor enters into apprenticeship agreement under this Act for a period of training which shall extend into his majority, the apprenticeship agreement shall likewise be binding for such a period as may be covered during the apprentice's majority.\nEvery apprenticeship agreement entered under this Act shall be approved by the parties to the appropriate existing collective bargaining agreement. Each such apprenticeship agreement shall also be approved by the appropriate apprenticeship committee. Where there is no appropriate apprenticeship committee or no collective bargaining agreement, each such apprenticeship agreement shall be approved by the Secretary of Labor, and a copy of each such agreement shall be filed with the Department of Labor."}},{"id":"PH-H1660-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"Upon the complaint of any interested person or upon his own initiative, the Secretary of Labor or his representatives shall investigate any violation of the terms of an apprenticeship agreement made under this Act, and for such purpose he shall hold hearings, inquiries, and other proceedings necessary to such investigations and determinations and issue subpoena and subpoena duces tecum. The parties to such agreement shall, upon reasonable notice thereof, be given a fair impartial hearing. All such hearings, investigations and determinations shall be made pursuant to such rules and procedures as may be prescribed by the Department of Labor."}},{"id":"PH-H1660-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"Any party to an apprenticeship agreement aggrieved by an order or decision of the Secretary of Labor may bring the appropriate proceedings in the courts. The decision of the Secretary of Labor shall be conclusive and final, if action thereon is not filed in court within thirty days after the date of notice of such order or decision.\nNo person shall institute any action for the enforcement of any apprenticeship agreement, or damages for the breach of any such agreement, made under this Act unless he shall first have exhausted all administrative remedies provided by this Act."}},{"id":"PH-H1660-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"To ensure the effective implementation of the policy laid down in section two hereof;\n(A) The National Employment Service shall develop and prepare economic analysis with respect to the several apprenticeship occupations and with respect to the industries involved, and provide appropriate aptitude tests in the selection of apprentices.\n(B) The Department of Education shall:\n(a) Provide related and supplemental instruction for apprentices, secure and furnish facilities, instructional materials, and supplies necessary for such instruction;\n(b) Develop and prepare courses of instruction for apprentices, correlate such instruction with job experience and administer and supervise such instructions;\n(c) Enroll apprentices in schools and keep individual attendance and progress records of such apprentices;\n(d) Employ or otherwise obtain and train apprentice instructors and coordinators;\n(e) Advise and assist the Secretary of Labor and apprenticeship committees regarding training programs;\n(f) Designate, when so required, members of educational advisory committees to the Department of Labor and apprenticeship committees; and\n(g) Assist in the selection of apprentices by the development of appropriate aptitude tests or by providing pre-apprenticeship courses, or both.\nThe Department of Education, with the approval of the Department of Labor, may delegate all or any of the foregoing duties to an appropriate public or private agency: Provided, That the Department of Education shall have a continuing responsibility for the effective performance of such delegated duties."}},{"id":"PH-H1660-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"As used in this Act.—\n(a) The term \"apprentice\" means a worker at least sixteen years of age who is covered by a written apprenticeship agreement with an employer, an association of employers, an organization of workers, or an apprenticeship committee registered with the Apprenticeship Division, which contract provides for not less than two thousand hours of reasonably continuous employment for such worker and for his participation in an approved schedule of work experience through employment and supplemented by related classroom instruction.\nNo person shall work or be engaged as apprentice unless he is at least sixteen years of age; has completed the high school course or such course or courses as the Secretary of Labor may prescribe; and shows his fitness for the employment by means of a certificate of his school attendance, demonstration of his capacities and aptitudes, and presentation of a certificate of his physical fitness by a medical officer of the Bureau of Labor Standards or Bureau of Health.\n(b) The term \"apprenticeship\" means a system of trained systematically in an apprenticeable occupation for contract to employ a worker and to train him or have him trained systematically in an apprenticeable occupation for a certain period, the duration of which has been fixed in advance and in the course of which the apprentice is bound to work in the service of such employer or employers.\n(c) The term \"apprenticeable occupation\" means an occupation which: (1) is customarily learned in a practical way through training on the job; (2) is clearly identified and commonly recognized throughout the industry as a skilled trade or craft; (3) requires two thousand or more hours of work experience to learn; (4) requires related instruction to supplement the work experience; (5) is not a part of a more extensive occupation recognized as apprenticeable by the Department of Labor; (6) involves the development of skills and the use of tools and equipment sufficiently broad to be applicable in like occupations throughout an industry rather than of restricted application to the products of one or more employees in such industry; and (7) is not concerned with selling or distribution of goods; or with managerial, clerical, professional and semiprofessional activities, or with agriculture as defined by Republic Act Numbered Six hundred two, as amended.\n(d) The term \"employ\" includes to suffer or permit to work;\n(e) The term \"employee\" includes any person acting directly or indirectly in the interest of an employer in relation to an employee.\n(f) The term \"industry\" includes a trade, business, industry, or branch thereof, or group of industries, in which individuals are gainfully employed.\n(g) The term \"person\" includes an individual, partnership, association, corporation, business trust, legal representatives, or any organized group of persons."}},{"id":"PH-H1660-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"This Act shall not apply to seamen."}},{"id":"PH-H1660-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"If any provision of this Act or the application of such provision to any person or circumstance shall be held invalid, the remainder of this Act, or the application of any provision thereof to other persons or circumstances shall not be affected thereby."}},{"id":"PH-H1660-A13","no":13,"noLabel":{"en":"Section 13."},"text":{"en":"The sum of one hundred fifty thousand pesos or so much thereof as may be necessary is hereby appropriated out of any funds in the National Treasury not otherwise appropriated, to carry out the purposes of this Act and as a special scholarship fund for the expenditure of apprentices for the fiscal year nineteen hundred fifty-seven to nineteen hundred fifty-eight. Nothing in this Act shall, however, be construed to prevent the acceptance by the Department of Labor of voluntary contributions for the support of apprenticeship and labor-management committees."}},{"id":"PH-H1660-A14","no":14,"noLabel":{"en":"Section 14."},"text":{"en":"All Acts or part of Acts inconsistent with any provision of this Act are hereby repealed."}},{"id":"PH-H1660-A15","no":15,"noLabel":{"en":"Section 15."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 22, 1957."}}],"pack":"ph-p23","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Establishing an Apprenticeship Training System and a National Apprenticeship Council, Defining the Powers and Duties of the Said Council and Providing Funds Therefor","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H1661"] = {"id":"PH-H1661","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1957/ra_1827_1957.html","fetchedAt":"2026-10-06","articleCount":14,"structureMode":"ARTICLE","title":{"zh":"规范在菲律宾国会与任命委员会进行游说的法案","en":"An Act to Regulate Lobbying in the Congress of the Philippines and in the Commission on Appointments","orig":"An Act to Regulate Lobbying in the Congress of the Philippines and in the Commission on Appointments"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 1827","issuingBody":"Congress of the Philippines","promulgatedDate":"1957-06-22","completenessNote":"全文，共 14 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1957/ra_1827_1957.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1661-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Legislative purpose. -The purpose of this Act is to prohibit corrupt or undesirable methods of lobbying, to promote a high standard of ethics in the practice of lobbying, to prevent harassing unfair and unethical lobbying practices, and to provide for the licensing of lobbyists and the suspension or revocation of such licenses."}},{"id":"PH-H1661-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Corrupt means to influence legislation; disclosure of interest. -Any person who shall, directly or indirectly, give or agree or offer to give any money or property or valuable thing or any security therefor to any person, for the service of such person or of any other person in procuring the passage or defeat of any measure before the Congress of the Philippines or before either House or any committee thereof, upon the contingency or condition of the passage or defeat of such measure, or who shall receive, directly or indirectly, or agree to receive any such money, property, thing of value or security therefor for such service, upon any such contingency or condition, or who, having a pecuniary or other interest, or acting as the agent or attorney of any person in procuring or attempting to procure the passage or defeat of any measure before the Congress of the Philippines or before either House or any committee thereof, shall attempt in any manner to influence any member of said Congress for or against such measure, without first making known to such member the real and true interest he has in such measure, either personally or as such agent or attorney, shall be punished by imprisonment of not more than two years or by fine not exceeding five thousand pesos or both such imprisonment and fine."}},{"id":"PH-H1661-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Corrupt or secret means to influence confirmation of appointment. -Any person who shall, directly or indirectly, give or agree or offer to give any money or property or valuable thing or any security therefor to any person, for the service of such person or of any other person in procuring the confirmation or rejection or by-passing of any appointment before the Commission on Appointments or before any committee thereof, upon the contingency or condition of the confirmation or rejection or by-passing of such appointment, or who shall receive, directly or indirectly, or agree to receive any such money, property, thing of value or security therefor for such service, upon any such contingency or condition, or who, having an appointment in his favor pending before the Commission on Appointments or before any committee thereof, shall through secret or clandestine methods attempt in any manner to influence any member of such Commission to vote for confirmation of such appointment, shall be punished by imprisonment of not more than two years or by a fine not exceeding five thousand pesos or both such imprisonment and fine."}},{"id":"PH-H1661-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Definitions. -The following words and phrases shall have the meaning respectively ascribed to them:\n(1) Measure. -Any proposed legislation either in the form of bill, resolution or otherwise or any amendment thereof.\n(2) Lobbying. -The practice of promoting or opposing the introduction or passage of legislation before either House of the Congress of the Philippines or any of its committees, or promoting or opposing the confirmation of any pending appointment before the Commission on Appointments or any of its committees.\n(3) Lobbyist. — Any person who engages in the practice of lobbying for hire except in the manner authorized by section twelve of this Act. Lobbying for hire shall include activities of any officers, agents, attorneys or employees of any principal who are paid a regular salary or retainer by such principal and whose duties include lobbying.\n(4) Unprofessional conduct. — A violation of any of the provisions of this Act, or soliciting employment from any principal, or instigating the introduction of legislation for the purpose of obtaining employment in opposition thereto, or attempt to influence the vote of members of Congress on any measure pending or to be proposed or on any appointment submitted for confirmation by the promise of support or opposition at any future election, or by any other means than a full and fair argument on the merits thereof, or by making public any unsubstantiated charges of improper conduct on the part of any other lobbyist or of any member of Congress, or engaging in practices which reflect discredit on the practice of lobbying or the Congress.\n(5) Principal. —\n(a) Any person, corporation or association which engages a lobbyist or other person in connection with any legislation, pending before the Congress or to be proposed, affecting the pecuniary interest of such person, corporation or association, or in connection with any appointment pending before the Commission on Appointments.\n(b) Any branch or subdivision or instrumentality of the government, including government-owned and government-controlled corporations, which engages a lobbyist or other person in connection with any legislation pending or to be proposed affecting the statutory powers, duties or appropriation of such branch, subdivision, or instrumentality.\n(6) Docket. — The register of licensed lobbyists maintained by the Secretary of the House of Representatives and by the Secretary of the Senate (insofar as Congress is concerned) or by the Secretary of the Commission on Appointments (insofar as said Commission is concerned) pursuant to section seven of this Act.\n(7) Report. — The statement of expenses filed with the Secretary of the House of Representatives and the Secretary of the Senate (insofar as Congress is concerned) or with the Secretary of the Commission on Appointments (insofar as said Commission is concerned) by lobbyists pursuant to section nine of this Act.\n(8) Pecuniary interest. -This term includes without limitation any legislation which creates, alters or repeals any statutory charge by way of tax, license fee, registration fee or otherwise, or which creates, alters or repeals any statutory privilege, power, restriction or obligation of any principal, or which creates, alters or repeals the powers or duties of any court or governmental agency before which the principal does business."}},{"id":"PH-H1661-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Licenses for lobbyists; suspension or revocation.—\n(1) Licenses; fees; eligibility. -Any person of legal age and good and moral character who is a citizen of the Philippines is qualified to be licensed as a lobbyist as herein provided. The Secretary of the House of Representatives and the Secretary of the Senate (insofar as Congress is concerned) or the Secretary of the Commission on Appointments (insofar as said Commission is concerned) shall provide for the form of application for license. Such application may be obtained in the office of the Secretary of either House of Congress or of the Secretary of the Commission on Appointments, as the case may be, and filed therein. No application shall be approved except by unanimous vote of the Secretaries of both Houses insofar as lobbying in Congress is concerned. Upon approval of such application and payment of the license fee of seventy-five pesos to the Secretary of either House or to the Secretary of the Commission on Appointments, as the case may be, a license shall be issued which shall entitle the licensee to practice lobbying on behalf of any one or more principals. Each license shall expire on December thirty-first of the year in which it was issued. No application shall be disapproved without affording the applicant a hearing which shall be held and decision entered within ten days of the date of filing of the application. Denial of a license may be reviewed by mandamus proceeding in the proper court.\n(2) Suspension or revocation of license. -Upon verified complaint in writing charging the holder of a license with having been guilty of unprofessional conduct or with having procured his license by fraud or deceit or through error, the Solicitor General is hereby authorized to bring civil action in the proper Court of First Instance against the holder and in the name of the state as plaintiff to revoke the license. The procedure in such civil action shall be as provided in the Rules of Court. If the court finds for the plaintiff judgment shall be rendered revoking the license and the clerk of the court shall file a certified copy of the judgment with the Secretaries of both Houses or with the Secretary of the Commission on Appointments, as the case may be. If the court shall determine that the complaint made to the Solicitor General was without proper cause, it shall enter judgment against the person making the complaint for the costs of the action with such damages as the court may award. The licensing authority may commence such action on their own motion.\n(3) Suspension of lobbying privileges. -No lobbyist whose license has been suspended or revoked and no person who has been convicted of a violation of any provisions of this Act shall engage in any activity permitted by section twelve hereof until he has been reinstated to the practice of lobbying and duly licensed."}},{"id":"PH-H1661-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"Lobby registry. -Except as provided in section twelve (2) hereof every principal who employs any lobbyist shall within one week after such employment cause the name of said lobbyist to be entered upon the docket. It shall also be the duty of the lobbyist to enter his name upon the docket. Upon the termination of such employment such fact may be entered opposite the name of the lobbyist either by the lobbyist or the principal."}},{"id":"PH-H1661-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"Docket; authorization.—\n(1) The Secretaries of both Houses or the Secretary of the Commission on Appointments, as the case may be, shall prepare and keep a docket in which shall be entered the name and business address of each lobbyist, the name and business address of his principal, and the subject or subjects of legislation or pending appointment to which the employment relates. Such docket shall be a public record and open to the inspection of any citizen upon demand at any time during the regular business hours of the office of the said Secretaries.\n(2) Any principal employing any lobbyist shall when further subjects of legislation or further appointments are submitted which such lobbyist is to promote or oppose, make or cause to be made additional entries in the docket stating such employment so that the docket will show at all times all subjects of legislation or pending appointments in relation to which the lobbyist is employed. The docket may also show the number or designation of bills, resolutions or other measures in relation to which the lobbyist is employed.\n(3) Within ten days after his registration in the docket, a lobbyist shall file with the Secretaries of both Houses or with the Secretary of the Commission on Appointments, as the case may be, a written authorization to act as such signed by his principal."}},{"id":"PH-H1661-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"Restriction on practice of lobbying.—\n(1) No person shall practice as a lobbyist unless he has been duly licensed under the provisions of section five hereof and unless his name appears upon the docket as employed in respect to such matters as he shall be promoting or opposing. No principal shall directly or indirectly authorize or permit any lobbyist employed by him to practice lobbying in respect of any legislation or appointment in which such principal is interested until such lobbyist is duly licensed and the name of such lobbyist is duly entered on the docket. No person shall be employed as a lobbyist for a compensation dependent in any manner upon the passage or defeat of any proposed or pending legislation or upon any other contingency connected with the action of the Congress or of either House thereof or of any committee thereof, or upon the confirmation or rejection or by-passing of any appointment pending before the Commission on Appointments.\n(2) Within five days after delivering any written or printed statement, argument or brief to the entire membership of either or both Houses of Congress, three copies thereof shall be deposited with the Secretaries of both Houses or with the Secretary of the Commission on Appointments, as the case may be."}},{"id":"PH-H1661-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"Reports of lobbyist; reports to Congress.—\n(1) Every lobbyist required to have his name entered upon the docket shall, within ten days after the end of each calendar month of any regular session of Congress, file with the Secretaries of both Houses or with the Secretary of the Commission on Appointments, as the case may be, a sworn statement of expenses made and obligations incurred by himself or any agent in connection with or relative to his activities as such lobbyist for the preceding month or fraction thereof, except that he need not list his own personal living and travel expenses in such statement.\n(2) Within ten days following the beginning of any regular or special session of Congress and on every week thereafter for the duration of such session, the Secretaries of both Houses or the Secretary of the Commission on Appointments, as the case may be, shall from their records report to each House of Congress or to the commission the names of lobbyist registered under section six hereof who were not previously reported, the names of the persons whom they represent as such lobbyist, and the subjects of legislation or appointments in which they are interested. Such reports shall be incorporated into the journal of each House. The Secretaries of both Houses or the Secretary of the Commission on Appointments, as the case may be, shall also forward to each House or to the Commission a copy of each statement required to be filed under subsection (1). Such copy shall be open to public inspection but shall not be incorporated in the journal unless the House or Commission so orders. Any expenditures made or obligations incurred by any lobbyist in behalf of or for the entertainment of any government official or employee concerning pending or proposed legislative matter or pending appointment shall be reported according to the provisions of this section."}},{"id":"PH-H1661-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"Statement of expense by municipal. -Within thirty days after the sine die adjournment of Congress, every principal whose name appears upon the docket or who has employed any person to engage in any activity permitted under section twelve hereof shall file with the Secretaries of both Houses or with the Secretary of the Commission on Appointments, as the case may be, a complete and detailed statement verified under oath by the person making the same, or in the case of a corporation by its president or treasurer, of all expenses paid or incurred by such principal in connection with the employment of lobbyists or in connection with promoting or opposing in any manner the passage by Congress of any legislation affecting the pecuniary interest of such principal, or in connection with any appointment pending before the Commission on Appointments. The accounts shall be rendered in such form as shall be prescribed by the Secretaries of both Houses or by the Secretary of the Commission on Appointments, as the case may be. Such accounts shall be open to public inspection."}},{"id":"PH-H1661-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"Penalties.—\n(1) Any principal violating any of the provisions of sections four to ten hereof (excepting the last sentence in section 8[1], the violation of which is penalized under sections 2 and 3) shall for such offense be fined not less than one thousand pesos nor more than twenty thousand pesos.\n(2) Any lobbyist who shall fail to comply with any of the provisions of said sections or any person who shall act as lobbyist without being duly licensed shall be fined not less than five hundred pesos nor more than ten thousand pesos and shall be disbarred from acting as a lobbyist for the period of three years from the date of such conviction.\n(3) Any lobbyist who fails to make and file the statement required by section nine hereof shall be punished by a fine not to exceed one thousand pesos or by imprisonment not to exceed six months or by both such fine and imprisonment. Any lobbyist who shall file a false statement shall be punished by a fine of not less than one thousand pesos nor more than five thousand pesos or by imprisonment for not less than six months nor more than two years, or both such fine and imprisonment."}},{"id":"PH-H1661-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"Personal lobbying prohibited, exceptions.—\n(1) It shall be unlawful for any person other than a licensed lobbyist to attempt personally and directly to influence any member of Congress to vote for or against any measure pending therein, or to be proposed, or to vote for or against confirmation of any appointment pending before the Commission on Appointments, otherwise than by appearing before the regular committees thereof, when in session, or by newspaper publications, or by public addresses to persons other than members of Congress or Commission on Appointments, as the case may be, or by written or printed statements, arguments or briefs delivered to each member of Congress or Commission on Appointments, as the case may be; Provided, that within five days after delivering such statement, argument or brief, three copies thereof shall be deposited with the Secretaries of both Houses or with the Secretary of the Commission of Appointments, as the case may be. No officer, agent, appointee, or employee, in the service of the government, shall attempt to influence any member of Congress to vote for or against any measure pending therein, affecting the pecuniary interests of such person, excepting in the manner authorized herein in the case of lobbyists. Nothing in this section shall be construed to deprive any citizen not lobbying for hire of his constitutional right to communicate with members of Congress.\n(2) Any person who limits his lobbying solely to appearance before either House of Congress or Commission on Appointments or its committees and registers his appearance on the records of such House or Commission or committee in writing, shall not be required to be licensed as a lobbyist, pay a license fee, register with the Secretaries of both Houses or with the Secretary of the Commission on Appointments, as the case may be, or make any reports of expenditures.\nAny person violating any of the provisions of this section shall be punished by imprisonment of not more than six months or by a fine not exceeding one thousand pesos, or both such imprisonment and fine."}},{"id":"PH-H1661-A13","no":13,"noLabel":{"en":"Section 13."},"text":{"en":"Compensation for published articles on matters pending before Congress to be reported; penalty. -Whenever money or other things of value is paid, or a promise or agreement to pay money or other thing of value is given, to the owner or publisher or any editor, reporter, agent or employee of any newspaper or periodical for the publication therein of any article, editorial or other matter favoring or opposing, or which is intended or tends to favor or oppose, any bill, resolution or other matter pending in the Congress, or any appointment pending in the Commission on Appointments, excepting a paid advertisement showing the name and address of the person authorizing the publication and the amount paid or agreed to be paid therefor, the owner or publisher of such newspaper or periodical shall, within ten days after such publication, file with the Secretaries of both Houses, or with the Secretary of the Commission on Appointments, as the case may be, a statement showing the amount of money or other things of value paid or agreed to be paid and the name and address of the person, firm or corporation from whom such payment or agreement was received.\nViolation of this section shall punishable by a fine of not less than five hundred pesos nor more than ten thousand pesos."}},{"id":"PH-H1661-A14","no":14,"noLabel":{"en":"Section 14."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 22, 1957."}}],"pack":"ph-p23","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act to Regulate Lobbying in the Congress of the Philippines and in the Commission on Appointments","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H1662"] = {"id":"PH-H1662","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1957/ra_1828_1957.html","fetchedAt":"2026-10-06","articleCount":10,"structureMode":"ARTICLE","title":{"zh":"授权开发、开采和利用 Surigao 保留地矿产，并授权菲律宾总统以政府自营、与私营企业合营或聘用承包商方式实施、设立机构及举债发债的法案，并为其他目的","en":"An Act Authorizing the Development, Exploitation and Utilization of the Mineral Deposits in the Surigao Reservation and, for the Purpose, Authorizing the President of the Philippines to Have the Same Undertaken Either by the Government Itself, or Jointly with Private Enterprise, or by Engaging the Services of Independent Contractor or Contractors, to Create an Office or Agency, and to Contract Loans and/or Float Bonds and for Other Purposes","orig":"An Act Authorizing the Development, Exploitation and Utilization of the Mineral Deposits in the Surigao Reservation and, for the Purpose, Authorizing the President of the Philippines to Have the Same Undertaken Either by the Government Itself, or Jointly with Private Enterprise, or by Engaging the Services of Independent Contractor or Contractors, to Create an Office or Agency, and to Contract Loans and/or Float Bonds and for Other Purposes"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 1828","issuingBody":"Congress of the Philippines","promulgatedDate":"1957-06-22","completenessNote":"全文，共 10 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1957/ra_1828_1957.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1662-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Recognizing the importance to the national economy of the development, exploitation and utilization of the mineral deposits in the Surigao Mineral Reservation and the processing and disposition of the minerals that may be produced therefrom, it is hereby declared to be the policy of the Government to undertake such development, exploitation, utilization, processing and disposition either by itself, or jointly with private enterprise, or by engaging and utilizing the services of persons or corporations, as independent contractor or contractors sixty per centum (60%) of the capital stock of which is owned and controlled by persons qualified under the Constitution to exploit, develop and utilize the natural resources of the Philippines. In any case, the foreign exchange derived from the sale of the minerals and/or mineral products produced from the said operations shall belong to the Government except as hereinafter provided."}},{"id":"PH-H1662-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"There is hereby created the Surigao Mineral Reservation Board, hereinafter referred to as the Board, composed of the Chairman of the National Economic Council, as chairman, the Secretary of Agriculture and Natural Resources, the Secretary of Finance, the Secretary of Justice, and the Governor of the Central Bank, as members, who shall carry out and implement the provisions of this Act, which shall be known as the \"Nickel Law.\" It shall have the power and authority to represent the Government in the operations and to insure compliance with the terms and conditions of the operating contract or contracts.\nThe Board is hereby authorized to organize an office and appoint the necessary staff, whose salaries and emoluments shall be fixed by the Board, and to secure the assistance of the personnel of the National Economic Council and other government offices.\nIn order to carry out the policy declared in Section one hereof, the President of the Philippines, is hereby authorized to determine, upon previous advice and recommendation of the Board, whether the development, exploitation and utilization of the said mineral deposit and the processing and disposition of the minerals that may be produced therefrom:\n(1) shall be undertaken by the Government itself, in which case he is authorized to contract loans and/or float bonds in such amounts as he may deem necessary and adequate to carry out effectively the undertakings contemplated in this Act, but not exceeding two hundred million pesos, after consultation with the Monetary Board of the Central Bank and upon recommendation of the National Economic Council; or\n(2) shall be undertaken by the Government jointly with private enterprise, in which case he is also authorized to contract loans and/or float bonds in the amount and in the manner stipulated in the preceding subparagraph (1) Provided, however, That the Government shall, at any one time, own not less than fifty-one per centum of the capital stock of such enterprise; or\n(3) shall have the operation undertaken as hereinabove provided through an independent contractor or contractors who are qualified pursuant to the provisions hereunder, for the entire operation or any part or phrase thereof.\nUnless there are clear advantages in favor of the third mode, either of the first modes shall be preferred: Provided , That in any case, the Board shall implement the policy herein declared.\nShould the President of the Philippines decide to have the operation undertaken through an independent contractor or contractors, as hereinabove provided, the Board may engage and utilize the services or person or corporations, as independent contractor or contractors, with the approval of the President by calling for bids to undertake or perform for the Government any phase or phases of all the operations authorized in this Act covering any particular area or areas within the Surigao Mineral Reservation, and the processing of the minerals produced therefrom, negotiating and entering for such purposes into contract or contracts of service with any party or parties, domestic or foreign, fully qualified as to organization, finances, resources, experience and technical competence, and which may offer such terms and conditions as determined by the Board subject to the approval of the President of the Philippines, to be most advantageous to the Government: Provided , That should there be no bid submitted or the bid or bids submitted are unacceptable, the Board, with approval of the President, is hereby authorized to negotiate with such party or parties, domestic or foreign, as may be fully qualified as to organization, finances, resources, experience and technical competence, for the operation of the whole or part of the Surigao Mineral Reservation under the provisions of this Act: Provided, further, That any provision of existing law to the contrary notwithstanding, the successful bidder, contractor, or operator, may be a corporation formed by one or more corporations organized for the purpose of engaging in mining at least sixty per cent of the capital stock of each of said corporations is owned by Filipino citizens, except where the effect of such interlocking stock ownership is to divest Filipino citizens of the ultimate and actual control of the corporation, in which case the corporation shall be disqualified to be a bidder, contractor, or operator under the provisions of this Act and shall be subject to the penalty prescribed in Section 190 1/7 of the Corporation Law.\nFor the purpose of this Act, a contract of service shall mean an operating contract in which the operator is an independent contractor of service, entitled as such to compensation for services rendered: Provided , That any contractor or contractors of service shall not, by virtue of the contract, acquire any title or interest in the area or areas affected, nor exempt as hereinafter provided in Section five hereof, in any of the minerals from the Surigao Mineral Reservation produced or processed by it.\nThe operator shall furnish as its own cost and expenses all materials, labor, equipment, plants and other installations and processes that may be required for carrying on the operations herein authorized, or necessarily or incident thereto, and all operations, processes, work or acts shall be carried out at operator's own cost and expense: Provided , That all materials, equipment, plants and other installations and/or processes erected, installed, used or placed on the premises subject of the operation, excepting roads, bridges, piers and other similar permanent improvements, shall remain the property of the operator, unless the same are not removed from the premises subject of the operation within one year after the termination of the contract: And provided, further, That this is without prejudice to the Government and operator agreeing on other terms regarding materials, equipment, plants, and other installations and processes.\nSection 2-A. The provisions of section 2 hereof notwithstanding, the President of the Philippines, in the interest of the national economy, may authorize the Bureau of Mines to explore, develop and exploit mineral deposits, other than those of nickel, cobalt and iron, within the Surigao Mineral Reservation, either directly or through a qualified contractor or contractors under an operating contract selected after public bidding or negotiation. The contract herein authorized shall, subject to the approval of the President, be executed by the Secretary of Natural Resources upon recommendation of the Director of Mines. The term of the contract shall be for twenty-five (25) years, renewable for another twenty-five (25) years."}},{"id":"PH-H1662-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The President may grant to the government entity which may operate the Reservation under paragraph one or two of Section two or to the operator under paragraph three of the same section, as the case may be, the following rights and privileges:\n(1) Necessary rights over an area or areas for investigation within the Surigao Mineral Reservation;\n(2) Exemption from laws and regulations relating to: (a) importation of machinery, equipment, accessories, spare parts, and/or supplies and materials necessary for or in connection with said operation or processing of minerals; (b) construction, installation and operation of power plants, including importation of machinery and equipment, accessories, spare parts and/or operating supplies and materials, should the National Power Corporation fail to supply within a reasonable period and at reasonable cost of the power needed in the operation; (c) exportation of such machinery and equipment which were imported solely for construction and installation purposes in connection with the aforesaid operation and processing, and which are no longer needed in the operation;\n(3) Exportation of mineral products produced by the operations: Provided , That all domestic requirements for same shall have first been satisfied;\n(4) Importation upon the sole approval of the Surigao Mineral Reservation Board of highly technical and specialized personnel and executive staff, who may exercise without examination or certification their profession solely for this undertaking subject to such regulations as may be prescribed by the office or agency to be created and designated: And Provided , That if the alien technicians lose their employment, or connection directly or indirectly with the operator, the applicable laws and regulations on immigrants shall apply to such alien technicians and their immediate families; and\n(5) Gratuitous use of timber and water for mining and processing purposes from any parcel or parcels of the Surigao Mineral Reservation subject of the operation."}},{"id":"PH-H1662-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Nothing in this Act provided shall authorize the President of the Philippines:\n(1) To grant to the Operator a contract term exceeding twenty-five years, renewable for an equal period, upon compliance by the Operator with the provisions of this Act and the terms and conditions of the contract;\n(2) To exempt the Operator from the provisions of laws of general application such as those relating to labor, health, safety and the general welfare;\n(3) To exempt the Operator from such measures as the Government may adopt in case and during a period of war or declared national emergency."}},{"id":"PH-H1662-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"The following provisions shall guide the relationship between the Government and the private enterprise holding the minority capital stock and/or its approved contractor as provided for in section two hereof.\n(1) Any minority stockholder and/or contractor shall be entitled to repatriate duly authorized and recognized foreign capital investments, plus interest, and to remit to non-resident investors abroad profits or dividends.\"\n(2) The final area or areas in compact block or blocks, irrespective of water separation of portions, shall be selected sufficient to meet his reasonable needs of the operation as to ore reserves, plant sites, timber and water resources, to assure commercial operations, but in no case to exceed a total land area of twenty-five thousand hectares.\n(3) The rights and obligations of the government and the minority stockholders shall be governed by the shares held by each;\n(4) Philippine citizens shall be given preference in all types of employment within the country insofar as such citizens are qualified to perform the corresponding work with reasonable efficiency and without hazard to the safety of the operations; and effective programs of training and advancement commensurate with the demonstrated abilities of such citizens to perform satisfactorily the various types of work involved in the operation shall be maintained."}},{"id":"PH-H1662-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"Should the President of the Philippines decide to have the operations or any part thereof authorized in this Act done through the services of an independent contractor or contractors, the same shall be, among others, under the following terms and conditions:\n(1) The operator shall be paid for services rendered and expenditures incurred beginning with the end of the first year after the effective date of the contract the sum of one peso (P1.00) per year, and the operator shall receive by way of additional compensation, an amount equivalent to a portion of the gross annual receipts, from all minerals, mineral and metal products, and by-products resulting from the operation, processing and disposition thereof computed such that the Government shall retain nor less than three and one-half per centum of the gross annual receipts, f.o.b., point of exports: Provided , That the operator shall, from the effective date of the contract of operation up to and including the fifth year after commencement of actual production, be exempt from all taxes, duties, fees and charges, both national and local, directly payable by it for any work or activity, equipment, machinery, materials, instruments, supplies, accessories, structures, buildings, lands, improvements, and/or other properties directly connected with or needed and to be used or being used exclusively in the operation, other than those provided in this Act and except those fees and charges that are imposed for work or services actually rendered to the operator: Provided, however, That the operator shall put the area or areas covered by the contract into actual production within five years from the effective date of the contract. Thereafter, penalties may be applied against the operator for failure to effect such production, and/or reach certain levels of production within a specific time period, as may be agreed upon: And, Provided, further, That exemptions from taxes shall not extend to taxes due from the contractor's personnel in their personal capacities;\n(2) The operator shall file a bond to guarantee full and faithful, compliance with all its obligations;\n(3) The operator shall be entitled to repatriate its duly authorized and recognized foreign capital investment, plus interest, and to remit to non-resident investors or stockholders abroad profits or dividends;\n(4) Within one year from the first date of commercial production, the operator shall select a final area or areas in compact block or block, irrespective of water separation of portions to be retained by him sufficient to meet his reasonable needs as to ore reserves, plant sites, timber and water resources to ensure commercial operation, but in no case to exceed a total land area of twenty-five thousand hectares;\n(5) The operator shall give preference to Philippine citizens in all types of employment within the country insofar as such citizens are qualified to perform the corresponding work with reasonable efficiency and without hazard to the safety of the operations; and shall maintain effective programs of training and advancement commensurate with the demonstrated abilities of work involved in the operation. The operator, however, shall not be hindered from using officials of its own selection for executive or technical work and for all other work which, in its judgment, and with the sole approval of the Board, requires highly specialized training and/or long experience;\n(6) The operator and/or its personnel shall be subject to the jurisdiction of the Philippine courts;\n(7) (Repealed by PD 1001, section 3, promulgated September 22, 1976.)\n(8) (Id.)\nSection 6-A. Should the President of the Philippines decide to have the operation or any part thereof conducted as authorized by Section 2-A hereof, the same shall be subject to the following minimum terms and conditions:\n(1) The operator shall pay and guarantee payment to the government out of the gross annual receipts from all minerals, mineral and metal products, and by-products resulting from the operation, processing and disposition of mineral deposits, other than those of nickel, cobalt and iron, a royalty of not less than five per centum (5%) of the said gross annual receipts, F.O.B. points of export beginning with the end of the first year after the effective date of the contract: Provided , That the operator shall from the effective date of the contract up to and including the fifth year commencement of actual production, be exempt from all taxes, duties, fees and charges, both national and local, directly payable by it for any work or activity, equipment, machinery, materials, instruments, supplies, accessories, structures, buildings, lands, improvements, and/or other properties directly connected with or needed and to be used or being used exclusively in the operation, other than those provided in this Act and except those fees and charges that are imposed for work or services actually rendered to the operator: Provided, further, That the operator shall put in operation the area or areas covered by the contract within two (2) years from the effective date of the contract. Thereafter, penalties may be applied against the operator for failure to effect such production and/or reach certain levels of production within specific time periods, as may be agreed upon: Provided , finally, that exemptions from taxes shall not extend to taxes from contractor's personnel in their personal capacities;\n(2) The operator shall furnish all the management, technological and financial services necessary to carry out the operation;\n(3) The operator shall file a bond to guarantee full and faithful compliance with all its obligations;\n(4) The operator shall be entitled to repatriate its duly recognized foreign capital investment, plus interest, and remit to non-resident investors or stockholders, abroad profits or dividends, subject to the regulations of the Central Bank of the Philippines;\n(5) Subject to existing and prior valid rights an operator may enter into one or more contracts with the government for any portion of the reservation with such terms and conditions as may be appropriate under the circumstances: Provided, however, That within (15) years from the effectivity of the operating contract, the operator shall select a final area or areas in compact block or blocks, irrespective of water separation of portion to be retained by him, sufficient to meet his reasonable needs as to ore reserves, plant sites, and water resources to ensure commercial operation, but in no case to exceed an aggregate land area of thirty thousand hectares;\n(6) The operator shall give preference to Philippine citizens in all types of employment within the country in so far as such citizens are qualified to perform the corresponding work with reasonable efficiency and without hazard to the safety of the operation, and shall maintain effective program of training and advancement; and\n(7) All information and data gathered by the operator shall be furnished the Bureau of Mines, and all books of accounts and records shall be open to the government for inspection.\nSection 6-B. Any royalty derived from the government under subparagraph (1) of section 6-A, hereinabove inserted, shall accrue equally to the Surigao Mineral Reservation Board and the Bureau of Mines, and shall be allotted for the undertaking of special projects and for the exploration and development of other mineralized government reservations, respectively."}},{"id":"PH-H1662-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"Negotiations with and proposals to the Philippine Government regarding the operation of the Surigao Mineral Reservation or any portion thereof shall be open to public scrutiny and shall be given publicity consistent with the best interest of the Government."}},{"id":"PH-H1662-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"For the purpose of carrying out the provisions of this Act, the amount of three hundred thousand pesos is hereby appropriated from funds in the National Treasury not otherwise appropriated and the same shall hereafter be included in the General Appropriation Act, to cover the expenses; including salaries, wages, and per diems of the members of the Board and its staff and personnel.\nAny provision of law to the contrary notwithstanding, the Chairman of the Board shall receive a per diem of thirty pesos and the members including the executive secretary thereof each receive a per diem of twenty-five pesos for every meeting actually attended."}},{"id":"PH-H1662-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"All laws inconsistent with the provisions of this Act are hereby amended or repealed."}},{"id":"PH-H1662-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"This Act shall take effect upon its approval.\nApproved, June 22, 1957."}}],"pack":"ph-p23","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Authorizing the Development, Exploitation and Utilization of the Mineral Deposits in the Surigao Reservation and, for the Purpose, Authorizing the President of the Philippines to Have the Same Undertaken Either by the Government Itself, or Jointly with Private Enterprise, or by Engaging the Services of Independent Contractor or Contractors, to Create an Office or Agency, and to Contract Loans and/or Float Bonds and for Other Purposes","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H1663"] = {"id":"PH-H1663","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1957/ra_1829_1957.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"重新开办新怡诗夏省Sabani市镇Bitulok中学，并将其改设为国立农村学校，名称为Sabani Estate农村中学","en":"An Act Reopening the Bitulok High School in the Municipality of Sabani, Province of Nueva Ecija, and Converting the Same into a National Rural School to be Known as the Sabani Estate Rural High School","orig":"An Act Reopening the Bitulok High School in the Municipality of Sabani, Province of Nueva Ecija, and Converting the Same into a National Rural School to be Known as the Sabani Estate Rural High School"},"level":"law","status":"active","topics":["education"],"docNumber":"Republic Act No. 1829","issuingBody":"Congress of the Philippines","promulgatedDate":"1957-06-22","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1957/ra_1829_1957.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1663-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The Bitulok High School in the Municipality of Sabani, Province of Nueva Ecija, is reopened and converted into a national rural school to be known as the Sabani Estate Rural High School."}},{"id":"PH-H1663-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The sum of two hundred thousand pesos is authorized to be appropriated, out of any funds in the National Treasury not otherwise appropriated, for the construction of necessary buildings, operation and maintenance of the said school for the fiscal year ending June thirty, nineteen hundred fifty-eight. Thereafter, the necessary sum for said purpose shall be included in the annual General Appropriations Act."}},{"id":"PH-H1663-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 22, 1957."}}],"pack":"ph-p23","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Reopening the Bitulok High School in the Municipality of Sabani, Province of Nueva Ecija, and Converting the Same into a National Rural School to be Known as the Sabani Estate Rural High School","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H1664"] = {"id":"PH-H1664","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1957/ra_1830_1957.html","fetchedAt":"2026-10-06","articleCount":13,"structureMode":"ARTICLE","title":{"zh":"授予全国甘蔗种植者联合会在菲律宾境内建设、维护和运营私人固定点对点无线电台的临时许可的法案","en":"An Act Granting the National Federation of Sugarcane Planters, a Temporary Permit to Construct, Maintain and Operate Private Fixed Point-to-Point Radio Stations for the Reception and Transmission of Radio Communications Within the Philippines","orig":"An Act Granting the National Federation of Sugarcane Planters, a Temporary Permit to Construct, Maintain and Operate Private Fixed Point-to-Point Radio Stations for the Reception and Transmission of Radio Communications Within the Philippines"},"level":"law","status":"active","topics":["environment"],"docNumber":"Republic Act No. 1830","issuingBody":"Congress of the Philippines","promulgatedDate":"1957-06-22","completenessNote":"全文，共 13 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1957/ra_1830_1957.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1664-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There is hereby granted to the National Federation of Sugarcane Planters, its successors or assigns, a temporary permit to construct, maintain and operate in the Philippines, at such places as the said company may select, subject to the approval of the Department Secretary under whose jurisdiction the Radio Control Division is functioning, or any competent authority who is or shall be authorized to give said approval, such private fixed point-to-point and land-based radio stations for the reception and transmission of wireless messages on radiotelegraphy or radiotelephony, each station to consist of two radio apparatus comprising of a receiving and sending radio apparatus."}},{"id":"PH-H1664-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The President of the Philippines shall have the power and authority to permit the location of said private fixed point-to-point and land-based radio stations or any of them on the public domain upon such terms as may be prescribed."}},{"id":"PH-H1664-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This temporary permit shall continue to be in force during the time that the Government has not established similar service at the places selected by the grantee, and is granted upon the express condition that the same shall be void unless the grantee shall start operation of said stations within one and one-half years from the date of approval of this Act."}},{"id":"PH-H1664-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"The grantee shall not engage in domestic business of telecommunication in the Philippines without further special assent of the Congress of the Philippines, it being understood that the purpose of this temporary permit is to secure to the grantee the right to construct, install, establish and operate private fixed point-to-point and land-based radio stations in places within the Philippines as the interest of the company and its trade and business may justify."}},{"id":"PH-H1664-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"A special right is hereby reserved to the President of the Philippines in time of war, insurrection, public peril, emergency, calamity, or disturbance of peace or order, to cause the closing of the station or stations or to authorize the temporary use or possession thereof by any department of the Government upon payment of just compensation."}},{"id":"PH-H1664-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"No fees shall be charged by the grantee as the radio stations that may be established by virtue of this Act shall engage in communication regarding the grantee's business only."}},{"id":"PH-H1664-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"The grantee, its successors or assigns, shall so construct and operate its radio stations as not to interfere with the operation of other radio stations maintained and operated in the Philippines."}},{"id":"PH-H1664-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"The grantee, its successors or assigns, shall hold the national, provincial, city, and municipal governments of the Philippines, harmless from all claims, accounts, demands or actions arising out of accidents or injuries, whether to property or to persons, cause by the construction or operation of its radio stations."}},{"id":"PH-H1664-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"The grantee shall not lease, transfer, grant the usufruct of, sell or assign this temporary permit, nor the rights or privileges acquired thereunder to any person, firm, company, corporation or other commercial or legal entity nor merge with any other person, company or corporation organized for the same purpose, without the approval of the Congress of the Philippines first had. Any corporation to which this temporary permit may be sold, transferred, or assigned, shall be subject to the corporation laws of the Philippines now existing or hereafter enacted, and any person, firm, company, corporation or other commercial or legal entity to which this temporary permit is sold, transferred, or assigned shall be subject to all conditions, terms, restrictions and limitations of this temporary permit as fully and completely and to the same extent as if the temporary permit had been originally granted to the said person, firm, company, corporation or other commercial or legal entity."}},{"id":"PH-H1664-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"The grantee, its successors or assigns, shall be subject to the corporation laws of the Philippines now existing or hereafter enacted."}},{"id":"PH-H1664-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"The grantee, its successors or assigns, is authorized to operate its private fixed point-to-point radio stations in the medium frequency, high frequency and very high frequency that may be assigned to it by the licensing authority."}},{"id":"PH-H1664-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"This temporary permit shall be subject to amendment, alteration, or repeal by the Congress of the Philippines when the public interest so requires, and shall not be interpreted as an exclusive grant of the privilege herein provided for."}},{"id":"PH-H1664-A13","no":13,"noLabel":{"en":"Section 13."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 22, 1957."}}],"pack":"ph-p23","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Granting the National Federation of Sugarcane Planters, a Temporary Permit to Construct, Maintain and Operate Private Fixed Point-to-Point Radio Stations for the Reception and Transmission of Radio Communications Within the Philippines","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H1665"] = {"id":"PH-H1665","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1957/ra_1831_1957.html","fetchedAt":"2026-10-06","articleCount":22,"structureMode":"ARTICLE","title":{"zh":"规定菲律宾武装部队士兵新的薪金与津贴标准，并废止第 315 号共和国法及经修正的联邦法第 1 号第 89 条与第 91 条的法案","en":"An Act to Provide New Rates of Pay and Allowances for Enlisted Men of the Armed Forces of the Philippines and to Repeal Republic Act Numbered Three Hundred and Fifteen and Sections Eighty-Nine and Ninety-One of Commonwealth Act Numbered One, as Amended","orig":"An Act to Provide New Rates of Pay and Allowances for Enlisted Men of the Armed Forces of the Philippines and to Repeal Republic Act Numbered Three Hundred and Fifteen and Sections Eighty-Nine and Ninety-One of Commonwealth Act Numbered One, as Amended"},"level":"law","status":"active","topics":["defence"],"docNumber":"Republic Act No. 1831","issuingBody":"Congress of the Philippines","promulgatedDate":"1957-06-22","completenessNote":"全文，共 22 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1957/ra_1831_1957.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1665-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"This Act may be cited as the \"Enlisted Men's Pay and Allowances Act of 1957.\""}},{"id":"PH-H1665-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Applicability. —The provisions of this Act shall apply only to enlisted men of the Regular Force: Provided, That the provisions of sections four to thirteen, inclusive, of this Act shall not apply to enlisted men of the Philippine Expeditionary Force to Korea nor to any other Philippine contingent, unit or individual member of the Armed Forces of the Philippines while on duty overseas on a mission involving actual, threatened or anticipated armed hostilities whose rates of pay and allowances shall be as provided in section seventeen hereof: Provided, further, That the provisions of this Act shall apply to reservists only as hereinafter indicated."}},{"id":"PH-H1665-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Enlisted Grades. —The following enlisted grades and the symbols therefor are hereby established:\na. E-7 ......................................................\nMaster Sergeant, First Sergeant, or Chief Petty Officer\nb. E-6 ......................................................\nTechnical Sergeant or Petty Officer, First Class\nc. E-5 ......................................................\nStaff Sergeant or Petty Officer, Second Class\nd. E-4 ......................................................\nSergeant or Petty Officer, Third Class\ne. E-3 ......................................................\nCorporal or Seaman, First Class\nf. E-2 ......................................................\nPrivate First Class or Seaman, Second Class\ng. E-l ......................................................\nPrivate or Apprentice Seaman"}},{"id":"PH-H1665-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Base Pay. —The monthly base pay of enlisted men of the Regular Force shall not be less than the following: a.\nE-7 .................................................................................................\n₱121.00 b.\nE-6 .................................................................................................\n107.00 c.\nE-5 .................................................................................................\n88.00 d.\nE-4 .................................................................................................\n79.00 e.\nE-3 .................................................................................................\n73.00 f.\nE-2 .................................................................................................\n70.00 g.\nE-l ..................................................................................................\n68.00"}},{"id":"PH-H1665-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Longevity Pay. —Enlisted men of the Regular Force shall receive longevity pay according to the number of years of continuous active service heretofore and hereafter rendered, at monthly rates not loss than the following: Provided, That continuous active service of an enlisted man in any of the armed forces of the Philippines, of the United States prior to July four, nineteen hundred forty-six, and/or in recognized guerrilla units, shall be credited in computing the amount of his longevity pay: Provided, further, That if an enlisted man shall reenlist will sixty days from his honorable discharge from a prior enlistment, the years of service rendered in both enlistments shall be added in computing the amount of longevity pay: Provided, finally, That nothing in this A shall be construed as authorizing the payment of any back longevity pay for any period of service heretofore rendered:\nGrade 3-6 Yrs 6-9 Yrs 9-12 Yrs 12-15 Yrs 15-18 Yrs 18-21 Yrs 21-24 Yrs Over 24 Yrs of Services of Services of Services of Services of Services of Services of Services of Services E-7\n2.00\n4.00\n6.00\n9.00\n12.00\n15.00\n18.00\n21.00 E-6\n2.00\n4.00\n6.00\n8.00\n10.00\n13.00\n16.00\n19.00 E-5\n1.00\n3.00\n5.00\n7.00\n9.00\n11.00\n13.00\n15.00 E-4\n1.00\n2.00\n3.00\n4.00\n5.00\n7.00\n9.00\n11.00 E-3\n1.00\n2.00\n3.00\n4.00\n5.00\n6.00\n8.00\n10.00 E-2\n1.00\n2.00\n3.00\n4.00\n5.00\n6.00\n7.00\n9.00 E-1\n1.00\n2.00\n3.00\n4.00\n5.00\n6.00\n7.00\n9.00"}},{"id":"PH-H1665-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"Flying Pay. —Enlisted men of the Air Force, except those receiving air mechanic's pay, hazardous duty pay, combat pay or specialist's pay, when participating in regular and frequent aerial flights pursuant to orders by competent authority shall receive additional pay equivalent to fifty per centum of the base pay prescribed for their respective grades."}},{"id":"PH-H1665-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"Air Mechanic's Pay. —Due to the necessity for technically trained enlisted personnel to properly maintain flying equipment, qualified first, second and third class air mechanics of the Air Force, except those receiving flying pay, hazardous duty pay, combat pay or specialist's pay and not exceeding fifteen per centum of the enlisted strength of the Air Force, when required to properly maintain flying equipment by competent authority, shall receive additional monthly pay of not less than seventy-five pesos, fifty pesos and twenty-five pesos, respectively."}},{"id":"PH-H1665-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"Sea Duty Pay. — Enlisted men of the Navy, except those receiving hazardous duty pay or combat pay, when performing sea duty pursuant to orders by competent authority, shall receive additional pay equivalent to ten per centum of the base pay prescribed for their respective grades."}},{"id":"PH-H1665-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"Hazardous Duty Pay. —Enlisted men, except those receiving flying pay, air mechanic's pay, sea duty pay, combat pay or specialist's pay shall receive additional to fifty per centum of the base pay prescribed by the Secretary of National Defense."}},{"id":"PH-H1665-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"Combat Pay. —Enlisted men, except tose receiving flying pay, air mechanic's pay, sea duty pay, hazardous duty pay or specialist's pay, shall receive additional monthly pay of not less than ten pesos while engaged in combat as defined in regulations prescribed by the Secretary of National Defense."}},{"id":"PH-H1665-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"Specialist's Pay. —Under such regulations the Secretary of National Defense shall prescribe, enlisted men, except those receiving flying pay, air mechanic's pay, hazardous duty pay or combat pay, may be rated as specialist and receive additional monthly pay therefor at rates not less than the following:\nFirst Class ..............................................................................................\n₱75.00 Second Class.........................................................................................\n65.00 Third Class.............................................................................................\n55.00 Fourth Class...........................................................................................\n45.00 Fifth Class...............................................................................................\n35.00 Sixth Class..............................................................................................\n25.00 Seventh Class........................................................................................\n20.00 Eighth Class...........................................................................................\n15.00 Ninth Class.............................................................................................\n10.00"}},{"id":"PH-H1665-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"Overseas duty pay for seamen.—Enlisted men of the Navy when on overseas service as defined in regulations prescribed by the Secretary of National Defense shall receive overseas pay equivalent to fifty per centum of their base pay."}},{"id":"PH-H1665-A13","no":13,"noLabel":{"en":"Section 13."},"text":{"en":"Quarters Allowance.—Under regulation as the Secretary of National Defense may prescribe, each enlisted man not furnished quarters in kind adequate of himself and/or his dependents, shall be granted quarters allowance at monthly rates which shall not be less than the following:\nPROVINCIAL RATES\nCITY RATES\nNumber of Dependents\nNumber of Dependents\nGrade\nNone 1 to 4 5 or more None 1 to 4 5 or more E-7\n20.00\n23.00\n26.00\n30.00\n36.00\n42.00 E-6\n20.00\n23.00\n26.00\n30.00\n36.00\n42.00 E-5\n12.00\n15.00\n18.00\n22.00\n28.00\n34.00 E-4\n12.00\n15.00\n18.00\n22.00\n28.00\n34.00 E-3\n10.00\n13.00\n16.00\n20.00\n26.00\n32.00 E-2\n10.00\n13.00\n16.00\n20.00\n26.00\n32.00 E-1\n10.00\n13.00\n16.00\n20.00\n26.00\n32.00 For purposes of this Act, the following persons are considered to be dependents of an enlisted man: (1) his lawful wife; (2) his unmarried legitimate children who are under twenty-one years of age; (3) his unmarried step-children and adopted children who are under twenty-one years of age and who are in fact dependent upon him; and (4) his unmarried legitimate children, step-children and adopted children, over twenty-one years of age, who are incapable of self-support because of being mentally or physically defective and who are in fact dependent upon him for over half of their respective support. Adequate quarters for enlisted men without dependents shall include bed space, and toilet facilities. Adequate quarters for enlisted men with dependents shall include a bedroom, sala-flining room, kitchenette, bath and toilet facilities."}},{"id":"PH-H1665-A14","no":14,"noLabel":{"en":"Section 14."},"text":{"en":"Subsistence Allowance. —Enlisted, men shall, in addition, be entitled to rations, barracks accommodations, medical attendance, and clothing as may be prescribed in regulations. Each enlisted man not furnished rations in kind shall be granted, under such, regulations as the Secretary of National Defense may prescribe, a basic allowance for subsistence, the value of which shall not be less than one peso per day: Provided, That enlisted men of Navy, while assigned to sea duty pursuant to appropriate orders, shall be given an additional subsistence allowance at the rate of not less than fifty centavos per day."}},{"id":"PH-H1665-A15","no":15,"noLabel":{"en":"Section 15."},"text":{"en":"Clothing Allowance. —Under such regulations as the Secretary of National Defense may prescribe, each enlisted man shall be granted clothing allowance the value of which shall not be less than seventy-five pesos upon original enlistment or reenlistment plus a monthly allowance of not less than ten pesos, and an additional twenty upon each reenlistment entered into within two months after his diacharge by reason of the expiration of the enlisted."}},{"id":"PH-H1665-A16","no":16,"noLabel":{"en":"Section 16."},"text":{"en":"Laundry Allowance. —Under such regulation as the Secretary of National Defense may prescribe enlisted men whose regular duties require frequent appearances in public or frequent attendance at ceremonies shall be granted laundry allowance at the rate of not less than eight pesos per month."}},{"id":"PH-H1665-A17","no":17,"noLabel":{"en":"Section 17."},"text":{"en":"Pay and Allowances of Enlisted men of the Philippine Expeditionary Force to Korea, hereinafter referred to as PEFTOK and any other Philippine contingent. —Enlisted men of PEFTOK and any other Philippine contingent, unit or individual member of the Armed Forces of the Philippines, while on overseas duty on a mission involving actual, threatened or anticipated armed hostilities, shall receive the following:\na. Monthly base pay, overseas pay and quarters allowance the total of which shall not exceed the following:\nE-7........................................................................................\n₱420.00 E-6........................................................................................\n375.00 E-5........................................................................................\n291.00 E-4........................................................................................\n261.00 E-3........................................................................................\n225.00 E-2........................................................................................\n195.00 E-1........................................................................................\n180.00\nb. Overseas Duty Bonus. —Upon return to the Philippines of any enlisted man from service overseas to shall receive an overseas duty bonus of one hundred pesos: Provided, That payment of the overseas duty bonus shall not be made to any person more than once: Provided, further, That no payment of the bonus shall be made to any person who has been found guilty of a violation of Articles of War (C. A. No. 408, as amended) 59, 60, 67, 76, 77, 78, 79, 82, 83, 87, or 93, or is awaiting trial by court martial for violation of such Articles, or is returned to the Philippines for discharge under conditions other than honorable.\nc. Family Subsistence Allowance. —The spouse, or in default of the spouse, the children, or in default of such spouse, and children, the parents, or in default of such spouse, children, and parents, the dependents for support of an enlisted man, shall receive a family subsistence allowance at the following rates:\nE-7........................................................................................\n₱480.00 E-6........................................................................................\n420.00 E-5........................................................................................\n340.00 E-4........................................................................................\n300.00 E-3........................................................................................\n260.00 E-2........................................................................................\n220.00 E-1........................................................................................\n200.00 Such family subsistence allowance shall be paid only once upon departure of the enlisted man from the Philippines for service overseas. The family subsistence allowance advanced or to be paid to the enlisted man shall be computed on the basis of their respective grades at the time of their departure from the Philippines: Provided, That if the cash advance already made to any enlisted man of the 10th or 20th BCT shall exceed his family subsistence allowance as prescribed above, such enlisted man shall not be required to reimburse the difference.\nd. Enlisted men of PEFTOK and any other Philippine contingent, unit or individual member of the Armed Forces of the Philippines while on duty overseas shall be entitled to rations, barracks accommodations, medical attendance, clothing, and subsistence allowance as are provided by laws and regulations of general application to listed personnel of the AFP. They shall be furnished Equate winter and other protective clothing and additional rations and subsistence allowance as may be provided in appropriations for this purpose.\ne. Except as otherwise specifically provided in this section, enlisted men of the PEFTOK and any other Philipine contingent, unit or individual member of the Armed Forces of the Philippines while on duty overseas shall be disqualified from receiving the pay and allowances of other enlisted men of the Regular Force as provided for in sections four to thirteen of this Act. No longevity pay shall be paid to any enlisted man of PEFTOK and any other Philippine contingent, unit or individual member of the Armed Forces of the Philippines while on duty overseas: Provided, That any period of service rendered as a member of PEFTOK and any other Philippine contingent, unit or individual member of the Armed Forces of the Philippines while on duty overseas shall be credited in the computation of longevity pay provided for in section five of this Act when such enlisted man shall again become entitled to longevity pay by virtue of his relief from overseas duty."}},{"id":"PH-H1665-A18","no":18,"noLabel":{"en":"Section 18."},"text":{"en":"Grades, Pay and Allowances of Reservists. —Grades, pay and allowances, of reservists shall be the same as those of enlisted men of the Regular Force: Provided, That reservists shall receive no pay or allowances while on inactive status: Provided, further, That reservists on annual active duty training shall receive pay and allowances as may be prescribed by the President: And provided, also, That in time of emergency, where a partial or full mobilization has been declared by the President, reservists called to active duty shall be entitled to the same rates of pay and allowances prescribed for enlisted men of the Regular Force."}},{"id":"PH-H1665-A19","no":19,"noLabel":{"en":"Section 19."},"text":{"en":"Pay and Allowances of Trainees. —Young men undergoing trainee instruction shall receive a monthly base pay of not less than ten pesos, in addition to meal and barracks accommodations, medical and dental attendance, clothing and transportation: Provided, That under such regulations as the Secretary of National may prescribe each trainee shall receive clothing allowance the value of which shall not be less than seventy-five pesos: And provided, further, That any trainee who may serve with the colors longer than ten months, except for those who may be required by regulations to serve additional periods as a result of their misconduct or unauthorized absences during their normal trainee instruction, shall receive pay and allowances at the same SJarribed for enlisted men of the Regular Force."}},{"id":"PH-H1665-A20","no":20,"noLabel":{"en":"Section 20."},"text":{"en":"The total number of enlisted men authorized in each grade shall be as the President may direct. The President in case of national emergency may prescribe new rates of pay and allowances of enlisted men and trainees of the Armed Forces of the Philippines, which shall not be less than the rates prescribed in this Act."}},{"id":"PH-H1665-A21","no":21,"noLabel":{"en":"Section 21."},"text":{"en":"Repealing Clause .—This Act repeals Republic Numbered Three hundred fifteen, and sections eighty-nine and ninety-one of Commonwealth Act Numbered One, as amended, and so much of sections four, five and flve-A of Republic Act Numbered Five hundred seventy-three and section one of Republic Act Numbered Eight hundred fifteen as pertain to pay and allowances of enlisted men of the PEFTOK."}},{"id":"PH-H1665-A22","no":22,"noLabel":{"en":"Section 22."},"text":{"en":"Date of effectivity.—This Act shall take effect on July one, nineteen hundred fifty-seven and has no retroactive effect.\nApproved, June 22, 1957."}}],"pack":"ph-p23","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act to Provide New Rates of Pay and Allowances for Enlisted Men of the Armed Forces of the Philippines and to Repeal Republic Act Numbered Three Hundred and Fifteen and Sections Eighty-Nine and Ninety-One of Commonwealth Act Numbered One, as Amended","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H1666"] = {"id":"PH-H1666","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1957/ra_1832_1957.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":"修订第514号共和国法（即《授予Mindanao Colleges设立无线电广播站临时许可法》）的法案","en":"An Act to Amend Republic Act Numbered Five Hundred Fourteen, Entitled “An Act Granting the Mindanao Colleges a Temporary Permit to Establish a Radio Broadcasting Station”","orig":"An Act to Amend Republic Act Numbered Five Hundred Fourteen, Entitled “An Act Granting the Mindanao Colleges a Temporary Permit to Establish a Radio Broadcasting Station”"},"level":"law","status":"active","topics":["education"],"docNumber":"Republic Act No. 1832","issuingBody":"Congress of the Philippines","promulgatedDate":"1957-06-22","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1957/ra_1832_1957.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1666-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Section one of the Republic Act Numbered Five hundred fourteen is amended to read as follows:\n\"Sec. 1. There is hereby granted to the Mindanao Colleges, hereinafter referred to as the 'grantee', a temporary permit to construct, maintain and operate in the Philippines at such places as the said grantee may select, subject to the approval of the Secretary of Public Works and Communications, radio broadcasting stations for commercial and educational purposes.\""}},{"id":"PH-H1666-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Section two of the same Act is likewise amended to read as follows:\n\"Sec. 2. This temporary permit shall continue to be in force during the time that the Government has not established similar services at the places selected by the grantee, and is made upon the express condition that the same shall be avoid unless the construction of said stations be begun within one and a half years from the approval of this amendatory Act.\""}},{"id":"PH-H1666-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Whenever the words \"station\" and \"Secretary of Commerce and Industry\" appear in Republic Act Numbered Five hundred fourteen, the same shall read \"stations\" and \"Secretary of Public Works and Communications,\" respectively."}},{"id":"PH-H1666-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 22, 1957."}}],"pack":"ph-p23","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act to Amend Republic Act Numbered Five Hundred Fourteen, Entitled “An Act Granting the Mindanao Colleges a Temporary Permit to Establish a Radio Broadcasting Station”","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H1667"] = {"id":"PH-H1667","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1957/ra_1833_1957.html","fetchedAt":"2026-10-06","articleCount":15,"structureMode":"ARTICLE","title":{"zh":"授予 Baldomero A. David 先生在菲律宾建设、维护和运营公共海岸无线电台及服务所需其他无线电台的临时许可的法案","en":"An Act Granting Mr. Baldomero A. David, Residing at San Jose, Navotas, Rizal, a Temporary Permit to Construct, Maintain and Operate Public Coastal Radio Stations in the Philippines, Together with Such Other Radio Stations as May be Necessary for the Operation of the Service, Such as Fixed and Land Based Radio Stations, for the Reception and Transmission of Radio Communications Within the Philippines not at Present Served by Government-Owned Public Radiotelegraph or Radiotelephone Systems","orig":"An Act Granting Mr. Baldomero A. David, Residing at San Jose, Navotas, Rizal, a Temporary Permit to Construct, Maintain and Operate Public Coastal Radio Stations in the Philippines, Together with Such Other Radio Stations as May be Necessary for the Operation of the Service, Such as Fixed and Land Based Radio Stations, for the Reception and Transmission of Radio Communications Within the Philippines not at Present Served by Government-Owned Public Radiotelegraph or Radiotelephone Systems"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 1833","issuingBody":"Congress of the Philippines","promulgatedDate":"1957-06-22","completenessNote":"全文，共 15 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1957/ra_1833_1957.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1667-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There is hereby granted to Mr. Baldomero A. David, residing at San Jose, Navotas, Rizal, his successors or assigns, hereinafter referred to as the \"grantee,\" a temporary permit to construct, maintain and operate in the Philippines at such places as said grantee may select, subject to the approval of the Secretary of Public Works and Communications or any competent authority who is nor shall be authorized now or in the future to give such approval, public coastal radio stations, together with such other radio stations as may be necessary for the operation of the service, such as fixed and land based radio stations, for the reception and transmission of wireless messages on radiotelegraphy and/or radiotelephony with vessels at sea: Provided, However , That the grantee shall establish and operate such stations in places not at present served by public radiotelegraph or radiotelephone systems owned by the Government."}},{"id":"PH-H1667-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The President of the Philippines shall have the power and authority to permit the location of any or all of the radio stations that may be established under this permit on the public domain upon such terms as he may prescribe."}},{"id":"PH-H1667-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This grant shall continue to be in force during the time that the Government has not established a similar public coastal radio service at the places selected by the grantee, in no case to exceed fifty years, and is made upon the express condition that the same shall be void unless the construction of at least one public coastal radio station be begun within two years from the date of approval of this Act and be completed within three years from said date."}},{"id":"PH-H1667-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"A special right is hereby reserved to the President of the Philippines, in time of war, insurrection, public peril or calamity or domestic trouble, to cause the closing of the radio stations, or to authorize the temporary use or possession thereof by any department of the Government upon payment of just compensation."}},{"id":"PH-H1667-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"The grantee, his successors or assigns, shall hold the national, provincial, and municipal governments of the Philippines harmless from all claims, accounts, demands or actions arising out of accidents or injuries whether to property or to persons caused by the construction or operation of the stations by the grantee, his successors or assigns."}},{"id":"PH-H1667-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"The stations of the grantee shall be constructed and operated in accordance with the established engineering standards and practice and subject to existing radio laws and regulations, and the frequencies or wave lengths shall be selected with a view to avoiding interference with the operation of other radio stations in the Philippines."}},{"id":"PH-H1667-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"No private property shall be taken for any purpose by the grantee without proper condemnation proceedings and just compensation paid or tendered therefore, and any authority to take and occupy land contained herein shall not apply to the taking, use or occupation of any land except such as is required for the actual necessary purpose for which this permit is granted."}},{"id":"PH-H1667-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"The right is hereby reserved to the Government of the Philippines, through the Public Service Commission or such other government agency as may hereafter be duly authorized, to fix the maximum rates or charges to be charged by the grantee."}},{"id":"PH-H1667-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"The grantee shall keep an account of the gross receipts of the business transacted by him and shall furnish the Auditor General and the National Treasurer of the Philippines a copy of such account not later than the thirty-first day of January each year for the preceding year. For the purpose of auditing the accounts rendered to the Auditor General and the National Treasurer, all the books and accounts of the grantee, or duplicates thereof, shall be subject to the official inspection of the Auditor General or his authorized representatives, and the audit and approval of such accounts by said officers shall be final and conclusive evidence as to the amount of said gross receipts, except that the grantee shall have the right to appeal to the courts of the Philippines under the terms and conditions provided in the laws of the Philippines."}},{"id":"PH-H1667-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"As a condition of the granting of this permit, the grantee shall execute a bond in favor of the Government of the Philippines in the sum of fifty thousand pesos, in form and with sureties satisfactory to the Secretary of Public Works and Communications or other competent authority, conditioned upon the faithful performance of the grantee's obligations hereunder during the first three years of the life of this permit. If after three years from the date of the acceptance of this permit, the grantee shall have fulfilled the same, the bond aforesaid shall be cancelled by the Secretary of Public Works and Communications or other competent authority."}},{"id":"PH-H1667-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"Acceptance of this permit shall be given in writing within six months after approval of this Act. When so accepted by the grantee and upon the approval of the bond aforesaid by the Secretary of Public Works and Communications or other competent authority, the grantee shall be empowered to exercise the privileges granted thereby."}},{"id":"PH-H1667-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"The grantee shall not lease, transfer, grant the usufruct of, sell or assign this permit, nor the rights or privileges acquired thereunder to any person, firm, company, corporation or other commercial or legal entity, nor merge with any other person, firm, company or corporation organized for the same purpose, without the approval of the Congress of the Philippines first had. Any corporation to which this permit may be sold, transferred, or assigned shall be subject to the corporation laws of the Philippines now existing or hereafter enacted, and any person, firm, company, corporation or other commercial or legal entity to which this permit is sold, transferred, or assigned shall be subject to all conditions, terms, restrictions and limitations of this permit as fully and completely and to the same extent as if the permit had been originally granted to the said person, firm, company, corporation or other commercial or legal entity."}},{"id":"PH-H1667-A13","no":13,"noLabel":{"en":"Section 13."},"text":{"en":"The permit hereby granted shall be subject to amendment, alteration or repeal by the Congress of the Philippines when the public interest so requires, and the rights to use and occupy public property and places hereby granted shall revert to the respective government upon termination of this permit by such repeal, amendment or alteration, or by forfeiture or expiration in due course."}},{"id":"PH-H1667-A14","no":14,"noLabel":{"en":"Section 14."},"text":{"en":"This permit shall not be interpreted to mean an exclusive grant of the privileges herein provided for."}},{"id":"PH-H1667-A15","no":15,"noLabel":{"en":"Section 15."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 22, 1957."}}],"pack":"ph-p23","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Granting Mr. Baldomero A. David, Residing at San Jose, Navotas, Rizal, a Temporary Permit to Construct, Maintain and Operate Public Coastal Radio Stations in the Philippines, Together with Such Other Radio Stations as May be Necessary for the Operation of the Service, Such as Fixed and Land Based Radio Stations, for the Reception and Transmission of Radio Communications Within the Philippines not at Present Served by Government-Owned Public Radiotelegraph or Radiotelephone Systems","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H1668"] = {"id":"PH-H1668","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1957/ra_1834_1957.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":"修订第872号共和国法的法案","en":"An Act to Amend Republic Act Numbered Eight Hundred and Seventy-Two","orig":"An Act to Amend Republic Act Numbered Eight Hundred and Seventy-Two"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 1834","issuingBody":"Congress of the Philippines","promulgatedDate":"1957-06-22","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1957/ra_1834_1957.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1668-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Section one of Republic Act Numbered Eight hundred and seventy-two is hereby amended to read as follows:\n\"Sec. 1. Subject to the conditions established in this Act and the provisions of Commonwealth Act Numbered One hundred and forty-six, as amended, and of the Constitution, applicable thereto, there is hereby granted to Artemio G. Ilano, hereinafter called the grantee, his successors or assigns, for a period of fifty years from the approval of this Act, the right and privilege to construct, maintain and operate in the cities of Cavite, Trece Martires, and Tagaytay, and the Province of Cavite, hereinafter referred to as the cities and province, a telephone and radiophone system to carry on the business of electrical transmission of conversations and signals in said cities and province. For this purpose, the grantee is hereby authorized to use all streets and public thoroughfares of the said cities and province for the construction and maintenance, and operation of all apparatus, conductors, and appliances necessary for the electrical transmission of conversations and signals, to erect poles, string wires, build conduits, lay cables, and to construct, maintain, and use such other approved and generally accepted means of electrical conduction in, on, over, or under the public roads, highways, lands, bridges, streets, lanes, and sidewalks of said cities and province, and overhead or underground lines or on the surface of the ground as may be necessary and best adapted to said transmission.\""}},{"id":"PH-H1668-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"All references in subsequent sections of the said Act to \"telephone and to \"City of Cavite\" are hereby amended to read \"telephone and radiophone\" and \"cities of Cavite, Trece Martires, and Tagaytay and the Province of Cavite,\" respectively."}},{"id":"PH-H1668-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The title of said Act is hereby amended to read as follows: \"An Act granting Artemio G. Ilano a franchise to install, operate and maintain a telephone and radiophone system in the cities of Cavite, Trece Martires, and Tagaytay and the Province of Cavite.\""}},{"id":"PH-H1668-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 22, 1957."}}],"pack":"ph-p23","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act to Amend Republic Act Numbered Eight Hundred and Seventy-Two","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H1669"] = {"id":"PH-H1669","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1957/ra_1835_1957.html","fetchedAt":"2026-10-06","articleCount":15,"structureMode":"ARTICLE","title":{"zh":"授予 Honorio G. Reyes 先生在菲律宾建设、维护和运营公共海岸无线电台及服务所需其他无线电台的临时许可的法案","en":"An Act Granting Mr. Honorio G. Reyes, Residing at Four Hundred Seventy-Six Laong-Laan, Sampaloc, Manila. a Temporary Permit to Construct, Maintain and Operate Public Coastal Radio Stations in the Philippines, Together with Such Other Radio Stations as May be Necessary for the Operation of the Service, Such as Fixed and Land Base Radio Stations, for the Reception and Transmission of Radio Communications Within the Philippines not at Present Served by Public Radiotelegraph or Radiotelephone Systems","orig":"An Act Granting Mr. Honorio G. Reyes, Residing at Four Hundred Seventy-Six Laong-Laan, Sampaloc, Manila. a Temporary Permit to Construct, Maintain and Operate Public Coastal Radio Stations in the Philippines, Together with Such Other Radio Stations as May be Necessary for the Operation of the Service, Such as Fixed and Land Base Radio Stations, for the Reception and Transmission of Radio Communications Within the Philippines not at Present Served by Public Radiotelegraph or Radiotelephone Systems"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 1835","issuingBody":"Congress of the Philippines","promulgatedDate":"1957-06-22","completenessNote":"全文，共 15 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1957/ra_1835_1957.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1669-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There is hereby granted to Mr. Honorio G. Reyes, residing at four hundred seventy-six Laong-Laan, Sampaloc, Manila, his successors or assigns, hereinafter referred to as the \"grantee,\" a temporary permit to construct, maintain and operate in the Philippines at such places as said grantee may select, subject to the approval of the Secretary of Public Works and Communications or any competent authority who is or shall be authorized now or in the future to give such approval, public coastal radio stations, together with such other radio stations as may be necessary for the operation of the service, such as fixed and land base radio stations, for the reception and transmission of wireless messages as radiotelegraphy and/or radiotelephony with vessels at sea: Provided, However, That the grantee shall establish and operate such stations in places not at present served by public radiotelegraph or radiotelephone systems."}},{"id":"PH-H1669-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The President of the Philippines shall have the power and authority to permit the location of any or all the radio stations that may be established under this permit on the public domain upon such terms as he may prescribe."}},{"id":"PH-H1669-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This grant shall continue to be in force during the time that the Government has not established a similar public coastal radio service at the places selected by the grantee, in no case to exceed fifty years, and is made upon the express condition that the same shall be void unless the construction of at least one public coastal radio stations be begun within two years, from the date of approval of this Act and be completed within three years from said date."}},{"id":"PH-H1669-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"A special right is hereby reserved to the President of the Philippines, in time of war, insurrection, public peril or calamity or domestic trouble, to cause the closing of the radio stations, or to authorize the temporary use or possession thereof by any department of the Government upon payment of just compensation."}},{"id":"PH-H1669-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"The grantee, his successors or assigns, shall hold the national, provincial, and municipal government of the Philippines harmless from all claims, accounts, demands or actions arising out of accidents or injuries whether to property or to persons caused by the construction or operation of the stations by the grantee, his successors or assigns."}},{"id":"PH-H1669-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"The stations of the grantee shall be constructed and operated in accordance with established engineering standards and practice and subject to existing radio laws and regulations, and the frequencies or wave length shall be selected with a view to avoiding interference with the operation of other radio stations in the Philippines."}},{"id":"PH-H1669-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"No private property shall be taken for any purpose by the grantee without proper condemnation proceedings and just compensation paid or tendered therefor, and any authority to take and occupy land contained herein shall not apply to the taking, use or occupation to any land except such as is required for the actual necessary purposes for which this permit is granted."}},{"id":"PH-H1669-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"The right is hereby reserved to the Government of the Philippines, through the Public Service Commission or such other government agency as may hereafter be duly authorized to fix the maximum rates or charges to be charged by the grantee."}},{"id":"PH-H1669-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"The grantee shall keep an account of the gross receipts of the business transacted by him and shall furnish the Auditor General and the National Treasurer of the Philippines a copy of such account not later than thirty-first day of January each year for the preceding year. For the purpose of auditing the accounts rendered the Auditor General and the National Treasurer, all the books and accounts of the grantee or duplicates thereof, shall be subject to the official inspection of the Auditor General or his authorized representatives, and the audit and approval of such accounts by said officers shall be final and conclusive evidence as to the amount of said gross receipts, except that the grantee shall have the right to appeal to the courts of the Philippines under the terms and conditions provided in the laws of the Philippines."}},{"id":"PH-H1669-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"As a condition of the granting of this permit the grantee shall execute a bond in favor of the Government of the Philippines in the sum of fifty thousand pesos, form and with sureties satisfactory to the Secretary of Public Works and Communications or other competent authority, conditioned upon the faithful performance of the grantee's obligations hereunder during the first three years of the life of this permit. If after three years upon the date of the acceptance of this permit, the grantee shall have fulfilled the same, the bond aforesaid shall cancelled by the Secretary of Public Works and Communications or other competent authority."}},{"id":"PH-H1669-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"Acceptance of this permit shall be given in during within six months after approval of this Act. When so accepted by the grantee and upon the approval of the bond aforesaid by the Secretary of Public Works and Communications or other competent authority, the grantee shall be empowered to exercise the privileges granted thereby."}},{"id":"PH-H1669-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"The grantee shall not lease, transfer, grant the usufruct of, sell or assign this permit, nor the rights or privileges acquired thereunder to any person, firm, company, corporation or other commercial or legal entity, nor merge with any other person, company or corporation organized for the same purpose, without the approval of the Congress of the Philippines first had. Any corporation to which this permit may be sold, transferred, or assigned, shall be subject to the corporation laws of the Philippines now existing or hereafter enacted, and any person, firm, company, corporation and other commercial or legal entity to which this permit is sold, transferred, or assigned shall be subject to conditions, terms, restrictions, and limitations of the permit as fully and completely and to the same extent as if the permit had been originally granted to the said person, firm, company, corporation or other commercial or legal entity."}},{"id":"PH-H1669-A13","no":13,"noLabel":{"en":"Section 13."},"text":{"en":"The permit hereby granted shall be subject to amendment, alteration or repeal by the Congress of the Philippines when the public interest so requires, and the rights to use and occupy public property and place hereby granted shall revert to the respective government upon termination of this permit by such repeal, amendment or alteration, or by forfeiture or expiration in any course."}},{"id":"PH-H1669-A14","no":14,"noLabel":{"en":"Section 14."},"text":{"en":"This permit shall not be interpreted to mean an exclusive grant of the privileges herein provided for."}},{"id":"PH-H1669-A15","no":15,"noLabel":{"en":"Section 15."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 22, 1957."}}],"pack":"ph-p23","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Granting Mr. Honorio G. Reyes, Residing at Four Hundred Seventy-Six Laong-Laan, Sampaloc, Manila. a Temporary Permit to Construct, Maintain and Operate Public Coastal Radio Stations in the Philippines, Together with Such Other Radio Stations as May be Necessary for the Operation of the Service, Such as Fixed and Land Base Radio Stations, for the Reception and Transmission of Radio Communications Within the Philippines not at Present Served by Public Radiotelegraph or Radiotelephone Systems","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H1670"] = {"id":"PH-H1670","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1957/ra_1836_1957.html","fetchedAt":"2026-10-06","articleCount":6,"structureMode":"ARTICLE","title":{"zh":"修订《修订行政法典》第五十六章以规定省的分类并确定省官员薪金的法案","en":"An Act to Amend Chapter Fifty-Six of the Revised Administrative Code so as to Provide for the Classification of Provinces, and to Fix the Salaries of Provincial Officials","orig":"An Act to Amend Chapter Fifty-Six of the Revised Administrative Code so as to Provide for the Classification of Provinces, and to Fix the Salaries of Provincial Officials"},"level":"law","status":"active","topics":["administrative"],"docNumber":"Republic Act No. 1836","issuingBody":"Congress of the Philippines","promulgatedDate":"1957-06-22","completenessNote":"全文，共 6 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1957/ra_1836_1957.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。 源文条号不连续（自第 1 条起，止于第 7 条，缺 4）：经逐条比对原始页面，该处原文没有对应的 “Section N.” 抬头行，系来源页自身的编号跳跃或条文以“续段”形式并入前条，非抽取遗漏，故未擅自补号。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1670-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Chapter Fifty-six of the Revised Administrative Code is amended by inserting between sections two thousand sixty-seven and two thousand sixty-eight thereof two new section, to be known as sections two thousand sixty-seven-A and two thousand sixty-seven-B which shall read as follows:\n\"Sec. 2067-A. Classification of provinces. -Provinces are divided into seven classes, according to their income, as follows:\n\"(a) First Class: The provinces that have obtained an average total revenue of one million five hundred thousand pesos or more per annum during the last five fiscal years;\n\"(b) Second Class: The provinces that have obtained an average total revenue of one million pesos or more but less than one million five hundred thousand pesos per annum during the last five fiscal years;\n\"(c) Third Class: The provinces that have obtained an average total revenue of seven hundred thousand pesos or more but less than one million pesos per annum during the last five fiscal years;\n\"(d) Fourth Class: The provinces that have obtained an average total revenue of five hundred thousand pesos or more but less than seven hundred thousand pesos per annum during the last five fiscal years;\n\"(e) Fifth Class: The provinces that have obtained an average total revenue of three hundred thousand pesos or more but less than five hundred thousand pesos per annum during the last five fiscal years;\n\"(f) Sixth Class: The provinces that have obtained an average total revenue of one hundred fifty thousand pesos or more but less than three hundred thousand pesos per annum during the last five fiscal years; and \"(g) Seventh Class: The provinces that have obtained an average total revenue of less than one hundred fifty thousand pesos per annum during the last five fiscal years: Provided, That revenue as used in this Act shall be interpreted to mean all revenues and receipts accruing to the province except proceeds from bond issues, proceeds from or repayment of loans, aids from the National Government, private contributions and donations, return of advances to economic enterprises, sales of fixed assets, income from sale of real property, prior year adjustment, inventory adjustment, and other receipts not regularly recurring each fiscal year: Provided, further, That no readjustment of the classification shall be made oftener than once in five consecutive years, except in cases of the diminishing revenues when the Secretary of Finance may, in his discretion, order at any time the readjustment of the classification of any province in accordance with the foregoing schedule.\"\n\"Sec. 2067-B. Salaries of provincial officials. -The annual salaries of provincial governors, provincial treasurers, provincial fiscals, provincial auditors, provincial health officers, provincial assessors, assistant provincial treasurers, assistant provincial auditors, assistant provincial health officers and assistant provincial assessors shall be as hereinbelow fixed:\n\"In first class provinces: For provincial governors, twelve thousand pesos; for provincial treasurers, provincial fiscals, provincial auditors, and provincial health officers, seven thousand eight hundred pesos; for provincial assessors, seven thousand two hundred pesos; for assistant provincial treasurers, assistant provincial auditors and assistant provincial health officers, five thousand one hundred pesos; and for assistant provincial assessors, four thousand five hundred pesos;\n\"In second class provinces: For provincial governors, ten thousand pesos; for provincial treasurers, provincial fiscals, provincial auditors, and provincial health officers, seven thousand five hundred pesos; for provincial assessors, six thousand nine hundred pesos; for assistant provincial treasurers, assistant provincial auditors and assistant provincial health officers, five thousand one hundred pesos and for assistant provincial assessors, four thousand five hundred pesos;\n\"In the third class provinces: For provincial governors, nine thousand six hundred pesos; for provincial treasurers, provincial fiscals, provincial auditors, and provincial health officers, seven thousand two hundred pesos; for provincial assessors, six thousand six hundred pesos; for assistant provincial treasurers, assistant provincial auditors and assistant provincial health officers, four thousand eight hundred pesos; and for assistant provincial assessors, four thousand two hundred pesos;\n\"In fourth class provinces: For provincial governors, eight thousand four hundred pesos; for provincial treasurers, provincial fiscals, provincial auditors, and provincial health officers, six thousand nine hundred pesos; for provincial assessors, six thousand three hundred pesos; for assistant provincial treasurers, assistant provincial auditors and assistant provincial health officers, four thousand five hundred sixty pesos; and for assistant provincial assessors, for thousand one hundred twenty pesos;\n\"In fifth class provinces: For provincial governors seven thousand two hundred pesos; for provincial treasurers, provincial fiscals, provincial auditors, and provincial health officers, six thousand six hundred pesos; for provincial assessors, six thousand pesos; for assistant provincial treasurers, assistant provincial auditors and assistant provincial health officers, four thousand one hundred twenty pesos; and for assistant provincial assessors, four thousand eighty pesos;\n\"In sixth class provinces: For provincial governors, six thousand six hundred pesos; for provincial treasurers, provincial fiscals, provincial auditors, and provincial health officers, six thousand pesos; for provincial assessors, five thousand four hundred pesos; for assistant provincial treasurers, assistant provincial auditors and assistant provincial health officers, four thousand eighty pesos; and for assistant provincial assessors, three thousand nine hundred pesos;\n\"In seventh class provinces: For provincial governors, six thousand pesos; for provincial treasurers, provincial fiscals, provincial auditors, and provincial health officers, five thousand four hundred pesos; for provincial assessors, four thousand eight hundred pesos; for assistant provincial treasurers, assistant provincial auditors and assistant provincial health officers, three thousand nine hundred pesos; and for assistant provincial assessors, three thousand six hundred pesos: Provided, That if after the classification of provinces as provided for in section five of this Act, the salaries of the present incumbents of the positions of provincial governor, provincial treasurer, provincial fiscal, provincial auditor, provincial health officer, provincial assessor, assistant provincial treasurer, assistant provincial auditor, assistant provincial health officer and assistant provincial assessor shall be reduced on account of the application of the schedule provided for in this section, the said incumbents shall continue to receive their present salaries until their successors are appointed: And Provided, further, That if after the salary of a provincial governor, provincial treasurer, provincial fiscal, provincial auditor, provincial health officer, provincial assessor, assistant provincial treasurer, assistant provincial auditor, assistant provincial health officer and assistant provincial assessor has been increased by virtue of the provisions hereof, the province concerned incurs an overdraft in its general fund or the operating expenses thereof exceed the revenue collections, the President of the Philippines, upon recommendation of the Secretary of Finance, shall reduce the salary of said officials to the maximum rates fixed for them in the next lower class of province.\n\"One-half of the salary of the provincial auditor, of the provincial health officer, of the assistant provincial auditor and of the assistant provincial health officer shall be paid out of the national funds and the other half shall be paid out of the funds of the province concerned: Provided, However , That the increase in salary of the provincial auditor, provincial health officer, assistant provincial auditor and assistant provincial health officer shall be borne by the province until the share thereof of the National Government shall have been provided for in the General Appropriations Act.\""}},{"id":"PH-H1670-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Section two thousand ninety-seven of the same chapter of the Revised Administrative Code, as amended, is hereby further amended to read as follows:\n\"Sec. 2097. Compensation of Members. -Except as otherwise specially provided, the members of the provincial board shall receive a compensation, to be fixed by resolution of the provincial board, of not exceeding thirty-five pesos in first class, second class and third class provinces; thirty pesos in fourth class and fifth class provinces; and twenty-five pesos in sixth class and seventh class provinces, for each day of actual attendance at the sessions of the board; and, except as otherwise specially provided, compensation shall in no case be paid for service rendered by a member of the board out of session. The amount of the per diem shall not be changed more than once a year.\n\"If not a resident of the provincial capital, a member of the provincial board shall be entitled to reimbursement of his actual and necessary travel expenses from his place of residence to the place where the provincial board holds its sessions, when going to said sessions and returning from the same.\""}},{"id":"PH-H1670-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Section two thousand one hundred twenty-one-A of the same chapter of the said Code is amended to read as follows:\n\"Sec. 2121-A. General limitation upon amount expendable for salaries and wages. -Except as hereinbelow provided, the amount expendable for salaries and wages of provincial officials and employees shall not exceed the following percentages of the ordinary and regular income that accrued to the general fund during the preceding fiscal year, exclusive of all balances carried forward from preceding fiscal years, transfers from other funds, and all receipts from loans, aids or gifts from government or private funds:\n\"First class provinces, forty-five per centum;\n\"Second class provinces, fifty per centum \"Third and fourth class provinces, fifty-five per centum;\n\"Fifth class provinces, sixty per centum;\n\"Sixth class provinces, sixty-five per centum;\n\"Seventh class provinces, seventy-five per centum.\n\"In case the current income of the general funds is less than that which accrued to the same fund during the preceding fiscal year, the percentages fixed in the preceding paragraph shall be based on the reduced income for the current fiscal year.\n\"The Secretary of Finance may authorize any province to exceed the percentages hereinabove fixed under such conditions as he may impose.\"\nSection 4 . Salaries of ex-officio officials. -In cases where an official is designated as ex officio official, such official shall receive additional compensation which shall not exceed the following:\nIn first class, second class, and third class provinces, one thousand two hundred pesos per annum.\nIn fourth class and fifth class provinces, nine hundred sixty pesos per annum; and In sixth class and seventh class provinces, seven hundred twenty pesos per annum."}},{"id":"PH-H1670-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Classification under this Act. -Upon the approval of this Act and for each period of five consecutive fiscal years thereafter, the Secretary of Finance shall classify all provinces on the basis of the average total revenue of such provinces during the five consecutive fiscal years immediately preceding such classification according to the provisions of this Act as certified by the Auditor General: Provided, That the first classification shall take effect on July one, nineteen hundred and fifty-seven. Hereafter, there shall be no special or partial classification of the provinces, except as provided for in section two thousand sixty-seven-A of the Revised Administrative Code."}},{"id":"PH-H1670-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"Act Numbered Thirty-seven hundred ninety-eight, as amended, Republic Act Numbered Three hundred sixty-eight, as amended, sections sixteen hundred and seventy-five and twenty hundred and eighty-six of the Revised Administrative Code, and all Acts, executive orders or parts thereof inconsistent with the provisions of this Act are repealed."}},{"id":"PH-H1670-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"This Act shall take effect on July first, nineteen hundred and fifty-seven.\nApproved: June 22, 1957."}}],"pack":"ph-p23","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act to Amend Chapter Fifty-Six of the Revised Administrative Code so as to Provide for the Classification of Provinces, and to Fix the Salaries of Provincial Officials","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H1671"] = {"id":"PH-H1671","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1957/ra_1837_1957.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":"修订第409号共和国法（即《马尼拉市修订宪章》）若干条款的法案","en":"An Act Amending Certain Sections of Republic Act Numbered Four Hundred Nine, Otherwise Known as the Revised Charter of the City of Manila","orig":"An Act Amending Certain Sections of Republic Act Numbered Four Hundred Nine, Otherwise Known as the Revised Charter of the City of Manila"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 1837","issuingBody":"Congress of the Philippines","promulgatedDate":"1957-06-22","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1957/ra_1837_1957.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1671-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Section fifty-nine of Republic Act Numbered Four hundred nine, otherwise known as the Revised Charter of the City of Manila, is amended to read as follows:\n\"Sec. 59. Revision of assessment. The city assessor and collector shall, during the first fifteen days of December of each year, add to his list of taxable real estate in the city the value of the improvements placed upon such property during the preceding year, and any property which is taxable and which has theretofore escaped taxation. He may during the same period revise and correct the assessed value of any or all parcels of real estate in the city which are not assessed at their true money value, by reducing or increasing the existing assessments as the case may be: Provided, however, That no increase in the assessment of a particular real estate shall be made oftener than once every five years. He shall give notice by publication for ten days prior to December first in two newspapers of general circulation published in the city, that he will be present in his office for that purpose on said days, and he shall further notify in writing such person the amount of whose tax will be changed by such action or such proposed change by delivering or mailing such notification to such person or his authorized agent at the last known address of such owner or agent in the Philippines sometime in the month of November.\""}},{"id":"PH-H1671-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"A new section, to be known as section sixty-A, is inserted between sections sixty and sixty-one to read as follows:\n\"Sec. 60-A. Time and manner of appealing to Board of Tax Appeals. In case the Municipal Board, or any owner of real estate or his authorized agent, or any tenant or lessee of land shall feel aggrieved by any decision of the city assessor and collector under the preceding sections of this article, such Board, owner or agent, or tenant or lessee may, within sixty days after the date on which the taxpayer received the notice of the assessor's appeal to the Board of Tax Appeals. The appeal shall be perfected by filing a written notice of the same with the city assessor and collector, and it shall be the duty of that officer forthwith to transmit the appeal to the Board of Tax Appeals with all written evidence in his possession relating to such assessment and valuation: Provided, however, That in case of tenants or lessees affected by the assessment, the period of appeal shall be counted from the time they have knowledge thereof.\""}},{"id":"PH-H1671-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Sections sixty-one and sixty-nine of the same Act are amended to read as follows:\n\"Sec. 61. Board of Tax Appeals. The Board of Tax Appeals shall be composed of seven members who shall be appointed by the President of the Philippines on the first day of January every four years, four of whom shall be owners of real estate in the city and three shall represent the tenant and lessee interests in the city.\n\"The members of the Board of Tax Appeals, except the chairman, shall receive a compensation of twenty pesos for each day on which they attend the session and serve as members of the Board.\n\"The chairman of the Board of Tax Appeals shall designated in the appointment of the President and shall receive forty pesos for each day on which he attend the sessions. The Secretary of the Board shall be appointed by the chairman thereof with the concurrence of a majority of its members and shall keep the record of the proceedings of the Board. The secretary shall receive such salary as the Board may fix.\"\n\"Sec. 69. Tax sale. In addition to the procedure prescribed in section sixty-five hereof the city assessor and collector may, upon the warrant of the certified record required in said section, not less than twenty days after delinquency, advertise the real estate of the delinquent for sale, or so much thereof as may be necessary to satisfy all public taxes upon said property as above with penalties and costs of sale, for a period of thirty days.\n\"The advertisement shall be by posting a notice at the main entrance of the City Hall and in a public and conspicuous place in the district in which the real estate lies, and by publication once a week for three weeks, in a newspaper of general circulation published in the city if any there be. Publication in the Official Gazette shall not be required for such notice. The advertisement shall state the amount of the taxes and penalties so due, the time and place of sale, the name of the taxpayers against whom the taxes are levied, and the approximate area, the lot and block number, the location by district and street, and the street number, if the property has a street number, of the real estate to be sold. At any time before the day fixed for the sale the taxpayer may discontinue all proceedings by paying the taxes, penalties, and costs to the city assessor and collector. If he does not do so the sale shall proceed and shall be held either at the main entrance of the City Hall or on the premises to be sold, as the city assessor and collector may determine: Provided , That no such sale shall proceed unless the delinquent taxpayer shall have been notified thereof by registered mail at least sixty days before the date fixed for the sale. Within five days after the sale the city assessor and collector shall make return of the proceedings and spread it in his records. The purchaser at the sale shall receive a certificate from the city assessor and collector from his records showing the proceedings of the sale, describing the property sold, stating the name of the purchaser, and setting out the exact amount of all public taxes, penalties and costs.\n\"It shall not be essential to the validity of a sale of real estate for delinquent taxes hereunder that the city assessor and collector shall have attempted to make the amount due out of the personal property of the delinquent taxpayer, and the remedy provided in section sixty-five hereof shall be deemed cumulative only.\""}},{"id":"PH-H1671-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 22, 1957"}}],"pack":"ph-p23","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Amending Certain Sections of Republic Act Numbered Four Hundred Nine, Otherwise Known as the Revised Charter of the City of Manila","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H1672"] = {"id":"PH-H1672","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1957/ra_1838_1957.html","fetchedAt":"2026-10-06","articleCount":8,"structureMode":"ARTICLE","title":{"zh":"授予 Angel R. Jose 在三宝颜市建设、维护和运营无线电广播电台的临时许可的法案","en":"An Act Granting Angel R. Jose a Temporary Permit to Construct, Maintain and Operate Radio Broadcasting Station in Zamboanga City","orig":"An Act Granting Angel R. Jose a Temporary Permit to Construct, Maintain and Operate Radio Broadcasting Station in Zamboanga City"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 1838","issuingBody":"Congress of the Philippines","promulgatedDate":"1957-06-22","completenessNote":"全文，共 8 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1957/ra_1838_1957.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1672-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Subject to the provisions of the Constitution, as well as of Act Numbered Three thousand eight hundred forty-six, entitled \"An Act providing for the regulation of radio stations and radio communications in the Philippine Islands, and for other purposes\"; Act Numbered Three thousand nine hundred ninety-seven known as the Radio Broadcasting Law; Commonwealth Act Numbered One hundred forty-six, known as the Public Service Act, and their amendments, and other applicable laws, Angel R. Jose is hereby granted a temporary permit to construct, maintain and operate, for commercial purposes and in the public interest, a radio broadcasting station in Zamboanga City: Provided, That this temporary permit shall be void unless the construction of the radio broadcasting station be begun within one year from the date of approval of this Act and be completed within two years from said date: Provided, further, That the grantee shall provide adequate public service time to enable the Government, through the station herein authorized, to reach the population on important public issues; shall assist in the functions of public information and education; and shall not use said station for the broadcasting of obscene or indecent language or speech, or for the dissemination of deliberately false information or willful misrepresentation, or to the detriment of the public health, or to incite, encourage or assist in subversive or treasonable acts."}},{"id":"PH-H1672-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The grantee shall file a bond in the amount of fifty thousand pesos to guaranty for the full compliance and fulfillment of the conditions under which this permit is granted, and shall not, during the lifetime of this permit, sell, transfer or assign the same to another without the consent of Congress."}},{"id":"PH-H1672-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"In the event of any competing individual, partnership or corporation receiving from the Congress a similar temporary in which there shall be any term or terms more favorable than those herein granted or tending to place the herein grantee at any disadvantage, then such term or terms shall, ipso facto, become a part of the terms hereof and shall operate equally in favor of the grantee as in the case of said competing individual, partnership or corporation."}},{"id":"PH-H1672-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"In the event the Government should desire to maintain or operate for itself the radio broadcasting station herein authorized, the grantee shall turn over such station to the Government with all the serviceable equipment therein at cost less reasonable depreciation."}},{"id":"PH-H1672-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"The grantee shall be liable to pay the same taxes on its real estate, buildings and personal property exclusive of the temporary permit, as other person or corporation are now or hereafter may be required by law to pay."}},{"id":"PH-H1672-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"The grantee shall not require any previous censorship of any speech, play or other matter to be broadcast from its station but if any such speech, play or other matter should constitute a violation of the law or infringement of a private right, the grantee shall be free from liability, civil or criminal, or such speech, play or other matter: Provided, That the grantee, during any broadcast shall cut off from the air the speech, play or other matter being broadcast if the tendency thereof is to propose and or incite treason, rebellion or sedition, or the language used therein or the theme thereof is indecent or immoral, willful failure in which duty will be sufficient cause for the forfeiture of this permit: Provided, further, That if the grantee should require, impose or undertake previous censorship of any speech, play or other matter to be broadcast from its stations, or if the grantee should cut off from the air any speech, play or other matter being broadcast except as herein provided, such act or acts shall constitute a valid ground for the cancellation of this permit."}},{"id":"PH-H1672-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"The grantee shall not lease, transfer, grant the usufruct of, sell or assign this temporary permit, nor the rights or privileges acquired thereunder to any person, firm, company, corporation or other commercial or legal entity, nor merge with any other person, firm, company or corporation organized for the same purpose, without the approval of the Congress of the Philippines first had. Any corporation to which this temporary permit may be sold, transferred, or assigned, shall be subject to the corporation laws of the Philippines now existing or hereafter enacted, and any person, firm, company, corporation or other commercial or legal entity to which this temporary permit is sold, transferred, or assigned shall be subject to all conditions, terms, restrictions and limitations of this temporary permit as fully and completely and to the same extent as if the temporary permit had been originally granted to the same person, firm, company, corporation or other commercial or legal entity."}},{"id":"PH-H1672-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 22, 1957."}}],"pack":"ph-p23","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Granting Angel R. Jose a Temporary Permit to Construct, Maintain and Operate Radio Broadcasting Station in Zamboanga City","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H1673"] = {"id":"PH-H1673","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1957/ra_1839_1957.html","fetchedAt":"2026-10-06","articleCount":12,"structureMode":"ARTICLE","title":{"zh":"授予 Valeriano C. Bueno 在菲律宾境内建设、设立、维护和运营私人固定点对点与海岸无线电台的临时许可的法案","en":"An Act Granting Valeriano C. Bueno a Temporary Permit to Construct, Establish, Maintain and Operate Private Fixed Point-to-Point and Private Coastal Radio Stations for the Reception and Transmission of Radio Communications Within the Philippines","orig":"An Act Granting Valeriano C. Bueno a Temporary Permit to Construct, Establish, Maintain and Operate Private Fixed Point-to-Point and Private Coastal Radio Stations for the Reception and Transmission of Radio Communications Within the Philippines"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 1839","issuingBody":"Congress of the Philippines","promulgatedDate":"1957-06-22","completenessNote":"全文，共 12 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1957/ra_1839_1957.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1673-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There is hereby granted to Valeriano C. Bueno, his heirs or assigns, a temporary permit to construct, establish, maintain and operate in the Philippines, at such places as the said grantee may select, subject to the approval of the Secretary of Public Works and Communications, private fixed point-to-point and private coastal radio stations for the reception and transmission of wireless messages on radiotelegraphy or radiotelephony, each station to be provided with a radio transmitting apparatus and a radio receiving apparatus."}},{"id":"PH-H1673-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The President of the Philippines shall have the power and authority to permit the location of said private fixed point-to-point and private coastal radio stations or any of them on lands of the public domain upon such terms as he may prescribe."}},{"id":"PH-H1673-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This temporary permit shall continue to be in force during the time that the Government has not established similar service at the places selected by the grantee, and is granted upon the express condition that the same shall be void unless the construction of said station be begun within one year from the date of approval of this Act and be completed within two years from said date."}},{"id":"PH-H1673-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"The grantee, his heirs or assigns, shall not engage in domestic business of the telecommunications in the Philippines without further special assent of the Congress of the Philippines, it being understood that the purpose of this temporary permit is to secure to the grantee the right to construct, establish, maintain and operate private fixed point-to-point and private coastal radio stations in such places within the Philippines as the interest of his trade and business may justify."}},{"id":"PH-H1673-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"This temporary permit shall not take effect until the Secretary of Public Works and Communications shall have allotted to the grantee the frequencies and wave lengths to be used thereunder, but the grantee, his heirs or assigns, may use the international distress frequency of five hundred kilocycles and the high distress frequency of eight thousand two hundred eighty kilocycles whenever necessary."}},{"id":"PH-H1673-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"No fees are chargeable, as the radio stations that may be established by virtue of this Act shall engage in communications regarding the grantee's business only."}},{"id":"PH-H1673-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"The grantee, his heirs or assigns, shall so construct and operate his radio stations as not to interfere with the operation of other radio stations maintained and operated in the Philippines."}},{"id":"PH-H1673-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"The grantee, his heirs or assigns, shall hold the national provincial and municipal governments of the Philippines harmless from all claims, accounts, demands, or actions arising out of accidents or injuries, whether to property or to persons, caused by the construction or operation of his radio stations."}},{"id":"PH-H1673-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"A special right is hereby reserved to the President m of the Philippines in time of war, insurrection, public peril, emergency, calamity or disaster to cause the closing of the grantee's radio stations or to authorize the temporary use or possession thereof by any department of the Government upon payment of just compensation."}},{"id":"PH-H1673-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"The grantee shall not lease, transfer, grant the usufruct of, sell or assign this temporary permit, nor the rights or privileges acquired thereunder to any person, firm, company, corporation or other commercial or legal entity, nor merge with any other person, firm, company or corporation organized for the same purpose, without the approval of the Congress of the Philippines first had. Any corporation to which this temporary permit may be sold, transferred, or assigned, shall be subject to the corporation laws of the Philippines now existing or hereafter enacted, and any person, firm, company, corporation or other commercial or legal entity to which this temporary permit is sold, transferred, or assigned shall be subject to all conditions, terms, restrictions and limitations of this temporary permit as fully and completely and to the same extent as if the temporary permit had been originally granted to the said person, firm, company, corporation or other commercial or legal entity."}},{"id":"PH-H1673-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"This temporary permit shall be subject to amendment, alteration, or repeal by the Congress of the Philippines when the public interest so requires, and shall not be interpreted as an exclusive grant of the privileges herein provided for."}},{"id":"PH-H1673-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 22, 1957."}}],"pack":"ph-p23","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Granting Valeriano C. Bueno a Temporary Permit to Construct, Establish, Maintain and Operate Private Fixed Point-to-Point and Private Coastal Radio Stations for the Reception and Transmission of Radio Communications Within the Philippines","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H1674"] = {"id":"PH-H1674","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1957/ra_1840_1957.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":"授予Feliciana S. Bermudez在哥打巴托省Tupi市镇电灯、热力与动力系统特许经营权的法案","en":"An Act to Grant to Feliciana S. Bermudez a Franchise for an Electric Light, Heat and Power System in the Municipality of Tupi, Province of Cotabato","orig":"An Act to Grant to Feliciana S. Bermudez a Franchise for an Electric Light, Heat and Power System in the Municipality of Tupi, Province of Cotabato"},"level":"law","status":"active","topics":["investment"],"docNumber":"Republic Act No. 1840","issuingBody":"Congress of the Philippines","promulgatedDate":"1957-06-22","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1957/ra_1840_1957.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1674-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Subject to the terms and conditions established in Act Numbered Thirty-six hundred and thirty-six, as amended by Commonwealth Act Numbered One hundred and thirty-two, and to the provisions of the Constitution, there is granted to Feliciana S. Bermudez, for a period twenty-five years from the approval of this Act, the right, privilege and authority to construct, maintain and operate an electric light, heat and power plant for the purpose of generating and distributing electric light, heat and/or power for sale within the limits of the Municipality of Tupi, Province of Cotabato."}},{"id":"PH-H1674-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"In the event that the grantee shall purchase and secure from the National Power Corporation electric heat and power, the National Power Corporation is hereby authorized to negotiate and transact for the benefit and in behalf of the public consumers with reference to rates."}},{"id":"PH-H1674-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"It is expressly provided that in the event the Government should desire to maintain and operate for itself the plant and enterprise herein authorized, the grantee shall surrender her franchise and will turn over to the Government all serviceable equipment therein, at cost, less reasonable depreciation."}},{"id":"PH-H1674-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 22, 1957."}}],"pack":"ph-p23","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act to Grant to Feliciana S. Bermudez a Franchise for an Electric Light, Heat and Power System in the Municipality of Tupi, Province of Cotabato","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H1675"] = {"id":"PH-H1675","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1957/ra_1841_1957.html","fetchedAt":"2026-10-06","articleCount":12,"structureMode":"ARTICLE","title":{"zh":"授予 Edward J. Nell Company 及其姊妹公司 Aircon，Inc. 在菲律宾境内建设、维护和运营私人固定点对点、陆基与陆上移动无线电台的临时许可的法案","en":"An Act Granting the Edward J. Nell Company and/or its Sister Company, the Aircon, Inc. a Temporary Permit to Construct, Maintain and Operate Private Fixed Point-to-Point and Land Based and Land Mobile Radio Stations for the Reception and Transmission of Radio Communications Within the Philippines","orig":"An Act Granting the Edward J. Nell Company and/or its Sister Company, the Aircon, Inc. a Temporary Permit to Construct, Maintain and Operate Private Fixed Point-to-Point and Land Based and Land Mobile Radio Stations for the Reception and Transmission of Radio Communications Within the Philippines"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 1841","issuingBody":"Congress of the Philippines","promulgatedDate":"1957-06-22","completenessNote":"全文，共 12 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1957/ra_1841_1957.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1675-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There is hereby granted to the Edward J. Nell Company and/or its sister company, the AIRCON, Inc., their successors or assigns, a temporary permit to construct, maintain and operate in the Philippines, at Manila and at such places as the said company may select, subject to the approval of the Secretary of Public Works and Communications, private fixed point-to-point and land based and land mobile radio stations for the reception and transmission of wireless messages on radiotelegraphy or radiotelephony, each station to be provided with a radio transmitting apparatus and a radio receiving apparatus."}},{"id":"PH-H1675-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This temporary permit shall continue to be in force during the time that the Government has not established similar service at the places selected by the grantee, and is granted upon the express condition that the same shall be void unless the construction or installation of said stations be begun within one year from the date of approval of this Act and be completed within two years from said date."}},{"id":"PH-H1675-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The grantee, its successors or assigns shall not engage in domestic business of telecommunications in the Philippines without further special assent of the Congress of the Philippines, it being understood that the purpose of this temporary permit is to secure to the grantee the right to construct, install, maintain, and operate private fixed point-to-point and land based and land mobile radio stations in such places within the Philippines as the interest of the grantee may justify."}},{"id":"PH-H1675-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"No fees shall be charged by the grantee on the radio stations that may be established by virtue of this Act shall engage in communications regarding the grantee's business only."}},{"id":"PH-H1675-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"The grantee, its successors or assigns, shall not construct and operate its radio stations as not to interfere with the operation of other radio stations maintained and operated in the Philippines."}},{"id":"PH-H1675-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"The grantee, its successors or assigns, shall hold the National, provincial, city and municipal governments of the Philippines harmless from all claims, accounts, demands, or actions arising out of accidents or injuries, whether to property or to persons, caused by the construction or operation of its radio stations."}},{"id":"PH-H1675-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"The grantee, its successors or assigns, shall be subject to the corporation laws of the Philippines now existing or hereafter enacted."}},{"id":"PH-H1675-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"The grantee, its successors or assigns, is authorized to operate its private fixed point-to-point and land based and land mobile radio stations in the medium frequency, high frequency, and very high frequency that may be assigned to it by the Secretary of Public Works and Communications."}},{"id":"PH-H1675-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"The grantee shall not lease, transfer, grant the usufruct of, sell or assign this temporary permit, nor the rights or privileges acquired thereunder to any person, firm company, corporation or other commercial or legal entity nor merge with the any other person, company or corporation organized for the same purpose, without the approval of the Congress of the Philippines first had. Any corporation to which this temporary permit may be sold, transferred, or assigned, shall be subject to the corporation laws of the Philippines now existing or hereafter enacted, and any person, firm, company, corporation or other commercial or legal entity to which this temporary permit is sold, transferred, or assigned shall be subject to all conditions, terms, restrictions and limitations of this temporary permit as fully and completely and to the same extent as if the temporary permit had been originally granted to the said person, firm, company, corporation or other commercial or legal entity."}},{"id":"PH-H1675-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"A special right is hereby reserved to the President of the Philippines in time of war, insurrection, public peril, emergency, calamity or disaster to cause the closing of the grantee's radio stations or to authorize the temporary use or possession thereof by any department of the Government upon payment of just compensation."}},{"id":"PH-H1675-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"This temporary permit shall be subject to amendment, alteration, or repeal by the Congress of the Philippines when the public interest so requires, and shall not be interpreted as an exclusive grant of the privilege herein provided for."}},{"id":"PH-H1675-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 22, 1957."}}],"pack":"ph-p23","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Granting the Edward J. Nell Company and/or its Sister Company, the Aircon, Inc. a Temporary Permit to Construct, Maintain and Operate Private Fixed Point-to-Point and Land Based and Land Mobile Radio Stations for the Reception and Transmission of Radio Communications Within the Philippines","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H1676"] = {"id":"PH-H1676","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1957/ra_1842_1957.html","fetchedAt":"2026-10-06","articleCount":6,"structureMode":"ARTICLE","title":{"zh":"设立Manila市","en":"An Act Creating the Meat Inspection Board in the City of Manila, Amending for This Purpose Republic Act Numbered Four Hundred and Nine","orig":"An Act Creating the Meat Inspection Board in the City of Manila, Amending for This Purpose Republic Act Numbered Four Hundred and Nine"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 1842","issuingBody":"Congress of the Philippines","promulgatedDate":"1957-06-22","completenessNote":"全文，共 6 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1957/ra_1842_1957.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1676-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Republic Act Numbered Four hundred and nine, otherwise known as the Revised Charter of the City of Manila, is amended by inserting between Articles XIV and XV thereof, a new article, to be known as Article XIV-A, which shall read as follows:\n\"Article XIV-A — Meat Inspection Board \"Sec. 80-A. Composition. -There is hereby created a Meat Inspection Board which shall be composed of the city veterinarian, as chairman, and the superintendent of the abattoir and the chief veterinary meat inspector. The chairman shall receive a compensation of eight thousand four hundred pesos per annum, and each of the members shall receive six thousand pesos per annum.\n\"Sec. 80-B. Duties and powers of the Board. -The Meat Inspection Board shall:\n\"(a) Exercise supervision and control over all public and private abattoirs, corrals, meat processing works, butchers' shops, packing plants and boiling down works.\n\"(b) Regulate and control the slaughtering of stock generally, and prohibit the slaughtering of stock in places other than abattoirs under the supervision of the Board and provide for the inspection of meat and meat products destined for consumption.\n\"(c) Provide for the licensing and inspection of slaughterhouses, packing houses and butchers' shops, as well as of establishments where meats are dressed, processed or offered for sale.\n\"(d) Regulate and supervise the carriage, storage, and treatment of meat and the carriage and treatment of stock intended for slaughter generally.\n\"(e) Provide for the destruction and disposal of stock and of carcasses of stock and meat which are diseased and which are otherwise unfit for human consumption.\n\"(f) Provide for the branding of carcasses or meat of stock slaughtered at abattoirs.\n\"(g) Prescribe and collect slaughterhouse charges and fees for inspection, storage, corralling and cartage of stock or meat and inspection charges for imported meats and meat products.\n\"(h) Prescribe, regulate and control the slaughter of horses for food of animals.\n\"(i) Prescribe the qualifications and duties of meat inspectors and other employees of the Board.\n\"(j) Take charge of the design and construction of such abattoirs, stockyards and corrals as may be authorized by the City.\n\"(k) Promulgate, subject to the approval of the mayor, such rules and regulations as may be necessary to implement effectively the provisions of this article.\n\"(l) Provide for measures to control and prevent the transmission of animal disease to man.\n\"(m) Provide for a system of inspection of fish and other marine products.\n\"(n) Provide for the inspection of milk and milk products thereof.\""}},{"id":"PH-H1676-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The second paragraph of section fifty-two of the same Act is amended to read as follows:\n\"The City Treasurer shall exercise the functions of municipal collector of taxes, shall collect all taxes and assessments due the city, and all licenses authorized by law or ordinances, and all rents due for lands, markets, and other property owned by the city; shall administer markets and shall receive and receipt for all costs, fees, fines and forfeitures imposed by the municipal court, from the clerks thereof, and the fees collected by the sheriff or his deputies, or by the justice of the peace.\""}},{"id":"PH-H1676-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Paragraph (a), section seventy-nine of the same Act is amended to read as follows:\n\"(a) He shall have general supervision and control over the health and sanitary conditions of the city, including the cleaning of crematories, cemeteries, and markets.\""}},{"id":"PH-H1676-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Paragraph (a), section eighty of the same Act is amended to read as follows:\n\"(a) He shall have general supervision and control over the sanitary building and plumbing inspection service; care, custody and cleaning of all public buildings including markets and buildings rented for city purposes; public toilets; collection and disposal of garbage, refuse, contents of toilets and cesspools, and all other offensive and dangerous substances within the city.\""}},{"id":"PH-H1676-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Upon the organization of the Meat Inspection Board, the balances of appropriations, personnel, equipment, supplies and records of the Division of Veterinary Service, Division of Slaughterhouses and Stockyards, Meat Delivery Service shall be transferred to the Meat Inspection Board."}},{"id":"PH-H1676-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 22, 1957."}}],"pack":"ph-p23"};
  FT["PH-H1677"] = {"id":"PH-H1677","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1957/ra_1843_1957.html","fetchedAt":"2026-10-06","articleCount":12,"structureMode":"ARTICLE","title":{"zh":"授予 Aguinaldo Development Corporation 在菲律宾境内建设、设立、维护和运营私人固定点对点无线电台的临时许可的法案","en":"An Act Granting the Aguinaldo Development Corporation a Temporary Permit to Construct, Establish, Maintain and Operate Private Fixed Point-to-Point Radio Stations for the Reception and Transmission of Radio Communications Within the Philippines","orig":"An Act Granting the Aguinaldo Development Corporation a Temporary Permit to Construct, Establish, Maintain and Operate Private Fixed Point-to-Point Radio Stations for the Reception and Transmission of Radio Communications Within the Philippines"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 1843","issuingBody":"Congress of the Philippines","promulgatedDate":"1957-06-22","completenessNote":"全文，共 12 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1957/ra_1843_1957.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1677-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There is hereby granted to the Aguinaldo Development Corporation, its successors or assigns, a temporary permit to construct, establish, maintain and operate in the Philippines, at such places as the said company may select, subject to the approval of the Secretary of Public Works and Communications, private fixed point-to-point radio stations for the reception and transmission of wireless messages on radiotelegraphy or radiotelephony, each station to be provided with a radio transmitting apparatus and a radio receiving apparatus."}},{"id":"PH-H1677-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The President of the Philippines shall have the power and authority to permit the location of said private fixed point-to-point radio stations or any of them on lands of the public domain upon such terms as he may prescribe."}},{"id":"PH-H1677-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This temporary permit shall continue to be in force during the time that the Government has not established similar service at the places selected by the grantee, and is granted upon the express condition that the same shall be void unless the construction of said stations be begun within one year from the date of approval of this Act and be completed within two years from said date."}},{"id":"PH-H1677-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"The grantee, its successors or assigns, shall not engage in domestic business of telecommunications in the Philippines without further special assent of the Congress of the Philippines, it being understood that the purpose of this temporary permit is to secure to the grantee the right to construct, establish, maintain and operate private fixed point-to-point radio stations in such places within the Philippines as the interest of the company and of the trade and business may justify."}},{"id":"PH-H1677-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"This temporary permit shall not take effect until the Secretary of Public Works and Communications shall have allotted to the grantee the frequencies and wave lengths to be used thereunder, but the grantee, its successors or assigns, may use the international distress frequency of five hundred kilocycles and the high distress frequency of eight thousand two hundred eighty kilocycles whenever necessary."}},{"id":"PH-H1677-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"No fees are chargeable, as the radio station that may be established by virtue of this Act shall engage in communications regarding the company's business only."}},{"id":"PH-H1677-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"The grantee, its successors or assigns, shall so construct and operate its radio stations as not to interfere with the operation of other radio stations maintained and operated in the Philippines."}},{"id":"PH-H1677-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"The grantee, its successors or assigns, shall hold the national, provincial and municipal governments of the Philippines harmless from all claims, accounts, demands, or actions arising out of accidents or injuries, whether to property or to persons, caused by the construction or operation of its radio stations."}},{"id":"PH-H1677-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"The grantee shall not lease, transfer, grant the usufruct of, sell or assign this temporary permit, nor the rights or privileges acquired thereunder to any person, firm, company, corporation or other commercial or legal entity nor merge with any other person, firm, company, or corporation organized for the same purpose, without the approval of the Congress of the Philippines first had. Any corporation to which this temporary permit may be sold, transferred, or assigned, shall be subject to the corporation laws of the Philippines now existing or hereafter enacted, and any person, firm, company, corporation or other commercial or legal entity to which this temporary permit is sold, transferred, or assigned shall be subject to all conditions, terms, restrictions and limitations of this temporary permit as fully and completely and to the same extent as if the temporary permit had been originally granted to the said person, firm, company, corporation or other commercial or legal entity."}},{"id":"PH-H1677-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"A special right is hereby reserved to the President of the Philippines in time of war, insurrection, public peril, emergency, calamity or disaster to cause the closing of the grantee’s radio stations or to authorize the temporary use or possession thereof by any department of the Government upon payment of just compensation."}},{"id":"PH-H1677-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"This temporary permit shall be subject to amendment, alteration, or repeal by the Congress of the Philippines when the public interest so requires, and shall not be interpreted as an exclusive grant of the privileges herein provided for."}},{"id":"PH-H1677-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"his Act shall take effect upon its approval.\nApproved: June 22, 1957."}}],"pack":"ph-p23","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Granting the Aguinaldo Development Corporation a Temporary Permit to Construct, Establish, Maintain and Operate Private Fixed Point-to-Point Radio Stations for the Reception and Transmission of Radio Communications Within the Philippines","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H1678"] = {"id":"PH-H1678","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1957/ra_1844_1957.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"宣布律师资格考试与专业资格考试为文官考试的法案","en":"An Act Declaring the Bar and Board Examinations as Civil Service Examinations","orig":"An Act to Amend Section One of Republic Act Numbered Ten Hundred Eighty, Entitled “An Act Declaring the Bar and Board Examinations as Civil Service Examinations”"},"level":"law","status":"active","topics":["administrative"],"docNumber":"Republic Act No. 1844","issuingBody":"Congress of the Philippines","promulgatedDate":"1957-06-22","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1957/ra_1844_1957.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1678-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Section one of Republic Act Numbered Ten hundred eighty is amended to read as follows:\n\"Sec. 1. The bar examinations and the examinations given by the various boards of examiners of the Government are declared as civil service examinations, and shall, for purpose of appointment of positions in the classified service the duties of which involve knowledge of the respective professions, except positions requiring highly specialized knowledge not covered by the ordinary board examinations, be considered as equivalent to the first grade regular examination given by the Bureau of Civil Service if the profession requires at least four years of study in college, and as equivalent to the second grade regular examination if the profession requires less than four years of college study: Provided, however, That such bar or board examination shall be equivalent to the next lower grade of civil service examination when the person is to be employed in a position other than one requiring his professional knowledge: And provided, further, That if under any law, a person is exempted from the examinations given by the various boards of examiners, and a certificate of registration for or admission to the practice of his profession is issued in his favor by the corresponding board of examiners, he shall be deemed for all legal purposes to have passed the required board examination for the practice of his profession.\""}},{"id":"PH-H1678-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 22, 1957"}}],"pack":"ph-p23","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Declaring the Bar and Board Examinations as Civil Service Examinations","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H1679"] = {"id":"PH-H1679","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1957/ra_1845_1957.html","fetchedAt":"2026-10-06","articleCount":13,"structureMode":"ARTICLE","title":{"zh":"授予 Tagum 农业开发公司在菲律宾境内建设、维护和运营私人固定点对点与陆基无线电台的临时许可的法案","en":"An Act Granting the Tagum Agricultural Development Company, Inc. a Temporary Permit to Construct, Maintain and Operate Private Fixed Point-to-Point and Land Based Radio Stations for the Reception and Transmission of Radio Communications Within the Philippines","orig":"An Act Granting the Tagum Agricultural Development Company, Inc. a Temporary Permit to Construct, Maintain and Operate Private Fixed Point-to-Point and Land Based Radio Stations for the Reception and Transmission of Radio Communications Within the Philippines"},"level":"law","status":"active","topics":["environment"],"docNumber":"Republic Act No. 1845","issuingBody":"Congress of the Philippines","promulgatedDate":"1957-06-22","completenessNote":"全文，共 13 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1957/ra_1845_1957.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1679-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There is hereby granted to the Tagum Agricultural Development Company, Inc., its successors or assigns, hereinafter referred to as \"grantee,\" a temporary permit to construct, maintain and operate in the cities of Manila, Davao and Cagayan de Oro, and at such other places in the Philippines as the grantee may select with the approval of the Secretary of Public Works and Communications, private fixed point-to-point and land based radio stations for the reception and transmission of wireless messages on radiotelegraphy or radiotelephony, each station to be provided with a radio transmitting apparatus and a radio receiving apparatus."}},{"id":"PH-H1679-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This temporary permit shall continue to be in force during the time that the Government has not established similar service at the places selected by the grantee, and is granted upon the express condition that the same shall be void unless the construction or installation of said station be begun within one year from the date of the approval of this Act and be completed within two years from said date."}},{"id":"PH-H1679-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The grantee, its successors and assigns, shall not engage in domestic business of telecommunications in the Philippines, it being understood that the purpose of this temporary permit is to secure to the grantee the right to construct, install, maintain and operate private fixed point-to-point and land based radio stations in the cities of Manila, Davao, and Cagayan de Oro, and at such other places within the Philippines as the interests of the grantee may justify."}},{"id":"PH-H1679-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"No fees shall be charged by the grantee as the radio stations that may be established by virtue of this Act shall engage in communications regarding the grantee's business only."}},{"id":"PH-H1679-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"The grantee, its successors or assigns, shall so construct and operate its radio stations as not to interfere with the operation of other radio stations maintained and operated in the Philippines."}},{"id":"PH-H1679-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"The grantee shall file a bond in the amount of fifty thousand pesos to guaranty full compliance and fulfillment of the conditions under which this temporary permit is granted."}},{"id":"PH-H1679-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"The grantee, its successors or assigns, shall hold the national, provincial, city and municipal governments of the Philippines harmless from all claims, accounts, demands or actions arising out of accidents or injuries whether to property or to persons, caused by the construction or operation of its radio stations."}},{"id":"PH-H1679-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"The grantee, its successors or assigns, shall be subject to the corporation laws of the Philippines nor existing or hereafter enacted."}},{"id":"PH-H1679-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"The grantee shall not lease, transfer, grant to usufruct of, sell or assign this temporary permit, nor the rights or privileges acquired thereunder to any person, firm, company, corporation or other commercial or legal entity, nor merge with any other person, firm, company, or corporation organized for the same purpose, without the approval of the Congress of the Philippines first had. Any corporation to which this temporary permit may be sold, transferred, or assigned, shall be subject to the corporation laws of the Philippines now existing or hereafter enacted, and any person, firm, company, corporation, or other commercial or legal entity to which this temporary permit is sold, or assigned shall be subject to all conditions, terms, restrictions and limitations of this temporary permit as fully and completely and to the same extent as if the temporary permit had been originally granted to the said person, firm, company, corporation or other commercial or legal entity."}},{"id":"PH-H1679-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"The grantee, its successors or assigns, is authorized to operate its private fixed point-to-point and land based radio stations on the medium frequency, high frequency, and very high frequency, that may be assigned to it by the Secretary of Public Works and Communications."}},{"id":"PH-H1679-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"A special right is hereby reserved to the President of the Philippines in time of war, insurrection, public peril, emergency, calamity or disaster to cause the closing of the grantee's radio stations or to authorize the temporary use, or possession thereof by any department of the Government upon payment of just compensation."}},{"id":"PH-H1679-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"This temporary permit shall be subject to amendment, alteration, or repeal by the Congress of the Philippines when public interest so requires, and shall not be interpreted as an exclusive grant of the privileges herein provided for."}},{"id":"PH-H1679-A13","no":13,"noLabel":{"en":"Section 13."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 22, 1957."}}],"pack":"ph-p23","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Granting the Tagum Agricultural Development Company, Inc. a Temporary Permit to Construct, Maintain and Operate Private Fixed Point-to-Point and Land Based Radio Stations for the Reception and Transmission of Radio Communications Within the Philippines","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H1680"] = {"id":"PH-H1680","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1957/ra_1846_1957.html","fetchedAt":"2026-10-06","articleCount":13,"structureMode":"ARTICLE","title":{"zh":"授予 Hercules 木材公司在菲律宾境内设立、维护和运营私人固定点对点无线电话站的临时许可的法案","en":"An Act Granting the Hercules Lumber Company, Incorporated, a Temporary Permit to Establish, Maintain and Operate Private Fixed Point-to-Point Radiotelephone Stations for the Transmission and Reception of Wireless Messages to and from Said Stations","orig":"An Act Granting the Hercules Lumber Company, Incorporated, a Temporary Permit to Establish, Maintain and Operate Private Fixed Point-to-Point Radiotelephone Stations for the Transmission and Reception of Wireless Messages to and from Said Stations"},"level":"law","status":"active","topics":["company"],"docNumber":"Republic Act No. 1846","issuingBody":"Congress of the Philippines","promulgatedDate":"1957-06-22","completenessNote":"全文，共 13 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1957/ra_1846_1957.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1680-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The Hercules Lumber Company, Incorporated, its successors or assigns, is hereby granted a temporary permit to establish, maintain and operate private fixed point-to-point radiotelephone stations in the Municipality of Alicia, Province of Zamboanga del Sur and in other parts of the Philippines where it operates its lumber business, subject to the approval of the Secretary of Public Works and Communications, for the transmission and reception of wireless messages to and from these stations, including its tugboats."}},{"id":"PH-H1680-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The President of the Philippines shall have the power and authority to permit the construction, maintenance, and operation of said private fixed point-to-point radiotelephone stations on any land of the public domain upon such terms as he may prescribe."}},{"id":"PH-H1680-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The temporary permit granted under this Act shall continue to be in force while the Government has not established similar service at places hereinabove stated, and subject to the condition that the grantee, its successors or assigns, shall start operation under said permit within one and half years from the date of the approval of this Act."}},{"id":"PH-H1680-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"The grantee, its successors or assigns, shall not engage in domestic business of telecommunication in the Philippines, it being understood that the temporary permit granted under this Act merely secures the right of the grantee to establish, maintain and operate private fixed point-to-point radiotelephone stations at the places hereinabove stated for no other purpose than to promote, protect, and subserve the trade and business interests of the grantee as a lumber company."}},{"id":"PH-H1680-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"The actual operation of said private fixed point-to-point radiotelephone stations shall not commence until after the Secretary of Public Works and Communications shall have allotted to the grantee the frequencies and wave lengths to be used thereunder."}},{"id":"PH-H1680-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"The grantee, its successors or assigns, shall so construct and operate such stations as not to interfere with the operation of other radio stations maintained and operated in the Philippines."}},{"id":"PH-H1680-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"The grantee, its successors or assigns, shall hold the national, provincial, city and municipal governments of the Philippines harmless from all claims, accounts, demands, or actions arising out of accidents or injuries whether to property or to persons, caused by the construction or operation of its radiotelephone stations."}},{"id":"PH-H1680-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"The grantee shall not lease, transfer, grant the usufruct of, sell or assigns this temporary permit, nor the rights or privileges acquired thereunder to any person, firm, company, corporation or other commercial or legal entity, nor merge with any other person, company or corporation organized for the same purpose, without the approval of the Congress of the Philippines first had. Any corporation to which this temporary permit may be sold transferred, or assigned, shall be subject to the corporation laws of the Philippines now existing or hereafter enacted, and any person, firm, company, corporation or other commercial or legal entity to which this temporary permit is sold, transferred, or assigned shall be subject to all conditions, terms, restrictions and limitations of this temporary permit as fully and completely and to the same extent as if the temporary permit had been originally granted to the said person, firm, company, corporation or other commercial or legal entity."}},{"id":"PH-H1680-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"The grantee, its successors or assigns, shall be subject to the corporation laws of the Philippines now existing or which may hereafter be enacted."}},{"id":"PH-H1680-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"A special right is hereby reserved to the President of the Philippines in time of war, rebellion, public peril, emergency, calamity, disaster or disturbance of peace or order to cause the closing of the grantee's radiotelephone stations or to authorize the temporary use and operation thereof by any department of the Government upon payment of just compensation."}},{"id":"PH-H1680-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"The temporary permit granted under this Act shall be subject to amendment, alteration, or repeal by the Congress of the Philippines when the public interest so requires, and shall not be interpreted as an exclusive grant of the privileges herein provided for."}},{"id":"PH-H1680-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"The grantee shall file a bond in the amount of fifty thousand pesos to guarantee full compliance and fulfillment of the conditions under which this temporary permit is granted."}},{"id":"PH-H1680-A13","no":13,"noLabel":{"en":"Section 13."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 22, 1957."}}],"pack":"ph-p23","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Granting the Hercules Lumber Company, Incorporated, a Temporary Permit to Establish, Maintain and Operate Private Fixed Point-to-Point Radiotelephone Stations for the Transmission and Reception of Wireless Messages to and from Said Stations","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H1681"] = {"id":"PH-H1681","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1957/ra_1847_1957.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":"在圣巴勃罗市设立国立工艺学校并为此授权拨付所需经费的法案","en":"An Act to Provided for the Establishment of a National School of Arts and Trades in the City of San Pablo and Authorizing the Appropriation of Necessary Funds for the Purpose","orig":"An Act to Provided for the Establishment of a National School of Arts and Trades in the City of San Pablo and Authorizing the Appropriation of Necessary Funds for the Purpose"},"level":"law","status":"active","topics":["education","culture"],"docNumber":"Republic Act No. 1847","issuingBody":"Congress of the Philippines","promulgatedDate":"1957-06-22","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1957/ra_1847_1957.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1681-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The Director of Public Schools is hereby authorized and directed to establish a national school of arts and trades in the City of San Pablo, which will offer a trade technical curriculum for high school graduates, the four-year secondary trade curriculum, and trade opportunity courses."}},{"id":"PH-H1681-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"With the approval of the Secretary of Education, the Director of Public Schools shall issue such rules and regulations as may be necessary to carry out the purposes of this Act."}},{"id":"PH-H1681-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The sum of fifty thousand pesos is hereby authorized to be appropriated annually, out of any funds is the National Treasury not otherwise appropriated, to carry out the purposes of this Act. If and when a peace treaty shall be entered into between the Philippines and Japan, the equipment necessary for this school shall be included in the reparations articles to be requisitioned from Japan."}},{"id":"PH-H1681-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 22, 1957."}}],"pack":"ph-p23","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act to Provided for the Establishment of a National School of Arts and Trades in the City of San Pablo and Authorizing the Appropriation of Necessary Funds for the Purpose","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H1682"] = {"id":"PH-H1682","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1957/ra_1848_1957.html","fetchedAt":"2026-10-06","articleCount":13,"structureMode":"ARTICLE","title":{"zh":"授予 H. R. Lopez Co.，Inc. 在菲律宾境内建设、安装、设立和运营私人固定点对点与海岸无线电台的临时许可的法案","en":"An Act Granting to H. R. Lopez Co., Inc. a Temporary Permit to Construct, Install, Establish and Operation Private Fixed Point-to-Point and Private Coastal Radio Stations for the Reception and Transmission of Radio Communications Within the Philippines","orig":"An Act Granting to H. R. Lopez Co., Inc. a Temporary Permit to Construct, Install, Establish and Operation Private Fixed Point-to-Point and Private Coastal Radio Stations for the Reception and Transmission of Radio Communications Within the Philippines"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 1848","issuingBody":"Congress of the Philippines","promulgatedDate":"1957-06-22","completenessNote":"全文，共 13 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1957/ra_1848_1957.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1682-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There is hereby granted to H. R. Lopez Co., Inc., a temporary permit to construct, install, establish and operate in the Philippines and at such places as the company may select, subject to the approval of the Department Secretary under whose jurisdiction the Radio Control Division is functioning, or any competent authority who is or shall be authorized, to give said approval, such private fixed point-to-point and land-based and land-mobile radio stations for the reception and transmission of wireless messages on radiotelephony, each station to consist of two radio apparatus comprising of a receiving and sending radio apparatus."}},{"id":"PH-H1682-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The President of the Philippines shall have the power and authority to permit the location of said private fixed point-to-point and land-based radio stations or any of them on the public domain upon such terms as he may prescribe."}},{"id":"PH-H1682-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This permit shall continue to be in force during the time that the Government has not established similar service at the places selected by the grantee."}},{"id":"PH-H1682-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"H. R. Lopez Co., Inc., shall not engage in domestic business of telecommunications in the Philippines without further special assent of the Congress of the Philippines, it being understood that the purpose of this temporary permit is to secure to the grantee the right to construct, install, establish and operate private fixed point-to-point and land-based radio stations in places within the Philippines as its interest and that of its trade and business may justify."}},{"id":"PH-H1682-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"A special right is hereby reserved to the President of the Philippines in time of war, insurrection, public peril, emergency, calamity, or disturbance of peace or order, to cause the closing of the station or stations or to authorize the temporary use or possession thereof by any department of the Government upon payment of just compensation."}},{"id":"PH-H1682-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"No fees shall be charged by the grantee as the radio stations that may be established by virtue of this Act shall engage in communication regarding the grantee's business only."}},{"id":"PH-H1682-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"The grantee, its successors or assigns, shall hold the national, provincial, and municipal governments of the Philippines harmless from all claims, accounts, demands or actions arising out of accidents or injuries, whether to property or to persons, caused by the construction or operation of the stations for reception and transmission of wireless messages by it."}},{"id":"PH-H1682-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"The grantee, shall so construct and operate its radio stations as not to interfere with the operation of other radio stations maintained and operated in the Philippines."}},{"id":"PH-H1682-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"The grantee shall be subject to the corporation laws of the Philippines now existing or which may hereafter be enacted."}},{"id":"PH-H1682-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"The grantee is hereby authorized to operate its private stations on commercial frequencies that may be assigned to it by the licensing authority."}},{"id":"PH-H1682-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"The grantee shall not lease, transfer, grant the usufruct of, sell or assign this temporary permit, nor the rights or privileges acquired thereunder to any person, firm, company, corporation or other commercial or legal entity, nor merge with any other person, company or corporation organized for the same purpose, without the approval of the Congress of the Philippines first had. Any corporation to which this temporary permit may be sold, transferred, or assigned, shall be subject to the corporation laws of the Philippines now existing or hereafter enacted, and any person, firm, company, corporation or other commercial or legal entity to which this temporary permit is sold, transferred, or assigned shall be subject to all conditions terms, restrictions and limitations of this temporary permit as fully and completely and to the same extent as if the temporary permit had been originally granted to the said person, firm, company, corporation or other commercial or legal entity."}},{"id":"PH-H1682-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"This permit shall be subject to amendment, alteration, or repeal by the Congress of the Philippines when the public interest so requires, and shall not be interpreted to mean as an exclusive grant of the privilege herein provided for."}},{"id":"PH-H1682-A13","no":13,"noLabel":{"en":"Section 13."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 22, 1957."}}],"pack":"ph-p23","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Granting to H. R. Lopez Co., Inc. a Temporary Permit to Construct, Install, Establish and Operation Private Fixed Point-to-Point and Private Coastal Radio Stations for the Reception and Transmission of Radio Communications Within the Philippines","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H1683"] = {"id":"PH-H1683","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1957/ra_1849_1957.html","fetchedAt":"2026-10-06","articleCount":18,"structureMode":"ARTICLE","title":{"zh":"授予 Butuan Sawmill，Inc. 在苏里高省 Lianga 市镇安装、运营和维护电灯、供热与动力系统的特许经营权法案","en":"An Act Granting the Butuan Sawmill, Inc. a Franchise to Install, Operate and Maintain an Electric Light, Heat and Power System in the Municipality of Lianga, Province of Surigao","orig":"An Act Granting the Butuan Sawmill, Inc. a Franchise to Install, Operate and Maintain an Electric Light, Heat and Power System in the Municipality of Lianga, Province of Surigao"},"level":"law","status":"active","topics":["investment"],"docNumber":"Republic Act No. 1849","issuingBody":"Congress of the Philippines","promulgatedDate":"1957-06-22","completenessNote":"全文，共 18 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1957/ra_1849_1957.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1683-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Subject to the conditions established in this Act and the provisions of Act Numbered Thirty-one hundred and eight and its amendments, applicable thereto, there is hereby granted to the Butuan Sawmill, Inc., for a period of fifty years from the approval of this Act, the right, privilege, and authority to construct, maintain and operate an electric light, heat, and power system, for the purpose of generating and distributing electric light, heat and power for sale within the limits of the Municipality of Lianga, Province of Surigao, Philippines. The grantee shall further have the right and privilege to install, lay, maintain on all streets, public thoroughfares, bridges and public places within said limits, poles, conductors interruptors, transformers, cables, wires, and other overhead appliances, and all other necessary apparatus and appurtenances for the furnishing and distribution of electric current and to supply, sell, and furnish such current to any person, corporation or public or private concern within said limits for provincial, municipal, domestic or manufacturing uses and for any other use to which electricity may be put, and to charge and collect a schedule of prices and conventional sets for the use of same: Provided, That this franchise shall not take effect until the grantee shall have obtained from the Public Service Commission a certificate showing the public necessity and convenience of the same in accordance with the purpose of subsection (i) of section fifteen of Act Numbered Thirty-one hundred and eight as amended, and shall have filed such certificate with the Secretary of Public Works and Communications upon accepting this franchise: And, Provided, further, That if the grantee does not file the proper application for said certificate with the Public Service Commission within six months from the date of the approval of this Act, this franchise shall become null and void."}},{"id":"PH-H1683-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The poles erected by the grantee shall be of such a height as to maintain the wires stretched on the same at a distance of at least twenty feet above the level of the ground, and shall be of such appearance as not to disfigure the streets, and shall be placed with due regard for the public safety so as not to be a danger to the same, in accordance with a plan approved by the provincial or municipal authorities concerned, represented by the provincial governor, or the municipal mayor, as the case may be, and said grantee shall supply electric power, heat and light to any applicant for the same within fifteen days after the date of his application, and as between such applicant and other applicants, in the order of the date of his application, up to the limit of the capacity of the plant of said grantee, to be determined by the electrical engineer of the Public Service Commission on the application of said grantee; and should the demand for electric power, heat and light at any time increase beyond the capacity of the plant of said grantee to supply the same, the capacity of said plant shall be increased by said grantee to meet such demand, in accordance with the decision of the Public Service Commission or its legal successors: Provided, However, That in case the point at which the electric light, heat, or power is to be supplied, is more than thirty meters from the lines or wires operated by said grantee, the latter shall not be obliged to furnish said service."}},{"id":"PH-H1683-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"All apparatus and appurtenances used by the grantee shall be modern and first class in every respect, and said wires shall be insulated and carefully connected and fastened so as not to come in direct contact with any object through which a ground could be formed, and shall be stretched so as not to interfere with the free use of said streets and public thoroughfares nor cause any injury to the public, danger of fire or damage and inconvenience to the owners of the property: Provided, That in the maintenance and operation of its plant and system for the transmission and distribution of electric current, the grantee shall always be subject to such reasonable regulations as the municipal council of Lianga and the provincial board of Surigao may promulgate in the premises and also to the regulations prescribed by the National Electrical Code of America: Provided, That the grantee shall, whenever the Congress of the Republic of the Philippines, upon recommendation of the Public Service Commission or its legal successor, so directs, place said wires in underground pipes or conduits at its own expense and without any cost and prejudice to the municipality above-mentioned."}},{"id":"PH-H1683-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Whenever it shall be necessary in the erection of said poles to take up any portion of the sidewalks or dig up the ground of the public streets or thoroughfares, then the said grantee shall, after said poles are erected, without delay replace said sidewalks in the proper manner or arrange said streets or public thoroughfares, removing from the same all rubbish, dirt, refuse or other materials which may have been placed there, taken up or dug up in the erection of said poles, leaving them in as good condition as they were before the work was done; and whenever it shall become necessary, by reason of the extension of streets or plazas as determined upon by the municipal council of the municipality above-mentioned to change the location of such poles, such change shall be made by the grantee, its successors or assigns, at their expense without delay, and said poles shall be placed where directed by said provincial board or said municipal council."}},{"id":"PH-H1683-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Whenever any person has obtained permission to use any of the streets or public thoroughfares of the municipality above-mentioned for the purpose of removing any building or in the prosecution of any municipal work or for any just cause whatsoever, making it necessary to raise or remove any of said poles or electric wires which may obstruct the removal of said building so as to allow the free and unobstructed prosecution of said work, the person or entity at whose request the building has been moved or the construction undertaken, shall pay one-half of the actual cost of removing or raising and of replacing the poles, wires and other overhead or underground conductors. The notice shall be served in the usual form, and in case of refusal or failure of the grantee to comply with such notice, the municipal mayor, with the proper approval of the municipal council first had, shall order such poles or wires to be raised or removed at the expense of said grantee, for the purpose aforesaid: Provided, However , That the grantee may appeal from any such decision to the provincial board of Surigao whose decision shall be final."}},{"id":"PH-H1683-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"The grantee shall be liable to the municipality above named for any injury arising from any claims caused by accidents to person or property by reason of the construction under this franchise or of any neglect or omission to keep the said poles and wires in a safe condition."}},{"id":"PH-H1683-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"Said grantee shall file his written acceptance of this franchise with the Secretary or Public Works and Communications within one hundred and eighty days from the date when he obtained the certificate required by section one of this Act and shall commence work under the supervision and subject to the approval of the electrical engineer of the Public Service Commission, in accordance with plan, specifications, and estimates previously approved by the Public Service Commission, within six months' time from and after the date of filing such acceptance, unless prevented by act of God, or force majeure, usurped or military power, martial law, riot or civil commotion or other inevitable cause, and shall complete the system and have the same in operation within eighteen months from the date of such acceptance, and shall thereafter maintain a first-class electric light, heat, and power service: Provided, That in consideration of the franchise hereby granted, the grantee shall pay quarterly into the municipal treasury of the municipality above named, one per centum of the gross earnings of his electrical business during the life of this franchise."}},{"id":"PH-H1683-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"Upon the acceptance of this franchise as provided in the preceding section, the grantee shall deposit in the National Treasury or with any of its agents in the Province of Surigao, one thousand pesos, or negotiable bonds of the Republic of the Philippines or other securities approved by the Secretary of Public Works and Communications, of the face value of one thousand pesos, as an earnest of good faith and a guarantee that he will begin the electric light, heat, and power business and may be completely provided with the necessary equipment therefor and ready to begin operation in accordance with the terms of this franchise: Provided, However , That if such deposit is in cash, it may be made with some official depository of the Government in the name of the grantee and subject to the order of the National Treasurer, who shall retain the evidence of the deposit so made. In this case, as well as in the case of the deposit being made in negotiable bonds or other securities, as provided in this section, the interest of the cash deposit or of the bonds or securities deposited if any, shall belong to the grantee.\nIn case such grantee shall fail, refuse or neglect, unless prevented by fortuitous cause or force majeure, public enemy, usurped or military power, martial law, riot, civil commotion, or other inevitable cause, to commence the work for the electric light, heat and power service within six months from the date of the acceptance of this franchise, or shall fail to provide the necessary equipment and be ready to operate within eighteen months after the date of such acceptance, in accordance with the terms of this franchise, then the deposit prescribed in this section and in the possession of the National Treasurer, whether in cash, bonds, or other securities, shall be forfeited to the provincial government of Surigao, as damages for the breach of implied contract involved in the acceptance of this franchise. In case the grantee begins to operate the electric light, heat, and power service and is ready for operation under this franchise, within the time limits specified, the deposit provided for in this section shall, upon recommendation by the Public Service Commission or its legal successor, be returned by the National Treasurer to said grantee: Provided, That the time during which such grantee has been prevented by any of the causes above referred to from carrying out the terms and conditions of this franchise shall be added to the time granted by this franchise for the fulfillment of its conditions."}},{"id":"PH-H1683-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"The municipality above named shall have the privilege, without compensation, of using the poles of the grantee for the purpose of installing, maintaining and operating a police telephone and alarm system, but the wires of such telephone and alarm system shall be placed and stretched in such manner as to cause no interference with or damage to the wires of the electric service of the grantee."}},{"id":"PH-H1683-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"The grantee is forbidden to issue stock or bonds under this franchise except in exchange for actual cash or for property at a fair valuation equal to the par value of the stock or bonds issued and upon prior authority of the Public Service Commission. Nor shall said grantee declare any stock or bond as dividend."}},{"id":"PH-H1683-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"The books and accounts of the grantee shall always be open to the inspection of the provincial treasurer of Surigao or his authorized representative, and it shall be the duty of the grantee to submit to the provincial treasurer quarterly reports in duplicate showing the gross receipts and the net receipts for the past quarter and the general condition of the business, one of which shall be forwarded by the provincial treasurer to the Auditor General who shall keep the same on file."}},{"id":"PH-H1683-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"The grantee shall pay on its real estate, buildings, plant, machinery, and other personal property the same taxes as are now or may hereafter be required by law from other persons."}},{"id":"PH-H1683-A13","no":13,"noLabel":{"en":"Section 13."},"text":{"en":"The grantee herein shall not, without the approval of the Public Service Commission first had, lease, grant, sell, convey or give in usufruct this franchise and the property and rights acquired thereunder to any person or corporation: Provided, That for the purpose of such lease, grant, sale, conveyance or giving in usufruct, it shall be necessary to file in the Office of the Secretary of Public Works and Communications an agreement in writing by which the person or corporation in whose favor such lease, grant, sale, conveyance, or giving in usufruct is made, shall bind himself to comply with all the terms and conditions imposed upon the grantee by this franchise and to accept the same subject to all existing terms and conditions: Provided, further, That in case of any national emergency affecting the endangering the public safety and order, the Republic of the Philippines shall have the right to take possession of the electric light system, as provided in this Act, and operate the same until such emergency shall have passed."}},{"id":"PH-H1683-A14","no":14,"noLabel":{"en":"Section 14."},"text":{"en":"The Public Service Commission, or its legal successor, after hearing the interested parties, upon notice and order in writing, shall have the power to declare the forfeiture of this franchise and all rights inherent in the same for failure on the part of the grantee to comply with any of the terms and conditions thereof, unless such failure shall have been directly and primarily caused by the act of God, public enemy or force majeure. Against such declaration of the forfeiture by the Public Service Commission or its legal successor, the grantee may apply for the remedies provided in section thirty-five of Act Numbered Three thousand one hundred eight, as amended."}},{"id":"PH-H1683-A15","no":15,"noLabel":{"en":"Section 15."},"text":{"en":"At any time after forty years from the date of the approval of this Act, the Republic of the Philippines or any of the political subdivisions thereof to which the right may be assigned, may purchase, and the grantee shall sell thereto, all of his plant, poles, wires, buildings, real estate, and all other property used in the enjoyment of this franchise, at a valuation based in part upon the net earnings of the grantee and its true worth on the books, making the proper deduction for depreciation; in part on the cost of the actual reproduction of said property, less depreciation and, in part, on the original cost of said property, less depreciation, the valuation to be determined after hearing by the Supreme Court of the Philippines, sitting as a board of directors, whose decision, by a majority of the members thereof, shall be final."}},{"id":"PH-H1683-A16","no":16,"noLabel":{"en":"Section 16."},"text":{"en":"The rates for the light service, flat rate, as well as meter rate, fixed by the grantee, shall always be subject to regulations by the Congress of the Philippines or by the proper authorities, and shall in no case be in excess of forty centavos per kilowatt hour: Provided, That only subscribers who have more than ten outlets installed in one building shall be entitled to be furnished with a meter."}},{"id":"PH-H1683-A17","no":17,"noLabel":{"en":"Section 17."},"text":{"en":"Whenever in this franchise the term \"grantee\" is used, it shall be held and understood to mean and represent the Butuan Sawmill, Inc., its representative, successors or assigns."}},{"id":"PH-H1683-A18","no":18,"noLabel":{"en":"Section 18."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 22, 1957."}}],"pack":"ph-p23","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Granting the Butuan Sawmill, Inc. a Franchise to Install, Operate and Maintain an Electric Light, Heat and Power System in the Municipality of Lianga, Province of Surigao","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H1684"] = {"id":"PH-H1684","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1957/ra_1850_1957.html","fetchedAt":"2026-10-06","articleCount":12,"structureMode":"ARTICLE","title":{"zh":"授予 Salt Industry of the Philippines，Inc. 设立、维护和运营私人固定点对点无线电话站以收发无线电报的临时许可的法案","en":"An Act Granting the Salt Industry of the Philippines, Inc. a Temporary Permit to Establish, Maintain and Operate Private Fixed Point-to-Point Radiotelephone Stations for the Transmission of Wireless Messages to and from Said Stations","orig":"An Act Granting the Salt Industry of the Philippines, Inc. a Temporary Permit to Establish, Maintain and Operate Private Fixed Point-to-Point Radiotelephone Stations for the Transmission of Wireless Messages to and from Said Stations"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 1850","issuingBody":"Congress of the Philippines","promulgatedDate":"1957-06-22","completenessNote":"全文，共 12 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1957/ra_1850_1957.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1684-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The Salt Industry of the Philippines, Inc., its successors or assigns, is hereby granted a temporary permit to establish, maintain and operate private fixed point-to-point radiotelephone stations in San Jose, Mindoro Occidental, and in other parts of the Philippines where it operates its business, subject to the approval of the Secretary of Public Works and Communications, for the transmission and reception of messages to and from said stations."}},{"id":"PH-H1684-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The President of the Philippines shall have the power and authority to permit the construction, maintenance, and operation of said private fixed point-to-point radiotelephone stations on any land of the public domain upon such terms as he may prescribe."}},{"id":"PH-H1684-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The temporary permit granted under this Act shall continue to be in force while the Government has not established similar service at places hereinabove stated, and subject to the condition that the grantee, its successors or assigns, shall start operation under said permit within one and a half years from the date of the approval of this Act."}},{"id":"PH-H1684-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"The grantee, its successors or assigns, shall not engage in domestic business of telecommunications in the Philippines, it being understood that the temporary permit granted under this Act merely secures the right of the grantee to establish, maintain and operate private fixed point-to-point radiotelephone stations at the places hereinabove stated for no other purpose than to promote, protect and subserve the trade and business interests of the grantee."}},{"id":"PH-H1684-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"The actual operation of said private fixed point-to-point radiotelephone stations shall not commence until after the Secretary of Public Works and Communications shall have allotted to the grantee the frequencies and wave lengths to be used thereunder."}},{"id":"PH-H1684-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"The grantee, its successors or assigns, shall construct and operate such stations as not to interfere with the operation of other radio stations maintained and operated in the Philippines."}},{"id":"PH-H1684-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"The grantee, its successors or assigns, shall hold the national, provincial city and municipal governments of the Republic of the Philippines harmless from all claims, accounts, demands or actions arising out of accidents or injuries, whether to property or to persons, caused by the construction or operation of its radiotelephone stations."}},{"id":"PH-H1684-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"The grantee, its successors or assigns, shall be subject to the corporation laws of the Philippines now existing or which may hereafter be enacted."}},{"id":"PH-H1684-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"The grantee shall not lease, transfer, grant the usufruct of, sell or assign this temporary permit, nor the rights or privileges acquired thereunder to any person, firm, company, corporation or other commercial or legal entity, nor merge with any other person, company or corporation organized for the same purpose, without the approval of the Congress of the Philippines first had. Any corporation to which this temporary permit may be sold, transferred, or assigned, shall be subject to the corporation laws of the Philippines now existing or hereafter enacted, and any person, firm, company, corporation or other commercial or legal entity to which this temporary permit is sold, transferred, or assigned shall be subject to all conditions, terms, restrictions and limitations of this temporary permit as fully and completely and to the same extent as if the temporary permit had been originally granted to the said person, firm, company, corporation or other commercial or legal entity."}},{"id":"PH-H1684-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"A special right is hereby reserved to the President of the Philippines in time of war, rebellion, public peril, emergency, calamity, disaster or disturbance of peace or order to cause the closing of the grantee's radiotelephone stations or to authorize the temporary use and operation thereof by any department of the Government upon payment of just compensation."}},{"id":"PH-H1684-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"The temporary permit granted under this Act shall be subject to amendment, alteration, or repeal by the Congress of the Philippines when the public interest so requires, and shall not be interpreted as an exclusive grant of the privileges herein provided for."}},{"id":"PH-H1684-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 22, 1957."}}],"pack":"ph-p23","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Granting the Salt Industry of the Philippines, Inc. a Temporary Permit to Establish, Maintain and Operate Private Fixed Point-to-Point Radiotelephone Stations for the Transmission of Wireless Messages to and from Said Stations","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H1685"] = {"id":"PH-H1685","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1957/ra_1851_1957.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"设立宿务火灾损失委员会并为其他目的法案","en":"An Act Creating the Cebu Fire Damage Commission, and for Other Purposes","orig":"An Act Creating the Cebu Fire Damage Commission, and for Other Purposes"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 1851","issuingBody":"Congress of the Philippines","promulgatedDate":"1957-06-22","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1957/ra_1851_1957.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1685-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There is hereby created a Cebu Fire Damage Commission to be composed of a representative each of the President, of the National Red Cross, and of the Social Welfare Administration, which shall have the duty and power to render aid and assistance to those rendered homeless and destitute because of that fire; and to receive and award claims for damages from any person whose home suffered any damage by reason of that fire. The Commission shall issue the necessary rules and regulations for carrying out the objectives of this Act, and its award shall be final and unappealable: Provided, That the Commission shall give priority in paying awards of one thousand pesos or less."}},{"id":"PH-H1685-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"There is hereby set aside the sum of five million pesos, out of any funds in the National Treasury not otherwise appropriated, which shall be used to extend aid and assistance to those rendered homeless by the fire, and also to pay the awards as well as other expenses of administration of the Commission."}},{"id":"PH-H1685-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 22, 1957."}}],"pack":"ph-p23","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Creating the Cebu Fire Damage Commission, and for Other Purposes","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H1686"] = {"id":"PH-H1686","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1957/ra_1852_1957.html","fetchedAt":"2026-10-06","articleCount":20,"structureMode":"ARTICLE","title":{"zh":"修订并废止第 327 号共和国法（即 Dumaguete 市宪章）若干条款的法案","en":"An Act Amending and Repealing Certain Sections of Republic Act Numbered Three Hundred Twenty-Seven, Otherwise Known as the Charter of the City of Dumaguete","orig":"An Act Amending and Repealing Certain Sections of Republic Act Numbered Three Hundred Twenty-Seven, Otherwise Known as the Charter of the City of Dumaguete"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 1852","issuingBody":"Congress of the Philippines","promulgatedDate":"1957-06-22","completenessNote":"全文，共 20 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1957/ra_1852_1957.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1686-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Section five of Republic Act Numbered Three hundred twenty-seven, otherwise known as the Charter of the City of Dumaguete, is amended to read as follows:\n\"Sec. 5. The City not liable for damages. -The City shall not be liable or held for damages or injuries to persons or property arising from the failure of the Municipal Board, the Mayor or any other city officer or employee, to enforce the provisions of the Charter, or any other law or ordinance, or from negligence of said Municipal Board, Mayor or other city officers or employees while enforcing or attempting to enforce the provisions thereof.\""}},{"id":"PH-H1686-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The second paragraph of section seven of the same Act is amended to read as follows:\n\"He shall receive the salary provided for in Republic Act Numbered Eight hundred forty, and non-commutable allowance of not exceeding five thousand pesos per annum.\""}},{"id":"PH-H1686-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Section eleven of the same Act is amended to read as follows:\n\"Sec. 11. Constitution and organization of the Municipal Board; Compensation of members thereof . -The Municipal Board shall be the legislative body of the city and shall be composed of the Vice-Mayor, who shall be its presiding officer, and eight councilors, who shall be elected at large by popular vote during every election for provincial and municipal officials in conformity with the provisions of the Revised Election Code. The Vice-Mayor shall have no right to vote except in case of a tie. In case of sickness, absence, or other temporary incapacity of the Vice-Mayor, or when he acts as Mayor, the Board shall designate one of its members to sit as temporary presiding officer, without additional compensation. In case of sickness, absence, suspension or temporary disability of any member of the Board, or if necessary to maintain a quorum, the President of the Philippines may appoint a temporary substitute who shall possess all the rights and perform all the duties of a member of the Board until the return to duty of the regular incumbent.\n\"If any member of the Municipal Board should be candidate for office in any election, he shall be disqualified to act with the Board in the discharge of the duties conferred upon it relative to election matters, and in such case the other members of the Board shall discharge said duties without his assistance, or the Mayor may choose some disinterested elector of the city to act with the Board in such matters in his stead.\n\"The members of the Municipal Board shall receive twenty-five pesos for each day of attendance of the session of the Board.\""}},{"id":"PH-H1686-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"The first paragraph of section thirteen of the same Act is amended to read as follows:\n\"Sec. 13. Appointment, salary, and duties of Secretary of Board. -The Board shall have a secretary who shall be appointed by the Mayor with the consent of the Board to serve during the term of office of the members thereof. The secretary shall receive the salary provided for in Republic Act Numbered Eight hundred forty. In case of disagreement between the Board and the Mayor, the Executive Secretary shall decide and his decision shall be final. A vacancy in the office of the secretary may be filled temporarily by the Mayor.\""}},{"id":"PH-H1686-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Section fourteen of the same Act is amended to read as follows:\n\"Sec. 14. Method of transacting business by the Board—Veto—Authentication and publication of ordinances. — The Board shall hold one ordinary session for the transaction of business during each week on a day which it shall fix by resolution, and such extraordinary sessions, not exceeding thirty during any one year, as may be called by the Mayor. It shall sit with open doors, unless otherwise ordered by an affirmative vote of five members. It shall keep a record of its proceedings and determine its rules of procedure not herein set forth. Five members of the Board shall constitute a quorum for the transaction of business. But a smaller number may adjourn from day to day and may compel the immediate attendance of any member absent without good cause by issuing to the police of the city an order for his arrest and production at the session under such penalties as shall have been previously prescribed by ordinance. Five affirmative votes shall be necessary for the passage of any ordinance, or of any resolution or motion directing the payment of money or creating liability, but other measures shall prevail upon the majority votes of the members present at any meeting duly called and held. The ayes and nays shall be taken and recorded upon the passage of all ordinances, upon all resolutions or motions directing the payment of money or creating liability, and at the request of any member, upon any other resolution or motion. Each approved ordinance, resolution or motion shall be sealed with the seal of the Board, signed by the presiding officer and the secretary of the Board and recorded in a book for the purpose and shall, on the day following its passage, be posted by the secretary at the main entrance to the city hall, and shall take effect and be in force on and after the tenth day following its passage unless otherwise stated in said ordinance, resolution or motion or vetoed by the Mayor as hereinafter provided. A vetoed ordinance, if repassed, shall take effect ten days after the veto is overridden by the required votes unless otherwise stated in the ordinance.\n\"Each ordinance and each resolution or motion directing the payment of money or creating liability enacted or adopted by the Board shall be forwarded to the Mayor for his approval. Within ten days after the receipt of the ordinance, resolution or motion, the Mayor shall return it with his approval or veto. If he does not return it within that time, it shall be deemed to be approved. If he returns it with his veto, his reasons therefor in writing shall accompany it, otherwise, the veto shall be null and void and the ordinance, resolution or motion considered as approved. If after it is validly vetoed, it is again enacted by the affirmative votes of six members of the Board, it shall be deemed approved. The Mayor shall have the power to veto any particular item or items of an appropriation ordinance, or of an ordinance, resolution or motion directing the payment of money or creating liability, but the veto shall not affect the item or items to which he does not object. The item or items objected to shall not take effect except in the manner heretofore provided in this section as to ordinances, resolutions, and motions returned to the Board with his veto, but should an item or items in an appropriation ordinance be disapproved by the Mayor, the corresponding item or items in the appropriation ordinance of the previous year shall be deemed restored unless otherwise expressly directed in the veto.\""}},{"id":"PH-H1686-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"Sub-section (y), section fifteen of the same Act, is amended to read as follows:\n\"(y) Subject to the provisions of subsection (f) of section one thousand nine hundred one of the Administrative Code, to provide for the laying out, construction, and improvement, and to regulate the use, of streets, avenues, alleys, sidewalks, wharves, piers, parks, cemeteries, and other public places; to provide for lighting, cleaning, and sprinkling of streets and public places; to regulate, fix license fees for, and prohibit the use of the same for processions, signs, signposts, awnings, awning posts, the carrying or displaying of banners, placards, advertisements, or handbills or the flying of signs, flags, or banners, whether along, across, over or from buildings, along the same; to prohibit the placing, throwing, depositing, or leaving of obstacles of any kind, offal, garbage, refuse or other offensive matter or matters liable to cause damage, in the streets and other public places, and to provide for the collection and disposition thereof; to provide for the inspection of, fix the license fees for, and regulate the openings in the same for the laying of gas, water, sewer, and other pipes, the buildings and repair of tunnels, sewers, and drains, and all structures in and under the same, and the erecting of poles and the stringing of wires therein; to provide for and regulate cross-walks, curbs, and gutters therein; to name streets without a name and provide for and regulate and numbering of houses and lots fronting thereon or in the interior of the blocks; to regulate traffic and sales upon the streets and other public places; to provide for the abatement of nuisances in the same and punish the authors or owners thereof; to provide for the construction and maintenance, and regulate the use of bridges, viaducts, and culverts; to prohibit or regulate ball playing, kite flying, hoop rolling, and other amusements which may annoy persons using the streets and public places, or frighten horses or other animals; to regulate the speed of horses and other animals, motor and other vehicles, cars, and locomotives within the limits of the city; to regulate the locating, constructing, and laying of the track of horse, electric, and other forms of railroad in the streets or other public places of the city authorized by law; unless otherwise provided by law, to provide for and change the location, grade, and crossing of railroads, and to compel any such railroad to raise or lower its track to conform to such provisions or charges; to require railroad companies to fence their property, or any part thereof, and to construct and repair ditches, drains, sewers, and culverts along and under their tracks, so that the natural drainage of the streets and adjacent property shall not be obstructed; and to regulate the location, installation, and operation of factories and/or other plants run by motor engines or electricity, giving the owners or operators thereof at least one year to transfer to such places as may be designated in the city zonification ordinances. The Board may grant extension of time within which such transfer shall be effected, provided that such extension does not exceed one year.\""}},{"id":"PH-H1686-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"The first paragraph of section nineteen of the same Act is amended to read as follows:\n\"Sec. 19. Appointment and removal of officials and employees.— The President of the Philippines shall appoint with the consent of the Commission on Appointments, the judge and auxiliary judge of the municipal court, the city treasurer, the city engineer, the city attorney, the chief of police, and the other heads of such city departments as may be created and not otherwise provided by law. Except the judge and the auxiliary judge of the municipal court, said officers shall hold office at the pleasure of the President: Provided, That the incumbent justice of the peace shall continue in office as judge of the municipal court without the necessity of a new appointment.\""}},{"id":"PH-H1686-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"Sub-section (g), section twenty-two of the same Act, is amended to read as follows:\n\"(g) He shall have the care and custody of all public docks, wharves, piers, levees, and handling places owned by the city, and the care and custody, supervision, administration and control of the Dumaguete pier, Dumaguete seawall, and all foreshore lands within the territorial jurisdiction of the city.\""}},{"id":"PH-H1686-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"The first paragraph of section twenty-four of the same Act is amended to read as follows:\n\"Sec. 24. The City Attorney—His powers and duties. -There shall be a city attorney and one assistant city attorney, who shall be the legal advisers of the city. The city attorney shall receive the salary provided for in Republic Act Numbered Eight hundred forty and the assistant city attorney shall receive a salary not exceeding three thousand one hundred and twenty pesos per annum. The city attorney shall have the following powers and duties:\""}},{"id":"PH-H1686-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"The first paragraph of section twenty-five of the same Act is amended to read as follows:\n\"Sec. 25. The Chief of Police—His powers, duties and compensation. -There shall be a chief of police who shall have charge of the police department. He shall receive the salary provided for in Republic Act Numbered Eight hundred forty. He shall have the following general powers and duties:\""}},{"id":"PH-H1686-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"Section twenty-six of the same Act is repealed."}},{"id":"PH-H1686-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"The first paragraph of section twenty-eight of the same Act is amended to read as follows:\n\"Sec. 28. Chief of Fire Department—His powers, duties, and compensation. -There shall be a chief of fire department who shall be appointed by the Mayor with the consent of the Municipal Board. He shall have charge of said department. He shall receive the salary provided for in Republic Act Numbered Eight hundred forty. He shall have the following general powers and duties:\""}},{"id":"PH-H1686-A13","no":13,"noLabel":{"en":"Section 13."},"text":{"en":"Subsection (a), section thirty of the same Act, is amended to read as follows:\n\"(a) Lands or buildings owned by the Republic of the Philippines, the Province of Negros Oriental or the City of Dumaguete and burying grounds, churches, and their adjacent parsonages and convents, and lands or buildings used exclusively for, and actually devoted to, religious, charitable, scientific, or educational purposes, and not for profit; but such exemption shall not extend to lands or buildings held for investment, lands and/or buildings not actually utilized and/or devoted to religious, charitable, scientific or educational purposes although they are owned by religious, charitable, scientific, or educational institutions, though the income therefrom be devoted to, and used for, religious, charitable, scientific, or educational purposes.\""}},{"id":"PH-H1686-A14","no":14,"noLabel":{"en":"Section 14."},"text":{"en":"Section seventy-four of the same Act is amended to read as follows:\n\"Sec. 74. Failure to enact an appropriation ordinance. -Whenever the Board fails to enact an appropriation ordinance for any fiscal year before the end of the previous fiscal year, the several sums appropriated in the last appropriation ordinance for the objects and purposes therein specified, so far as they may be done, shall be deemed to be reappropriated for the several objects and purposes specified in said last appropriation ordinance, and shall go into effect on the first day of the new fiscal year in the appropriation ordinance for that year, until a reappropriation ordinance is duly enacted.\n\"Any provision of existing laws to the contrary notwithstanding, the budget shall be submitted to the Department of Finance only in case of conflict between the Municipal Board and the City Mayor.\""}},{"id":"PH-H1686-A15","no":15,"noLabel":{"en":"Section 15."},"text":{"en":"The second and fourth paragraphs of section seventy-five of the same Act are amended to read as follows:\n\"The municipal judge shall be allowed a vacation of not more than thirty days every year with salary, which vacation may be cumulated. The auxiliary municipal judge shall discharge the duties in case of absence, incapacity or inability of the municipal judge until he resumes his post, or until a new judge shall have been appointed. During his incumbency the auxiliary municipal judge shall enjoy the powers, emoluments and privileges of the municipal judge who shall not receive any remuneration therefor except the salary to which he is entitled by reason of his vacation provided for in this Act.\n\"The municipal judge shall receive the salary provided for in Republic Act Numbered Eight hundred forty.\""}},{"id":"PH-H1686-A16","no":16,"noLabel":{"en":"Section 16."},"text":{"en":"The first paragraph of section seventy-six of the same Act is amended to read as follows:\n\"Sec. 76. Clerk and employees of the municipal court. -There shall be a clerk of the municipal court who shall be appointed by the Secretary of Justice in accordance with Civil Service Law, rules and regulations, and who shall receive a compensation not exceeding two thousand four hundred pesos per annum. He shall keep the seal of the court and affix it to all orders, judgments, certificates, records, and other documents issued by the court. He shall keep a docket of the trials in the court, in which he shall record in a summary manner the names of the parties and the various proceedings in civil cases, and in criminal cases, the name of the defendant, the charge against him the names of the witnesses, the date of the arrest, the appearance of the defendant, together with the fines and costs adjudged or collected in accordance with the judgment. He shall have the power to administer oath and to act as notary public ex officio.\""}},{"id":"PH-H1686-A17","no":17,"noLabel":{"en":"Section 17."},"text":{"en":"Section eighty-three of the same Act is amended to read as follows:\n\"Sec. 83. The General Auditing Office—City Auditor. -The City Auditor, under the supervision of the Auditor General shall receive and audit all accounts of the city, in accordance with the provisions of law relating to government accounts and accounting. He shall be appointed by the Auditor General and shall receive a salary of not exceeding four thousand eight hundred pesos per annum, fifty per cent of which salary shall be payable from the funds of the city, and the remaining fifty per cent, from national funds.\""}},{"id":"PH-H1686-A18","no":18,"noLabel":{"en":"Section 18."},"text":{"en":"Section eighty-five of the same Act is amended to read as follows:\n\"Sec. 85. The Bureau of Public Schools. -The Director of Public Schools shall exercise the same jurisdiction and powers in the city as elsewhere in the Philippines. There shall be a city superintendent of schools who shall be appointed by the Secretary of Education, and who shall receive a salary of not exceeding four thousand eight hundred pesos per annum. He shall have all the powers and duties in respect to the schools of the city as are vested in division superintendents in respect to schools of their divisions.\n\"A city school board of six members, two of whom shall be women and who shall serve without salary, shall be selected and removed in the same manner, and shall have the same powers and duties, as local school boards in the municipalities.\n\"The municipal board shall have the same powers in respect to the establishment of schools as are conferred by law on municipal councils.\""}},{"id":"PH-H1686-A19","no":19,"noLabel":{"en":"Section 19."},"text":{"en":"A new section, to be known as section eighty-nine-A, is inserted between sections eighty-nine and ninety of the same Act, to read as follows:\n\"Sec. 89-A. Relations between the City of Dumaguete and the Provincial Government of Negros Oriental. — The City of Dumaguete shall remain the capital of the Province of Negros Oriental, unless otherwise provided by law.\n\"All qualified voters of the City of Dumaguete shall be entitled to vote and to be voted upon in all provincial elective positions in accordance with the Revised Election Code.\n\"The Provincial Board of Negros Oriental shall have the right to appeal to the President of the Philippines any or all ordinances approved by the Municipal Board which affect the interests of the province.\n\"In consideration of the privileges and exemptions enjoyed by the Provincial Government within the City and of the responsibilities imposed upon the said city by its continuance as capital of the province, the Provincial Board of Negros Oriental shall create a permanent and continuing annual appropriation of not less than ten thousand pesos to be credited to the general funds of the city. The Auditor General shall enforce the foregoing provision by causing to be transferred to be credit of the City of Dumaguete at the beginning of each year, from any funds in the Provincial Treasury of Negros Oriental, not otherwise appropriated, the sum of ten thousand pesos, unless the Provincial Government shall have previously voted a greater sum."}},{"id":"PH-H1686-A20","no":20,"noLabel":{"en":"Section 20."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 22, 1957."}}],"pack":"ph-p23","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Amending and Repealing Certain Sections of Republic Act Numbered Three Hundred Twenty-Seven, Otherwise Known as the Charter of the City of Dumaguete","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H1687"] = {"id":"PH-H1687","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1957/ra_1853_1957.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"进一步修订第304号共和国法，授权退伍军人使用其欠薪凭证向国家、省、市或市镇政府购买或租赁土地的法案","en":"An Act Further Amend Republic Act Numbered Three Hundred and Four by Authorizing War Veterans to Use Their Back Pay Certificates for the Purchase or Lease of Lands from the National, Provincial, City or Municipal Governments","orig":"An Act Further Amend Republic Act Numbered Three Hundred and Four by Authorizing War Veterans to Use Their Back Pay Certificates for the Purchase or Lease of Lands from the National, Provincial, City or Municipal Governments"},"level":"law","status":"active","topics":["defence"],"docNumber":"Republic Act No. 1853","issuingBody":"Congress of the Philippines","promulgatedDate":"1957-06-22","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1957/ra_1853_1957.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1687-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Section two of Republic Act Numbered Three hundred four, as amended, is further amended to read as follows:\n\"Sec. 2. The Treasurer of the Philippines shall, upon application of all person specified in section one hereof and within one year from the approval of this amendatory Act, and under such rules and regulations as may be promulgated by the Secretary of Finance, acknowledge and file requests for the recognition of the right to the salaries or wages as provided in section one hereof, and notice of such acknowledgment shall be issued to the applicant which shall state the total amount of such salaries or wages due the applicant, and certify that it shall be redeemed by the Government of the Philippines within ten years from the date of their issuance without interest: Provided, That upon application and subject to such rules and regulations as may be approved by the Secretary of Finance a certificate of indebtedness may be issued by the Treasurer of the Philippines covering the whole or a part of the total salaries or wages the right to which has been duly acknowledged and recognized, provided that the face value of such certificate of indebtedness shall not exceed the amount that the applicant may need for the payment of (1) obligations subsisting at the time of the approval of this amendatory Act for which the applicant may directly be liable to the Government or to any of its branches or instrumentalities, or the corporations owned or controlled by the Government, the provisions of their charters, articles of incorporation, by-laws or rules and regulations to the contrary notwithstanding, or to any citizen of the Philippines, or to any association or corporation organized under the laws of the Philippines, who may be willing to accept the same for such settlement; (2) his taxes; (3) government hospital bills of the applicant; (4) lands purchased or leased or to be purchased or leased by him from the national, provincial, city of municipal governments; (5) for the repurchase of properties which have been sold at public auction and sold in favor of the Government; and (6) any amount received by the applicant as gratuity or pension which he has to refund to the Government or to any of its branches or instrumentalities: Provided, further, That such settlement shall be effected by indorsement on the instrument: Provided, furthermore, That no certificate shall be transferred or ceded by indorsement more than once, nor at a discount rate exceeding two per centum per annum: And provided, also, That any person who is not an alien, bank or other financial institution at least sixty per centum of whose capital is owned by Filipinos may, notwithstanding any provision of its charter, articles of incorporation, by-laws, or rules and regulations to the contrary, accept or discount at not more than three and one-half per centum per annum for ten years a negotiable certificate of indebtedness which shall be issued by the Treasurer of the Philippines upon application by a holder of back pay acknowledgment: Provided, furthermore, That in the case of members of the Philippine Army and of recognized guerrilla forces and the Philippine Scouts herein mentioned who may apply for recognition of their back pay salaries, wages, per diems, and/or allowances under the provisions of this amendatory Act, such back pay acknowledgment shall certify that it shall be redeemed by the Government of the Philippines within thirty years from the date of its issuance without interest depending upon the availability of funds which shall be determined by the Treasurer of the Philippines: Provided, finally, That if certificates of indebtedness have been issued to an officer or employee, his back pay at the end of ten years from the date of the approval of this Act, or in the case of members of the Philippine Army and of recognized guerrilla forces and the Philippine Scouts herein mentioned thirty years from the date of the approval of this amendatory Act, shall be equal to the amount due him under the provisions of this Act minus the full and total face value of the certificates of indebtedness issued to him in the interim. Failure to file the application within the time herein provided for will forfeit whatever right there may be to any back salary or wage which otherwise should have been due the applicant.\""}},{"id":"PH-H1687-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 22, 1957."}}],"pack":"ph-p23","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Further Amend Republic Act Numbered Three Hundred and Four by Authorizing War Veterans to Use Their Back Pay Certificates for the Purchase or Lease of Lands from the National, Provincial, City or Municipal Governments","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H1688"] = {"id":"PH-H1688","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1957/ra_1854_1957.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":"在东内格罗斯省Guihulñgan市镇设立职业中学，名称为Guihulñgan职业中学，并为此拨付所需经费的法案","en":"An Act Providing for the Establishment of a Vocational High School in the Municipality of Guihulñgan, Province of Negros Oriental, to be Known as the Guihulñgan Vocational High School and Appropriating the Necessary Funds Therefor","orig":"An Act Providing for the Establishment of a Vocational High School in the Municipality of Guihulñgan, Province of Negros Oriental, to be Known as the Guihulñgan Vocational High School and Appropriating the Necessary Funds Therefor"},"level":"law","status":"active","topics":["education"],"docNumber":"Republic Act No. 1854","issuingBody":"Congress of the Philippines","promulgatedDate":"1957-06-22","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1957/ra_1854_1957.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1688-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There shall be established, under the direct supervision of the Director of Public Schools, a vocational high school in the Municipality of Guihulñgan, Province of Negros Oriental, to be known as the Guihulñgan Vocational High School, to offer courses in trade and agriculture."}},{"id":"PH-H1688-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Upon the recommendation of the Director of Public Schools, the President shall set aside and reserve such portion of the public lands located within the Municipality of Guihulñgan of said province as may be necessary and convenient for the establishment of said high school."}},{"id":"PH-H1688-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The sum of two hundred thousand pesos is hereby appropriated, out of any funds in the National Treasury not otherwise appropriated, for the establishment, operation and maintenance of the said high school during the fiscal year nineteen hundred fifty-eight. Such sums as may be necessary for its operation and maintenance in subsequent years shall be included in the annual General Appropriation Act."}},{"id":"PH-H1688-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 22, 1957."}}],"pack":"ph-p23","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Providing for the Establishment of a Vocational High School in the Municipality of Guihulñgan, Province of Negros Oriental, to be Known as the Guihulñgan Vocational High School and Appropriating the Necessary Funds Therefor","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H1689"] = {"id":"PH-H1689","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1957/ra_1855_1957.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"通过修订第466号联邦法（即国家国内税收法典，经修正）第24条与第32条，使寿险公司适用新所得税基础","en":"An Act to Place Life Insurance Companies on an New Income Tax Basis by Amending Sections Twenty-Four and Thirty-Two of Commonwealth Act Numbered Four Hundred and Sixty-Six, Otherwise Known as the National Internal Revenue Code, as Amended","orig":"An Act to Place Life Insurance Companies on an New Income Tax Basis by Amending Sections Twenty-Four and Thirty-Two of Commonwealth Act Numbered Four Hundred and Sixty-Six, Otherwise Known as the National Internal Revenue Code, as Amended"},"level":"law","status":"active","topics":["tax"],"docNumber":"Republic Act No. 1855","issuingBody":"Congress of the Philippines","promulgatedDate":"1957-06-22","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1957/ra_1855_1957.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1689-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Section twenty-four of Commonwealth Act Numbered Four hundred and sixty-six, otherwise known as the National Internal Revenue Code, as amended, is hereby further amended to read as follows:\n\"Sec. 24. Rate of Tax on Corporations. (A) In general there shall be levied, assessed, collected, and paid annually upon the total net income received in the preceding taxable year from all sources by every corporation organized in, or existing under the laws of the Philippines, no matter how created or organized, but not including duly registered general copartnerships (compañias colectivas), domestic life insurance companies and foreign life insurance companies doing business in the Philippines, a tax upon such income equal to the sum of the following:\n\"Twenty per centum upon the amount by which such total net income does not exceed one hundred thousand pesos; and \"Twenty-eight per centum upon the amount by which such total net income exceeds one hundred thousand pesos; and a like tax shall be levied, assessed, collected, and paid annually upon the total net income received in the preceding taxable year from all sources within the Philippines by every corporation organized, authorized, or existing under the laws of any foreign country: Provided, however, That Building and Loan Associations operating as such in accordance with sections one hundred and seventy-one to one hundred and ninety of the Corporation Law, as amended, as well as private educational institutions, shall pay a tax of twelve per centum and ten per centum, respectively, on their total net income: And, provided, further, That in the case of dividends received by a domestic or resident foreign corporation from a domestic corporation liable to tax under this Chapter or from a domestic corporation engaged in a new and necessary industry, as defined under Republic Act Numbered Nine hundred and one, only twenty-five per centum thereof shall be returnable for purposes of the tax imposed by this section.\n\"(B) Rate of Tax on Life Insurance Companies. There shall be levied, assessed, collected and paid annually from every life insurance company organized in or existing under the laws of the Philippines, or foreign life insurance company authorized to carry on business in the Philippines, but not including purely cooperative companies or associations as defined in section two hundred fifty-five of this code, on the total investment income received by such company during the preceding taxable year from interest, dividends and rents from all sources, whether from or without the Philippines, a tax of six and one-half per centum upon such income: Provided, however, That foreign life insurance companies not doing business in the Philippines shall, on any investment income received by them from the Philippines, be subject to tax as any other foreign corporation.\n\"The total net investment income of domestic life insurance companies is the gross investment income received during the taxable year from rents, dividends, and interest less deductions for real estate expenses, depreciation, interest paid within the taxable year on its indebtedness, except on indebtedness incurred to purchase or carry obligation the interest upon which is wholly exempt from taxation under existing laws, and such investment expenses paid during the taxable year as are ordinary and necessary in the conduct of the investments; and the total net investment income of foreign life insurance companies doing business in the Philippines is that portion of their gross world investment income which bears the same ratio to such income as their total Philippine reserve bears to their total world reserve less that portion of their total world investment expenses which bears the same ratio to such expenses as their total Philippine investment income bears to their total world investment income.\""}},{"id":"PH-H1689-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Section thirty-two of the National Internal Revenue Code, as amended, is hereby further amended to read as follows:\n\"Sec. 32. Special provisions regarding income and deductions of insurance companies, whether domestic or foreign. (a) Special deductions allowed to insurance companies. In the case of insurance companies, except domestic life insurance companies and foreign life insurance companies doing business in the Philippines, the net additions, if any, required by law to be made within the year to reserve funds and the sums other than dividends paid within the year on policy and annuity contracts may be deducted from their gross income: Provided, however, That the released reserved be treated as income for the year of release.\n\"(b) Mutual insurance companies. In the case of mutual fire and mutual employers' liability and mutual workmen's compensation and mutual casualty insurance companies requiring their members to make premium deposits to provide for losses and expenses, said companies shall not return as income any portion of the premium deposits returned to their policy-holders, but shall return as taxable income all income received by them from all other sources plus such portion of the premium deposits as are retained by the companies for purposes other than the payment of losses and expenses and re-insurance reserves.\n\"(c) Mutual marine insurance companies. Mutual marine insurance companies shall include in their return of gross income gross premiums collected and received by them less amounts paid for re-insurance, but shall be entitled to include in deductions from gross income amounts repaid to policy-holders on account of premiums previously paid by them, and interest paid upon such amounts between the ascertainment thereof and the payment thereof.\n\"(d) Assessment insurance companies. In the case of assessment insurance companies, whether domestic or foreign, the actual deposit of sums with the officers of the Government of the Philippines pursuant to law, as additions to guarantee or reserve funds, shall be treated as payments required by law to reserve funds.\""}},{"id":"PH-H1689-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 22, 1957."}}],"pack":"ph-p23","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act to Place Life Insurance Companies on an New Income Tax Basis by Amending Sections Twenty-Four and Thirty-Two of Commonwealth Act Numbered Four Hundred and Sixty-Six, Otherwise Known as the National Internal Revenue Code, as Amended","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H1690"] = {"id":"PH-H1690","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1957/ra_1856_1957.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"修订《国家国内税收法典》 与 204第18388条（经修正）的法案","en":"An Act Amending Sections One Hundred Eighty-Two, One Hundred Eighty-Eight and Two Hundred Four of the National Internal Revenue Code, as Amended","orig":"An Act Amending Sections One Hundred Eighty-Two, One Hundred Eighty-Eight and Two Hundred Four of the National Internal Revenue Code, as Amended"},"level":"law","status":"active","topics":["tax"],"docNumber":"Republic Act No. 1856","issuingBody":"Congress of the Philippines","promulgatedDate":"1957-06-22","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1957/ra_1856_1957.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1690-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Sections one hundred eighty-two, one hundred eighty-eight and two hundred four of the National Internal Revenue Code, as amended, are further amended to read as follows:\n\"Sec. 182. Fixed Taxes. (A) On business (1) Persons subject to percentage tax. Unless otherwise provided, every person engaging in a business on which the percentage tax is imposed shall pay a fixed annual tax of twenty pesos.\n\"(2) Persons not subject to percentage tax. Every person who is not required to pay the percentage tax prescribed in sections one hundred eighty-four, one hundred eighty-five and one hundred eighty-six shall pay in full for each calendar year or fraction thereof in which such person shall engage in business a fixed annual tax based upon his gross annual sales during the preceding calendar year, as follows:\n\"Ten pesos, if the amount of the gross annual sales exceeds two thousand pesos but does not exceed ten thousand pesos;\n\"Twenty pesos, if the amount of the gross annual sales exceeds ten thousand pesos but does not exceed thirty thousand pesos;\n\"Thirty pesos, if the amount of the gross annual sales exceeds thirty thousand pesos but does not exceed fifty thousand pesos;\n\"Fifty pesos, if the amount of the gross annual sales exceeds fifty thousand pesos but does not exceed seventy-five thousand pesos;\n\"Seventy-five pesos, if the amount of the gross annual sales exceeds seventy-five thousand pesos but does not exceed one hundred thousand pesos;\n\"One hundred pesos, if the amount of the gross annual sales exceeds one hundred thousand pesos but does not exceed one hundred fifty thousand pesos;\n\"One hundred fifty pesos, if the amount of the gross annual sales exceeds one hundred fifty thousand pesos but does not exceed three hundred thousand pesos;\n\"Three hundred pesos, if the amount of the gross annual sales exceeds three hundred thousand pesos but does not exceed five hundred thousand pesos; and \"Five hundred pesos, if the amount of the gross annual sales exceeds five hundred thousand pesos: Provided , That if a merchant is engaged in two or more businesses, one or more of which is subject to, and the others exempt from, the percentage tax, he shall pay the graduated fixed annual tax provided above, based on the individual sales of his business not subject to the percentage tax under this title: Provided, however, That the initial graduated fixed annual tax to be paid by the person first engaging in business subject to said tax shall be ten pesos.\n\"This tax shall be payable before the person subject to the same begins to engage in the business, and thereafter within the regulation period in the month of January during which the other fixed privilege taxes may be paid without penalty.\n\"(3) Other fixed taxes. The following fixed taxes shall be collected as follows, the amount stated being for the whole year, when not otherwise specified:\n\"(a) Brewers, one thousand pesos.\n\"(b) Distillers of spirits, one hundred pesos, if the annual production does not exceed fifty thousand gauge liters; two hundred pesos, if the annual production exceeds fifty thousand gauge liters but does not exceed one hundred thousand gauge liters; four hundred pesos, if the annual production exceeds one hundred thousand gauge liters but does not exceed two hundred and fifty thousand gauge liters; and six hundred pesos, if the annual production exceeds two hundred and fifty thousand gauge liters.\n\"(c) Rectifiers of distilled spirit, compounders, and repackers of wines or distilled spirits, four hundred and fifty pesos.\n\"(d) Wholesale peddlers of distilled, manufactured, or fermented liquor, one hundred pesos.\n\"(e) Wholesale peddlers of manufactured tobacco, fifty pesos.\n\"(f) Retail peddlers of distilled, manufactured, or fermented liquor, one hundred and fifty pesos.\n\"(g) Retail peddlers of manufactured tobacco, sixteen pesos.\n\"(h) Wholesale liquor dealers\n1. In the City of Manila, six hundred pesos;\n2. In chartered cities other than Manila, four hundred pesos;\n3. In any other place, one hundred and fifty pesos.\n\"(i) Wholesale dealers in fermented liquors, except basi, tuba and tapuy, one hundred and fifty pesos.\n\"(j) Retail liquor dealers, one hundred pesos.\n\"(k) Retail vino dealers, twenty pesos.\n\"(l) Retail dealers in fermented liquors, fifty peso.\n\"(m) Wholesale leaf tobacco dealers, one hundred pesos.\n\"(n) Retail leaf tobacco dealers, thirty pesos.\n\"(o) Manufacturers of tobacco and manufacturers of cigars and cigarettes.\n1. In the City of Manila, four hundred pesos;\n2. In any other place, one hundred pesos.\n\"(p) Wholesale tobacco dealers, sixty pesos; retail tobacco dealers, sixteen pesos.\n\"(q) Manufacturers or importers of playing cards, two hundred pesos.\n\"(r) Manufacturers, producers, or importers of soft drinks or mineral waters, one hundred pesos.\n\"(s) Stockbrokers, dealers in securities, real estate brokers, real estate dealers, commercial brokers, customs brokers and immigration brokers, one hundred and fifty pesos: Provided, however, That in the case of real estate dealers, the annual fixed tax to be collected shall be as follows:\n\"One hundred and fifty pesos, if the annual income from buying, selling, exchanging, leasing, or renting property (whether on their own account as principals or as owners of rental property or properties) is four thousand pesos or more but not exceeding ten thousand pesos;\n\"Three hundred pesos, if such annual income exceeds ten thousand pesos but does not exceed thirty thousand pesos; and \"Five hundred pesos, if such annual income exceeds thirty thousand pesos.\n\"(t) Owners of race tracks for each day on which races are run on any track, five hundred pesos.\n\"(u) Lending investors\n1. In chartered cities and first-class municipalities, three hundred pesos;\n2. In second and third-class municipalities, one hundred and fifty pesos;\n3. In fourth and fifth-class municipalities and municipal districts, seventy-five pesos; Provided , That lending investors who do business as such in more than one province shall pay a tax of three hundred pesos.\n\"(v) Cinematographic film owners, lessors or distributors, two hundred pesos.\n\"(w) Business agents (agentes de negocios), seventy-five pesos.\n\"(B) On occupation. Taxes on occupation shall be collected as follows, effective January one, nineteen hundred and fifty-seven, the amount stated being the sum due for the whole year:\n\"(1) Lawyers, medical practitioners, architects, interior decorators, certified public accountants, civil, electrical, chemical, mechanical or mining engineers, insurance agents and subagents, veterinarians, dental surgeons, opticians, commercial aviators, professional appraisers or connoisseurs of tobacco and other domestic or foreign products, licensed ship masters and marine chief engineers, seventy-five pesos.\n\"The term 'mechanical engineers', as used herein, means professional mechanical engineers as defined in Commonwealth Act Numbered Two hundred and ninety-four.\n\"(2) Land surveyors, chief mates, marine second engineers, pharmacists, registered nurses, chiropodists, tattooers, masseurs, pelotaris, jockeys, professional actors or actresses, stage performers and hostesses, fifty pesos.\n\"Every professional legally authorized to practice his profession, who has paid the corresponding annual privilege tax on professions as herein imposed, shall be entitled to practice the profession for which he has been duly qualified under the law, in all parts of the Philippines without being subject to any other tax, charge, license or fee for the practice of such profession: Provided, however, That they have paid to the office concerned the registration fees required by their respective professions: Provided, further, That any amount collected in excess of the rates in effect prior to January one, nineteen hundred and fifty-seven, shall be refunded or credited to the taxpayer concerned subject to the provisions of section three hundred and nine of this Code.\"\n\"(C) Exceptions. The following shall be exempt from the tax imposed in this section:\n\"(1) Persons whose gross monthly sales or receipts do not exceed two hundred pesos.\n\"(2) All persons in public market places, selling exclusively domestic meat, fruits, vegetables, game, poultry, fish, and other similar domestic food products.\n\"(3) Peddlers and sellers at fixed stands and other similar selling places engaged exclusively in the sale at retail of domestic meat, fruits, vegetables, game, poultry, fish, and similar domestic food products, whose total stock in trade on any one day does not reach a retail value of one hundred pesos.\n\"(4) Producers of commodities of all classes working in their own homes, consisting of parents and children living as one family, when the value of each day's production by each person capable of working is not in excess of five pesos.\n\"(5) Owners of animal drawn two-wheeled vehicles.\n\"(6) Owners of bancas.\n\"(7) Persons employed in any branch of the service of the Government of the Philippines whose entire professional services are devoted exclusively thereto or are applied under its direction, or persons devoting their entire professional services to any religious, educational, or charitable institution, or hospital, sanitarium, or to any similar establishment, not conducted for private gain, in respect to the tax imposed by paragraph (B) of this section.\"\nSection 188. Transactions and persons not subject to percentage tax. In computing the tax imposed in sections one hundred eighty-four, one hundred eighty-five, and one hundred eighty-six, transactions in the following commodities shall be excluded:\n\"(a) Articles subject to tax under Title IV of this Code.\n\"(b) Agricultural products and the ordinary salt whether in their original form or not when sold, bartered, or exchanged in this country by the producer or owner of the land where produced, as well as all kinds of fish and its by-products when sold, bartered, or exchanged by the fisherman or fishing operator whether in their original state or not.\n\"(c) Minerals and mineral products when sold, bartered or exchanged by the lessee, concessionaire, or owner of the mineral land from which removed.\n\"(d) Articles subject to tax under section one hundred eighty-nine of this Code.\n\"(e) Articles shipped or exported abroad by the manufacturer or producer, irrespective of any shipping arrangement that may be agreed upon which may influence or determine the transfer of ownership of the articles so exported.\n\"The following shall be exempt from the percentage taxes imposed in sections one hundred eighty-four, one hundred eighty-five, and one hundred eighty-six;\n\"(a) Persons whose gross monthly sales or receipts do not exceed two hundred pesos.\n\"(b) All persons in public market places, selling exclusively domestic meat, fruits, vegetables, game, poultry, fish and other similar domestic food products.\n\"(c) Peddlers and sellers at fixed stands and other similar selling places engaged exclusively in the sale at retail of domestic meat, fruits, vegetables, game, poultry, fish, and similar domestic food products, whose total stock in trade in any one day does not reach a retail value of one hundred pesos.\n\"(d) Producers of commodities of all classes working in their own homes, consisting of parents and children living as one family, when the value of each day's production by each person capable of working is not in excess of five pesos.\n\"(e) Persons importing articles under the contract for the exclusive use of the Armed Forces of the Philippines.\"\n\"Sec. 204. Persons subject to tax, to issue sales invoices or receipts. All persons subject to an internal revenue tax, shall, for each sale or transfer of merchandise or for services rendered valued at two pesos or more, prepare and issue sales or commercial invoices or receipts serially numbered in duplicate, showing among other things, their names, or styles, if any, and business addresses: Provided , That in case of sales, receipts or transfers in the amount of fifty pesos or more, the invoices or receipts shall further show the name or style, if any, and business address of the purchaser, customer or client. The original of each sales invoice or receipt shall be issued to the purchaser, customer or client who, if engaged in any taxable business shall keep and preserve the same in his place of business for a period of five years from the date of the invoice or receipt, the duplicate to be kept and preserved by the persons subject to tax, also in his place of business for a like period: Provided , That persons subject to tax, whose gross sales, earnings or receipts during the last preceding year exceed twenty thousand pesos shall, for each sale or transaction, issue an invoice or receipt, irrespective of the value of the article sold or service rendered.\n\"The Collector of Internal Revenue may, in meritorious cases, exempt any person subject to an internal revenue tax, from compliance with the provisions of this section. In any event, public market vendors selling exclusively domestic meat, fruits, vegetables, game, poultry, fish and other domestic food products are hereby exempted from the provisions of this section.\""}},{"id":"PH-H1690-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 22, 1957."}}],"pack":"ph-p23","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Amending Sections One Hundred Eighty-Two, One Hundred Eighty-Eight and Two Hundred Four of the National Internal Revenue Code, as Amended","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H1691"] = {"id":"PH-H1691","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1957/ra_1857_1957.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"将巴拉望省Cuyo市镇Palawan初级中学改设为菲律宾工艺与贸易学校类型的国立工艺与贸易学校，名称为西南区域工艺与贸易学校，并为此拨款","en":"An Act to Convert the Palawan Junior High School in the Municipality of Cuyo, Province of Palawan, into a National School of Arts and Trades, of the Philippine School of Arts and Trades Type, to be Known as the Southwestern Regional School of Arts and Trades, and Appropriating Funds for the Purpose","orig":"An Act to Convert the Palawan Junior High School in the Municipality of Cuyo, Province of Palawan, into a National School of Arts and Trades, of the Philippine School of Arts and Trades Type, to be Known as the Southwestern Regional School of Arts and Trades, and Appropriating Funds for the Purpose"},"level":"law","status":"active","topics":["education","culture"],"docNumber":"Republic Act No. 1857","issuingBody":"Congress of the Philippines","promulgatedDate":"1957-06-22","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1957/ra_1857_1957.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1691-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The Palawan Junior High School, situated in the Municipality of Cuyo, Province of Palawan, is hereby converted into a national school of arts and trades, of the Philippine School of Arts and Trades type, to be known as the Southwestern Regional School of Arts and Trades."}},{"id":"PH-H1691-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The sum of two hundred thousand pesos is hereby appropriated, out of any funds in the National Treasury not otherwise appropriated, for the operation and maintenance of the Southwestern Regional School of Arts and Trades during the school year nineteen hundred fifty-seven to nineteen hundred fifty-eight. Thereafter, the necessary sum for said purpose shall be included in the Annual General Appropriation Act."}},{"id":"PH-H1691-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 22, 1957."}}],"pack":"ph-p23","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act to Convert the Palawan Junior High School in the Municipality of Cuyo, Province of Palawan, into a National School of Arts and Trades, of the Philippine School of Arts and Trades Type, to be Known as the Southwestern Regional School of Arts and Trades, and Appropriating Funds for the Purpose","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H1692"] = {"id":"PH-H1692","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1957/ra_1858_1957.html","fetchedAt":"2026-10-06","articleCount":10,"structureMode":"ARTICLE","title":{"zh":"授予 Philippine Publishers，Inc. 在菲律宾建设、维护和运营广播与电视台特许权的法案","en":"An Act Granting the Philippine Publishers, Inc. a Franchise to Construct, Maintain and Operate Radio Broadcasting and Television Stations in the Philippines","orig":"An Act Granting the Philippine Publishers, Inc. a Franchise to Construct, Maintain and Operate Radio Broadcasting and Television Stations in the Philippines"},"level":"law","status":"active","topics":["investment"],"docNumber":"Republic Act No. 1858","issuingBody":"Congress of the Philippines","promulgatedDate":"1957-06-22","completenessNote":"全文，共 10 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1957/ra_1858_1957.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1692-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Subject to the provisions of the Constitution, the Philippine Publishers, Inc., is hereby granted a franchise, which shall continue in force during the time that the Government has not established similar service at the places selected by the grantee, to construct, maintain and operate, for commercial purposes and in the public interest, radio broadcasting and television stations in the Philippines: Provided, That this franchise shall be void unless the construction of at least one radio broadcasting station or one television station be begun within two years from the date of approval of this Act, and be completed within four years from said date; Provided further, That the grantee shall provide adequate public service time to enable the Government, through the said radio broadcasting and television stations, to reach the population on important public issues; shall assist in the functions of public information and education; shall conform to the ethics of honest enterprise; and shall not use its stations for the broadcasting and/or telecasting of obscene or indecent language, speech, act or scene, or for the dissemination of deliberately false information or willful misrepresentation, or to the detriment of the public health, or to incite, encourage, or assist in subversive or treasonable acts."}},{"id":"PH-H1692-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Such provisions of Act Numbered Thirty-eight hundred and forty-six, entitled \"An Act providing for the regulation of radio stations and radio communications in the Philippine Islands, and for other purposes;\" Act Numbered Thirty-nine hundred and ninety-seven, known as the Radio Broadcasting Law; Commonwealth Act Numbered One hundred and forty-six, known as the Public Service Act, and their amendments, as are applicable to radio broadcasting stations shall be applied, as far as practicable, to the television stations referred to in section one."}},{"id":"PH-H1692-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The grantee shall file a bond in the amount of fifty thousand pesos to guaranty for the full compliance and fulfillment of the conditions under which this franchise is granted."}},{"id":"PH-H1692-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"In the event of any competing individual, partnership or corporation receiving from the Congress a similar franchise in which there shall be any term or terms more favorable than those herein granted or tending to place the herein grantee at any disadvantage, then such term or terms shall ipso facto become a part of the terms hereof and shall operate equally in favor of the grantee as in the case of said competing individual, partnership or corporation."}},{"id":"PH-H1692-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"(a) The grantee shall be liable to pay the same taxes on its real estate, buildings and personal property, exclusive of the franchise, as other persons or corporations are now or hereafter may be required by law to pay.\n(b) The grantee shall further be liable to pay all other taxes that may be imposed by the National Internal Revenue Code by reason of this franchise."}},{"id":"PH-H1692-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"In the event the Government should desire to maintain and operate for itself any or all of the stations herein authorized, the grantee shall turn over such station or stations to the Government with all the serviceable equipment therein, at cost, less reasonable depreciation."}},{"id":"PH-H1692-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"A special right is reserved to the President of the Philippines in time of war, rebellion, public peril, emergency, calamity, disaster or disturbance of peace and order, to cause the closing of said stations or to authorize the temporary use and operation thereof by any department of the Government upon due compensation to the grantee for the use of said stations during the period when they shall be so operated."}},{"id":"PH-H1692-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"The grantee shall not require any previous censorship of any speech, play, act or scene or other matter to be broadcast and/or telecast from its stations; but if any such speech, play, act or scene or other matter should constitute a violation of the law or infringement of a private right, the grantee shall be free from any liability, civil or criminal, for such speech, play, act or scene or other matter: Provided, That the grantee, during any broadcast and/or telecast, may cut off from the air speech, play, act or scene or other matter being broadcast and/or telecast, if the tendency thereof is to propose and/or incite treason, rebellion or sedition, or the language used therein or the theme thereof is indecent or immoral."}},{"id":"PH-H1692-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"The grantee shall not lease, transfer, grant the usufruct of, sell or assign this franchise nor the rights and privileges acquired thereunder to any person, firm, company, corporation or other commercial or legal entity, nor merge with any other company or corporation organized for the same purpose, without the previous approval of the Congress of the Philippines. Any corporation to which this franchise is sold, transferred or assigned, shall be subject to all the conditions, terms, restrictions and limitations of this franchise as fully and completely and to the same extent as if the franchise had been originally granted to the said person, firm, company, corporation or other commercial or legal entity."}},{"id":"PH-H1692-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 22, 1957."}}],"pack":"ph-p23","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Granting the Philippine Publishers, Inc. a Franchise to Construct, Maintain and Operate Radio Broadcasting and Television Stations in the Philippines","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H1693"] = {"id":"PH-H1693","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1957/ra_1859_1957.html","fetchedAt":"2026-10-06","articleCount":7,"structureMode":"ARTICLE","title":{"zh":"在达沃市设立地区医疗与培训中心并为其拨款的法案","en":"An Act to Establish a Regional Medical and Training Center in Davao City and Appropriating Funds Therefor","orig":"An Act to Establish a Regional Medical and Training Center in Davao City and Appropriating Funds Therefor"},"level":"law","status":"active","topics":["health"],"docNumber":"Republic Act No. 1859","issuingBody":"Congress of the Philippines","promulgatedDate":"1957-06-22","completenessNote":"全文，共 7 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1957/ra_1859_1957.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1693-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"A regional medical and training center is hereby established in Davao City."}},{"id":"PH-H1693-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"There is hereby appropriated, out of any funds in the National Treasury not otherwise appropriated, the sum of three million pesos to construct and equip the required buildings for the Davao Regional Medical and Training Center."}},{"id":"PH-H1693-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"After the completion of the new buildings, the funds necessary for the operation and maintenance of this Regional Medical and Training Center and computed at eight to ten pesos per bed per day at the least, shall be included in the yearly appropriation Act: Provided, That the bed capacity of this hospital shall be at least three hundred and fifty beds."}},{"id":"PH-H1693-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Once this Center is in full operation, all patients requiring hospitalization for special medical services in the Mindanao and Sulu areas and who cannot be given such services in their local hospitals shall be referred to the Davao Regional Medical and Training Center."}},{"id":"PH-H1693-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"The supervision and control of the Davao Regional Medical and Training Center is vested in the Secretary of Health, whose power shall be exercised through the Davao Regional Health Director."}},{"id":"PH-H1693-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"All Acts or parts of the Acts inconsistent herewith are hereby repealed or amended."}},{"id":"PH-H1693-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 22, 1957"}}],"pack":"ph-p23","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act to Establish a Regional Medical and Training Center in Davao City and Appropriating Funds Therefor","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H1694"] = {"id":"PH-H1694","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1957/ra_1860_1957.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"修订第409号共和国法（经第1201号与第1571号共和国法修正）第38条与第38-A条并为其他目的法案","en":"An Act to Amend Sections Thirty-Eight and Thirty-Eight-A of Republic Act Numbered Four Hundred Nine, as Amended by Republic Acts Numbered One Thousand Two Hundred One and One Thousand Five Hundred Seventy-One, and for Other Purposes","orig":"An Act to Amend Sections Thirty-Eight and Thirty-Eight-A of Republic Act Numbered Four Hundred Nine, as Amended by Republic Acts Numbered One Thousand Two Hundred One and One Thousand Five Hundred Seventy-One, and for Other Purposes"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 1860","issuingBody":"Congress of the Philippines","promulgatedDate":"1957-06-22","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1957/ra_1860_1957.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1694-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Section thirty-eight of Republic Act Numbered Four hundred nine, as amended by Republic Acts Numbered One thousand two hundred one and One thousand five hundred seventy-one, is hereby further amended to read as follows:\n\"Sec. 38. The City Fiscal and Assistant City Fiscals. — There shall be in the Office of the City Fiscal one chief to be known as the City Fiscal with the rank of a district judge, an assistant chief to be known as the assistant city fiscal, three second assistant city fiscals who shall be the chiefs of divisions, and fifty-two assistant fiscals, who shall discharge their duties under the general supervision of the Secretary of Justice. To be eligible for appointment as City Fiscal one must be a citizen of the Philippines and must have practiced law in the Philippines for a period of not less than ten years or held during a like period an office in the Philippine Government requiring admission to the practice of law as an indispensable requisite. To be eligible for appointment as assistant fiscal one must be a citizen of the Philippines and must have practiced law for at least five years prior to his appointment or held during a like period an office in the Philippine Government requiring admission to the practice of law as an indispensable requisite.\n\"The City Fiscal and his assistants shall receive the salaries hereinafter set forth, which shall be paid by the City of Manila:\n\"(a) City Fiscal, twelve thousand pesos per annum.\n\"(b) First assistant city fiscal, eleven thousand six hundred pesos per annum.\n\"(c) Three second assistant city fiscals who shall be the chiefs of the three divisions, eleven thousand pesos per annum each.\n\"(d) Six assistant fiscals, ten thousand pesos per annum each.\n\"(e) Six assistant fiscals, nine thousand pesos per annum each.\n\"(f) Six assistant fiscals, eight thousand four hundred pesos per annum each.\n\"(g) Six assistant fiscals, eight thousand one hundred pesos per annum each.\n\"(h) Six assistant fiscals, seven thousand six hundred pesos per annum each.\n\"(i) Six assistant fiscals, seven thousand two hundred pesos per annum each.\n\"(j) Six assistant fiscals, six thousand six hundred pesos per annum each.\n\"(k) Ten assistant fiscals, six thousand pesos per annum each.\""}},{"id":"PH-H1694-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Section thirty-eight-A is hereby amended to read as follows:\n\"Sec. 38-A . Organization of the Office into three divisions. -To promote a more efficient performance of the functions and duties of the office, the City Fiscal shall organize said office into three divisions as follows:\n\"(a) Preliminary Investigation Division which shall have exclusive charge of the conduct of preliminary investigations of all crimes and violations of city ordinances.\n\"(b) Prosecution Division which shall have exclusive charge of the prosecution of criminal cases; and \"(c) Miscellaneous Division which shall represent the city in all civil cases wherein the city or any officer thereof in his official capacity is a party, render opinions, draw ordinances when required by the Board, contracts, bonds, and inspect and pass upon all such documents already drawn but pending approval by the city officer concerned.\n\"The City Fiscal shall effect, from time to time, such changes in the organization of the said three divisions as the exigencies of the service demand. This organization shall be without prejudice to the power of the City Fiscal to designate any single assistant fiscal or group of assistant fiscals to investigate and also prosecute the same case or cases: Provided, That notwithstanding any provision herein to the contrary, all of the assistant fiscals occupying the positions affected by the amendments embodied in this Act at time of the approval hereof shall continue to occupy said positions and discharge the duties and functions thereof and receive the corresponding salary increases without the necessity of any new appointment.\""}},{"id":"PH-H1694-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 22, 1957."}}],"pack":"ph-p23","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act to Amend Sections Thirty-Eight and Thirty-Eight-A of Republic Act Numbered Four Hundred Nine, as Amended by Republic Acts Numbered One Thousand Two Hundred One and One Thousand Five Hundred Seventy-One, and for Other Purposes","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H1695"] = {"id":"PH-H1695","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1957/ra_1861_1957.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"授予A.J. Wills先生建设和运营电视台的临时许可，为此修订第767号共和国法的标题与第1条的法案","en":"An Act Granting Mr. A.J. Wills a Temporary Permit to Construct, Maintain and Operate Television Stations, Amending for the Purpose the Title and Section One of Republic Act Numbered Seven Hundred Sixty-Seven","orig":"An Act Granting Mr. A.J. Wills a Temporary Permit to Construct, Maintain and Operate Television Stations, Amending for the Purpose the Title and Section One of Republic Act Numbered Seven Hundred Sixty-Seven"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 1861","issuingBody":"Congress of the Philippines","promulgatedDate":"1957-06-22","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1957/ra_1861_1957.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1695-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Section one of Republic Act Numbered Seven hundred sixty-seven is hereby amended to read as follows:\n\"Sec. 1. There is hereby granted to Mr. A. J. Wills, hereinafter referred to as the \"grantee\" a temporary permit to construct, maintain and operate in the Philippines, at such places as the said grantee may select, subject to the approval of the Secretary of Public Works and Communications, radio broadcasting stations and television stations: Provided, That the holder of the temporary permit herein granted shall start the operation of radio broadcasting stations within three years from the approval of this amendatory Act, and shall start the operation of television stations not later than December thirty-one, nineteen hundred sixty. Failure to comply with this requirement shall ipso facto cancel and avoid the temporary permit."}},{"id":"PH-H1695-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The title of the same Act is hereby amended to read as follows:\n\"An Act granting Mr. A. J. Wills a temporary permit to construct, maintain and operate radio broadcasting stations and television stations in the Philippines.\""}},{"id":"PH-H1695-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 22, 1957."}}],"pack":"ph-p23","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Granting Mr. A.J. Wills a Temporary Permit to Construct, Maintain and Operate Television Stations, Amending for the Purpose the Title and Section One of Republic Act Numbered Seven Hundred Sixty-Seven","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
